window.__D("text/torat-menachem/c019",{"p":[[1400130037,"(הנחה בלתי מוגה)\n<b>כי</b> תשא את ראש בני ישראל גו' ונתנו איש כפר נפשו גו' זה יתנו כל העובר על הפקודים מחצית השקל בשקל הקדש עשרים גרה השקל מחצית השקל תרומה לה'<sup data-n=\"1980\">1</sup>. וידוע הדיוק בזה, מהו אומרו עשרים גרה השקל, הרי צריך רק לתת מחצית השקל, וא\"כ מה נוגע שעשרים גרה השקל. וגם מהו אומרו מחצית השקל תרומה לה', כיון שאומר תחילה זה יתנו גו' מחצית השקל, למה צריך לכפול ולומר מחצית השקל תרומה לה'. ועוד צריך להבין מ\"ש ונתנו איש כפר נפשו, שמזה מובן שמחצית השקל הוא כפרה, וכמ\"ש בסיום הפרשה<sup data-n=\"1981\">2</sup> לכפר על נפשותיכם, והיינו דלבד זאת דמחצית השקל הוא בשביל למנות את ישראל, ה\"ז ג\"כ בשביל כפרה, וזהו שמחצית השקל הוא בשביל עשיית המשכן, שעל זה נצטוו בנ\"י אחר חטא העגל<sup data-n=\"1982\">3</sup>, והיינו שמחצית השקל הוא תיקון על חטא העגל. וצריך להבין, דלכאורה הרי מחצית השקל הו\"ע פרטי, ואיך הוא כפרה על חטא העגל שהוא חטא כללי. ומובן מזה דמחצית השקל הו\"ע כללי, ולכן הוא כפרה על חטא העגל, שהרי הכפרה צ\"ל דוגמת החטא. ויובן כל זה בהקדים תחילה מ\"ש כי תשא את ראש בני ישראל, דלכאורה הול\"ל כי תשא את בנ\"י, ומהו אומרו את ראש דייקא.\nב) <b>והענין</b> בזה<sup data-n=\"1983\">4</sup>, דהנה כתיב<sup data-n=\"1984\">5</sup> החכם עיניו בראשו, ופרש\"י בתחילת הדבר מסתכל מה יהי' בסופה. וזהו ג\"כ מה שאמרו חז\"ל<sup data-n=\"1985\">6</sup> איזהו חכם הרואה את הנולד, שבכל דבר הוא מסתכל ורואה את הנולד מזה. וענין זה הוא עיקר גדול בעבודת ה', דלהיות שקיום המצוות הוא עבודה גדולה וטרחה יתירה, וכמו\"כ הענין דלאכפייא לסט\"א ע\"י המניעה מעבירה הוא עבודה ויגיעה רבה, הנה זה אפשר להיות עי\"זשרואה את הנולד, כמאמר<sup data-n=\"1986\">7</sup> והוי מחשב הפסד מצוה כנגד שכרה, דהפסד המצוה צריך לחשב כנגד שכרה, שההפסד דעכשיו הוא באין ערוך להשכר שיהי' אח\"כ, דההפסד הוא בדברים גשמיים שהם ענינים עוברים, ואילו השכר הוא שכר נצחי, ובפרט לפי המבואר<sup data-n=\"1987\">8</sup> בענין שכר מצוה מצוה<sup data-n=\"1988\">9</sup> דמצוה היא מלשון צוותא<sup data-n=\"1989\">10</sup>, והיינו ששכר המצוה הוא ההתקשרות בעצומ\"ה א\"ס ב\"ה, הרי בודאי שאין ערוך כלל הפסד המצוה לגבי שכרה שיהי' אח\"כ. וכמו\"כ הוא ג\"כ לענין שכר עבירה כנגד הפסדה, דשכר עבירה הוא נופת תטופנה שפתי זרה<sup data-n=\"1990\">11</sup>, הנה צריך לחשב שכר זה כנגד ההפסד, ואחריתה מרה כלענה<sup data-n=\"1991\">12</sup>, אשר גם הפסד זה הוא נצחי, דכמו ששכר המצוה הוא נצחי כנ\"ל, כמו\"כ גם הפסד העבירה הוא נצחי, כמ\"ש בתניא<sup data-n=\"1992\">13</sup> לענין טמטום המוח או טמטום הלב שנעשה ע\"י העבירות, שאף שכבר עשה תשובה נכונה, הרי עיקר התשובה בלב, והלב יש בו בחינות ומדריגות רבות והכל לפי מה שהוא אדם וכו', ומסיים, שהיום לא נתקבלה תשובתו ועונותיו מבדילים, או שרוצים להעלותו לתשובה עילאה יותר כו', ולכן אמר דוד וחטאתי נגדי תמיד<sup data-n=\"1993\">14</sup>, ומזה מובן שהפסד העבירה, אחריתה מרה, הו\"ע נצחי, ובמילא הנה שכר העבירה אינו נחשב לכלום כנגד הפסדה. ועי\"ז שמחשב הפסד מצוה כנגד שכרה ושכר עבירה כנגד הפסדה, מחשב ורואה מה שיהי' בסופו, שזהו ע\"ד מ\"ש איזהו חכם הרואה את הנולד, אזי יקיים את המצוות, מבלי הבט על גודל היגיעה שבדבר. וזהו שמצינו במדות שמנו חכמים, שר\"ש בן נתנאל שהי' מדתו ירא חטא<sup data-n=\"1994\">15</sup>, אמר<sup data-n=\"1995\">16</sup> איזו היא דרך טובה שידבק בה האדם הרואה את הנולד, דכיון שהי' ירא חטא בחר בהרואה את הנולד, שעי\"ז יהי' ירא חטא ולא יחטא לעולם<sup data-n=\"1996\">17</sup>. דהנה, יראת חטא אינה היראה מפני העונשים ושארי הענינים הבאים מצד העבירות, כי אם היראה מצד עצם החטא<sup data-n=\"1997\">18</sup>, דחטא הוא מלשון חסרון<sup data-n=\"1998\">19</sup>, והיינו שע\"י העבירה יחסר לו תמיד ההתקשרותבעצומ\"ה. ובכדי שיהי' ירא חטא, והיינו שיהי' ירא מכל ענין של חטא, גם דקדוק קל של דברי סופרים, וגם ענין שהוא לפנים משורת הדין, וגם ענין קדש עצמך במותר לך<sup data-n=\"1999\">20</sup>, שעי\"ז יחסר לו תמיד ההתקשרות בעצומ\"ה, הנה יראה זו באה ע\"י שרואה את הנולד.\n<b>אמנם</b> עדיין צריך להבין הדיוק החכם עיניו בראשו, דלכאורה, ע\"פ הנ\"ל שהכוונה היא להענין דהרואה את הנולד, שרואה בראשיתו של דבר מה שיהי' בסופו, הי' צריך לומר החכם עיניו בסופו, ומהו אומרו החכם עיניו בראשו דוקא. אך הענין הוא, שראשו קאי על בחינת המקיפים דנשמה, שמשם נמשך הענין דהרואה את הנולד, להיות ירא חטא (שירא מעצם החטא שהוא היפך האלקות), דיראת חטא באה מיראת הרוממות דוקא, שהיא בכח החכמה שבנפש, והיינו בפנימיות החכמה, שהו\"ע ראיית מהות האלקות. וזהו\"ע איזהו חכם הרואה את הנולד, הרואה דייקא, היינו, שלא מספיק שמיעה לבד, שענינה הבנה והשגה, שמע הוא מלשון הבנה<sup data-n=\"2000\">21</sup>, כי, בשכל בלבד, הנה אף שעכשיו הוא מבין, מ\"מ יכול להיות עוד שכל שיסתור את השכל הקודם, ולכן מצד השכל לבדו אפשר להיות אחיזה ללעו\"ז, ולכן צ\"ל בחינת ראי' דוקא, שהו\"ע ההתאמתות בהדבר כמו שרואה בראי' חושית בעיני בשר, דאף שעכשיו לא ישנו הדבר ויבוא אח\"כ, מ\"מ ה\"ז אצלו כאילו הוא כבר רואה את הדבר בעיני בשר. וענין זה אי אפשר להיות כי אם ע\"י בחינת המקיפים שבנפש דוקא, דהכחות פנימיים בלבד אינם מספיקים, להיות שכנגד הכחות פנימיים דקדושה שבאים בהתלבשות, ישנם כחות דלעו\"ז המנגדים על הכחות דקדושה, ורק מצד הכחות מקיפים דקדושה שאין עליהם מנגד, בבואה דבבואה לית להו<sup data-n=\"2001\">22</sup>, אפשר להיות הרואה את הנולד. וזהו מ\"ש החכם עיניו בראשו דייקא, כי דוקא ע\"י ראשו שהוא בחינת המקיפים שבנפש, יכול להיות רואה את הנולד, שעי\"ז יבוא ליראת חטא.\n<b>ועוד</b> פירוש בהמאמר החכם עיניו בראשו, כמ\"ש בזהר<sup data-n=\"2002\">23</sup> (ומובא בתניא<sup data-n=\"2003\">24</sup>) שכל חכם עינוי ומילוי ברישי' אינון בההוא דשריא על רישי', דשכינתא שריא על רישי', שלכן תנן לא יהך בר נש בגילוי' דרישא, דשכינתא דשריא על רישי' (שלכן צ\"ל הענין דקבלת עול, וגילויהראש הוא היפך דקב\"ע). והיינו שראש קאי על השכינה, כמ\"ש<sup data-n=\"2004\">25</sup> לגבי משיח עלה הפורץ לפניהם גו' ויעבר מלכם לפניהם והוי' בראשם. והיינו, שלפירוש הא' קאי ראשו על בחינת המקיפים בנפש, שעי\"ז רואה את הנולד, ובא לידי יראת חטא, שלא יהי' חסרון בהתקשרותו לעצומ\"ה, כנ\"ל. ולפי' הב' קאי ראשו על השכינה, והפירוש דחכם עיניו בראשו הוא, שהזהירות בקיום המצוות הוא מצד ראשו שהוא השכינה, שלא לגרום ענין של חסרון ופגם למעלה.\nג) <b>ועד\"ז</b> מצינו במדרש<sup data-n=\"2005\">26</sup> ב' פירושים במ\"ש<sup data-n=\"2006\">27</sup> בנבואת זכרי' ראיתי והנה מנורת זהב כולה וגולה על ראשה, חד אמר גולה וחד אמר גאולה. מאן דאמר גולה, שגולה לבבל וגלת שכינה עמהן כו', ומאן דאמר גאולה, פרוקא כו' וכתיב עלה הפורץ לפניהם גו' וה' בראשם. והענין בזה, דפירוש הא' הוא דגולה הוא לשון גלות, היינו שגם בזמן הגלות, במעמד ומצב דחושך כפול ומכופל כו', נקראים נשמות ישראל בשם מנורת זהב, ומדגיש בכתוב מנורת זהב כולה, שכל הנשמות, עד ירכה עד פרחה<sup data-n=\"2007\">28</sup>, היינו מהפשוט שבפשוטים עד הגדול שבגדולים<sup data-n=\"2008\">29</sup>, הם מנורת זהב. וטעם הדבר הוא מפני שגולה על ראשה, שגם בזמן הגלות נמצאת השכינה עמהם, דגלו לבבל שכינה עמהם<sup data-n=\"2009\">30</sup>, דשכינה עמהם קאי על נקודת היהדות שישנה בכאו\"א מישראל<sup data-n=\"2010\">31</sup>, דנקודת היהדות היא באופן שלעולם אינה נטמאת ח\"ו (זי ווערט קיינמאָל ניט נטמא ח\"ו), דאע\"ג דאזיל הכא והכא דיוקנא אשתאר בך<sup data-n=\"2011\">32</sup>, ועז\"נ<sup data-n=\"2012\">33</sup> וכבודי לאחר לא אתן, ומצד זה הנה גם בזמן הגלות כתיב מנורת זהב כולה. ופירוש הב' הוא, דגולה הוא לשון גאולה, והפירוש דגולה (גאולה) על ראשה הוא, שסיבת הגאולה דבנ\"י (דאף שישנו זמן הגלות, מ\"מ תהי' הגאולה) הוא מצד גאולת השכינה (ראשה), שע\"י יציאת השכינה מהגלות תהי' גם יציאת בנ\"י מהגלות (די שכינה וועט דאָך אַרויסגיין פון גלות, וועט זי מיט שלעפּן אלעמען). ויש לקשר ב' הפירושים, שהגאולה היא מצד זה גופא שגם בזמן הגלות נקראים בנ\"י מנורת זהב כולה, שזהו מצד נקודת היהדות שבכאו\"א מישראל, שזהו\"ע דגלו לבבל שכינה עמהם. וע\"דמ\"ש אני הוי' אלקיכם אשר הוצאתי אתכם מארץ מצרים<sup data-n=\"2013\">34</sup>, והיינו דטעם הגאולה ממצרים הוא מפני שאני הוי' אלקיכם, דאלקיכם הוא כוחכם וחיותכם, והכח והחיות של ישראל הוא אני הוי', אני הוא ולא אחר<sup data-n=\"2014\">35</sup>, ועי\"ז נמשך להיות יציאת מצרים, היציאה מהגלות<sup data-n=\"2015\">36</sup>. והנה, שני הפירושים בענין וגולה על <i>ראשה</i>, הם בהתאם לשני הפירושים בענין החכם עיניו <i>בראשו</i>. הפירוש שהחכם עיניו בראשו קאי על בחינת המקיפים שבנשמה, מתאים להפירוש שגולה על ראשה קאי על נקודת היהדות שהיא בשלימות בכאו\"א מישראל גם בזמן הגלות. והפירוש שהחכם עיניו בראשו קאי על השכינה, מתאים להפירוש שגולה על ראשה קאי על הגאולה שתהי' ע\"י גאולת השכינה, שראשה הוא שכינה.\nד) <b>והנה</b> יש גם ב' פירושים במארז\"ל<sup data-n=\"2016\">37</sup> אין עומדין להתפלל אלא מתוך כובד ראש. פירוש הא' הוא פירוש הרב המגיד<sup data-n=\"2017\">38</sup> דראש קאי על השכינה, והתפלה צריכה להיות על הכובד שבראש, היינו, על החסרון דלמעלה. דהנה, אף שהמצות עשה דתפלה היא שיתפלל האדם ויבקש בעת מן העתים אשר יצטרך לדבר מן הדברים כמו בעת צרה וכיוצא<sup data-n=\"2018\">39</sup>, שואל צרכיו שהוא צריך להם<sup data-n=\"2019\">40</sup>, בני חיי ומזוני, שזוהי המצות עשה שציוונו הש\"י שיבקש האדם זה ממנו ית', כיון שלו לבדו היכולת להושיע, ובמילא האָט ער ניט באַ קיינעם וואָס צו בעטען, רק צריך להתפלל להוי', והיינו שהתפלה היא למלאות את חסרונותיו, מ\"מ, צ\"ל אופן התפלה לא על מה שחסר לו, אלא שיתפלל על כובד ראש שלמעלה, והיינו שיתמלא החסרון שלמעלה. דהנה, כשיש חסרון למטה יש גם חסרון למעלה, כמארז\"ל<sup data-n=\"2020\">41</sup> בשעה שאדם מצטער שכינה מה לשון אומרת קלני מראשי קלני מזרועי [ויש לבאר דיוק הלשון ראשי וזרועי דוקא, שראש וזרוע הם מקום הנחת התפילין, ואמרו חז\"ל<sup data-n=\"2021\">42</sup> תפילין דמארי עלמא מה כתיב בהו ומי<sup data-n=\"2022\">43</sup> כעמך ישראל גו', ולכן, כשישראל מצטערים אומר הקב\"ה קלני מראשי קלני מזרועי דוקא], ולזה צ\"ל התפלה על החסרון דלמעלה, וכאשר יתמלא החסרון שלמעלה, אזי במילא יתמלאגם החסרון למטה, דכיון שכללות החסרון למטה הוא מצד החסרון למעלה, לכן כשיתמלא החסרון שלמעלה יתמלא ממילא החסרון למטה.\n<b>וביאור</b> הענין, דהנה כללות התהוות העולמות היא ע\"י צמצום הראשון שהוא חסרון האור, כמ\"ש בע\"ח<sup data-n=\"2023\">44</sup> דקודם הצמצום הי' אוא\"ס ממלא את מקום החלל, ולא הי' אפשר להיות התהוות העולמות, ורק ע\"י הצמצום שהוא חסרון האור נעשה התהוות העולמות. וחסרון האור (החסרון דלמעלה) הוא הסיבה לכל החסרונות שיש בעולמות (החסרון למטה). אך ע\"י עבודת האדם נעשה מילוי החסרון שלמעלה (ובמילא מתמלא החסרון שלמטה), והוא ע\"י המשכת אור נעלה יותר מהאור שהי' ממלא את מקום החלל קודם הצמצום, כמ\"ש בעמה\"מ<sup data-n=\"2024\">45</sup>, דזהו מ\"ש<sup data-n=\"2025\">46</sup> ויניחהו בגן עדן לעבדה ולשמרה, ויניחהו הוא מלשון נחת רוח<sup data-n=\"2026\">47</sup>, להיות שע\"י עבודת האדם, לעבדה רמ\"ח מ\"ע ולשמרה שס\"ה ל\"ת<sup data-n=\"2027\">48</sup>, נמשך אור נעלה יותר מהאור שהי' קודם הצמצום, שע\"י אור זה דוקא הוא מילוי החסרון. והענין בזה, דהנה התהוות העולמות הוא מראשית הקו כמו שהוא לפני הצמצום, שהוא אור הממלא, כמאמר הי' ממלא את החלל, דבאור זה שייך חסרון הצמצום, והוא הסיבה להחסרונות דחטא עה\"ד וחטא העגל, ולכן מצד אור זה אי אפשר להיות מילוי החסרון, כי אם ע\"י המשכת האור שלמעלה מהאור שהי' ממלא מקום החלל, שהוא אור הסובב ולמעלה יותר, שבאור זה לא שייך ענין החסרון, ולכן ע\"י המשכת אור זה דוקא נעשה מילוי החסרון. והמשכת אור זה הוא ע\"י קיום התומ\"צ, כי ע\"י קיום התומ\"צ נעשה יחוד קוב\"ה ושכינתי' (שלכן אומרים קודם קיום המצוות לשם יחוד קוב\"ה ושכינתי')<sup data-n=\"2028\">49</sup>, שהו\"ע המשכת אור הסובב<sup data-n=\"2029\">50</sup>, וזהו ויניחהו בג\"ע לעבדה ולשמרה, דע\"י העבודה דלעבדה זו רמ\"ח מ\"ע ולשמרה שס\"ה ל\"ת, נעשה ויניחהו מלשון נח\"ר, כיון שנמשך האור שלמעלה יותר מהאור שהי' קודם הצמצום, שעל ידו הוא מילוי החסרון. והנה, להיות שמילוי החסרון הוא ע\"י המשכת האורכנ\"ל, וכל מילוי בא ע\"י שמחה, לזאת אין עומדין להתפלל אלא מתוך שמחה<sup data-n=\"2030\">51</sup>, דשמחה גורם הגילוי, ועי\"ז הוא מילוי החסרון. וזהו פירוש הה\"מ במארז\"ל אין עומדין להתפלל אלא מתוך כובד ראש, שכאשר יש חסרון למטה, צריך להתפלל שיתמלא החסרון שלמעלה, שהוא ע\"י המשכת אור שאין שייך בו חסרון כלל, והוא ע\"י השמחה, דעי\"ז מתמלא החסרון שלמעלה, ובמילא נמשך גם למטה בבני חיי ומזוני רויחי.\nה) <b>ופירוש</b> הב' במארז\"ל אין עומדין להתפלל אלא מתוך כובד ראש, הוא פירוש כ\"ק אדמו\"ר הזקן<sup data-n=\"2031\">52</sup>, דראש קאי על נשמות ישראל, דישראל הוא ל\"י רא\"ש<sup data-n=\"2032\">53</sup>, דהנה, כל הנבראים שרשם הוא מהדבור, כמ\"ש<sup data-n=\"2033\">54</sup> בדבר הוי' שמים נעשו, ונש\"י שרשם ממחשבה, כמאמר<sup data-n=\"2034\">55</sup> נש\"י עלו במחשבה, מדריגה עליונה שבמחשבה<sup data-n=\"2035\">56</sup>, וזהו שנש\"י הם ראש. וענין כובד ראש הוא הכובד שבבחינת לי ראש.\n<b>וביאור</b> הענין, דהנה כתיב<sup data-n=\"2036\">57</sup> שמע ישראל גו' ואהבת את הוי' אלקיך, וידועה הקושיא בזה<sup data-n=\"2037\">58</sup> הלא אהבה היא הרגש הלב, ואיך שייך ציווי על זה, אך הענין הוא, דהציווי אינו על האהבה, כי אם על ההתבוננות בדברים המעוררים את האהבה, דע\"י שמתבונן בדברים המעוררים את האהבה, הנה אם רק לא יהי' לו מניעות מבחוץ (אשר גם ענין זה גופא תלוי בו), אזי בודאי יבוא לאהבה. ובזה יובן מ\"ש ואהבת, דלכאורה, מאחר שאין הציווי על האהבה כי אם על ההתבוננות, למה נאמר ואהבת, אך הענין הוא, דלהיות דכאשר יתבונן בדברים המעוררים את האהבה בודאי יבוא לידי אהבה, לזאת נאמר ואהבת. וטעם הדבר שע\"י ההתבוננות יהי' לו בודאי אהבה, הוא, כמ\"ש לעיל מיני', שמע ישראל הוי' אלקינו הוי' אחד. דהנה, ישראל הוא לי ראש, והוי' אלקינו היינו שהוי' הוא אלקינו, דהוי' הוא הי' הוה ויהי' כאחד<sup data-n=\"2038\">59</sup> שהוא למעלהמהעולמות, והוי' הוא אלקינו, כחנו וחיותנו. וזהו שבפסוק זה נאמר ב\"פ הוי', הוי' אלקינו הוי' אחד, הוי' אחד הוא הוי' ששייך לעולמות ששייך שיהי' בו פירוד, שלכן צריכים לשלול ולומר הוי' אחד, והוי' אלקינו הוא הוי' שלמעלה מהעולמות. והנה, הוי' אחד הוא בחינת דבור, והו\"ע ד' רבתי דאחד (כמ\"ש בשו\"ע<sup data-n=\"2039\">60</sup>), שהוא מקור הדיבור, והוי' אלקינו הוא בחינת מחשבה. וזהו הוי' אלקינו, שהוי' שלמעלה מהעולמות, בחינת מחשבה, הוא כחנו וחיותנו, דנש\"י עלו במחשבה, ובנים אתם להוי' אלקיכם<sup data-n=\"2040\">61</sup>, ולכן, כמו שהבן בטבעו אוהב את אביו, כמו\"כ יש בנש\"י אהבה טבעית ועצמית לאלקות. ולהיות שבטבע ישנה האהבה לאלקות, וצריך רק לגלותה מן ההעלם אל הגילוי ע\"י ההתבוננות, והיינו, שמצד העלם והסתר הגוף ונה\"ב צריך להתבוננות כדי להסיר את ההעלם, לכן, כאשר מתבונן בודאי יהי' לו אהבה, כיון שההתבוננות אינה אלא לגלות את האהבה שישנה בעצם.\n<b>אמנם</b> אע\"פ שמצד היות בני ישראל בבחינת ראש הרי בודאי שע\"י ההתבוננות יבואו לאהבה, מ\"מ, יכול להיות מצב של כובד ראש, שהו\"ע טמטום המוח והלב, שגם כאשר מתבונן כו' אינו בא לאהבת ה'. וענין זה נעשה ע\"י העוונות, כמ\"ש<sup data-n=\"2041\">62</sup> כי עוונותי גו' ראשי גו' כבד, ולא רק עוונות ממש, אלא גם השיקוע בדברים המותרים שמתאוה וחומד להם, כמ\"ש<sup data-n=\"2042\">63</sup> שמנת עבית כשית, הנה זה פועל העלם והסתר וכיסוי נוסף על הנשמה, שגם כאשר מתבונן באלקות מ\"מ לא יהי' לו אהבה, והיינו שנעשה אצלו טמטום המוח, דגם כאשר מתבונן כו', אינו מרגיש (ער דערהערט ניט) את הענין האלקי, ועוד יותר, דגם כאשר אין לו טמטום המוח ומרגיש במוחו את הענין האלקי, מ\"מ יש לו טמטום הלב, והיינו שאין זה שייך להתעוררות המדות ואין זה נוגע לפועל. והתיקון לזה הוא ע\"י התפלה מתוך כובד ראש כפשוטו, וכדפירש\"י הכנעה ושפלות, והיינו שמתבונן במעמדו ומצבו אליבא דנפשי' ושע\"י עוונותיו גרם כובד ראש, ומזה מתמרמר מאד, והמרירות נוגעת (רירט אים אָן) עד העצם, כמ\"ש כי עוונותי עברו ראשי, היינו שהמרירות מהעוונות עוברת את הראש ונוגעת עד העצם, וע\"י ההכנעה ושפלות נעשית הסרת ההעלם. ואח\"כ הנה ע\"י השמחה נעשה גילוי האור (כנ\"לסוס\"ד). וזהו סדר העבודה בתקון חצות באופן של מרירות, ואח\"כ לימוד התורה בשמחה.\n<b>וכשם</b> שנת\"ל בפירוש הה\"מ שכובד ראש הוא על החסרון שלמעלה, שמילוי החסרון הוא ע\"י האור שלמעלה יותר מהאור שהי' ממלא החלל, כמו\"כ הוא ג\"כ בפירוש אדמו\"ר הזקן שכובד ראש הוא הכובד שבישראל, הנה ע\"י ההכנעה ושפלות ממשיכים אור שלמעלה יותר מכמו שהי' קודם החטא, לפי שתשובה קדמה לעולם<sup data-n=\"2043\">64</sup>, היינו שהוא אור שלמעלה מהעולם, וע\"י המשכת אור זה דוקא מתמלא חסרון החטא.\nו) <b>והנה</b> נוסף על תיקון הכובד ראש שבישראל, שע\"י ההתבוננות בדברים המעוררים את האהבה יבוא לאהבת הוי', צריכה להיות אהבת הוי' בכל לבבך<sup data-n=\"2044\">65</sup>, כפירוש רז\"ל<sup data-n=\"2045\">66</sup> בשני יצריך, והיינו שהאהבה לא תהי' רק מצד נפש האלקית, אלא גם מצד נפש הבהמית, שגם נה\"ב תבוא לאהבה את הוי'. וסדר העבודה בזה, דהנה כתיב<sup data-n=\"2046\">67</sup> וייצר ה\"א את האדם עפר מן האדמה, וייצר בשני יודי\"ן, ואיתא בגמרא<sup data-n=\"2047\">68</sup> ב' דעות, חד אמר דו פרצופין ברא הקב\"ה באדם, שנאמר<sup data-n=\"2048\">69</sup> אחור וקדם צרתני, וחד אמר שני יצרים ברא הקב\"ה, אחד יצר טוב ואחד יצר רע. והנה, כשם שלמ\"ד דו פרצופין ברא הקב\"ה באדם, הרי היו דבוקים אחור באחור, והוצרך להיות ענין הנסירה, ואח\"כ הי' יכול להיות יחוד פנים בפנים לצורך ההולדה, כך גם למ\"ד שני יצרים ברא הקב\"ה צ\"ל ענין הנסירה כדי שיהי' יחוד פנים בפנים. והענין בזה, דהנה, התלבשות הנשמה בגוף ונה\"ב אינו כמו אדם המתלבש בלבוש שהלבוש נפרד ממנו, אלא זוהי התלבשות פנימית, והיינו, שנה\"א דבוקה בנה\"ב, וכמו בדו פרצופין שדבוקים אחור באחור שזה מושך לכאן וזה מושך לכאן (דער שלעפּט אַהער און דער שלעפּט אַהין), ולזאת צריך להיות ענין הנסירה, להפריד ולהבדיל המדות דנה\"ב מנה\"א, ואח\"כ אפשר להיות היחוד דנה\"ב עם נה\"א, שגם נה\"ב תבוא לאהבה את ה'. והיינו, דציור הרע שבו מתלבש כח המתאוה דנה\"ב, צריכים לבטלו, אבל הנה\"ב עצמה, שהוא הכח המתאוה, אין צריך לבטלו<sup data-n=\"2049\">70</sup>, שהרי יש בו מעלה כו', וכמ\"ש<sup data-n=\"2050\">71</sup> ורבתבואות בכח שור, אלא העבודה היא לפעול שגם הוא יבוא לאהבה את הוי', שזהו\"ע היחוד דנה\"ב עם נה\"א.\n<b>אך</b> כדי להפריד המדות דנה\"ב ולהפכם לקדושה שגם הנה\"ב יבוא לאהבה את הוי', הנה עז\"נ אחור וקדם צרתני ותשת עלי כפכה. דהנה, בריאת האדם היא באופן שמצד נה\"ב הוא אחור למעשה בראשית, ומצד נה\"א הוא קדם למעשה בראשית<sup data-n=\"2051\">72</sup>. והכוונה שנברא באופן כזה היא כדי שגם הנה\"ב שהוא אחור למע\"ב יבוא לאהבה את הוי'. והכח על זה הוא ותשת עלי כפכה&lt;69&gt;, דכפכה קאי על התורה, כמארז\"ל<sup data-n=\"2052\">73</sup> על הפסוק<sup data-n=\"2053\">74</sup> אדם לעמל יולד, כשהוא אומר כי אכף עליו פיהו<sup data-n=\"2054\">75</sup>, הוי אומר לעמל פה נברא, ומסיק שעמל פה הוא עמל תורה. והענין בזה, שבתורה יש לא רק הענינים דקדושה אלא גם הענינים השייכים לעולם, שהרי התורה מבארת גם סדר ההתהוות, והיינו שבתורה יש לא רק עשרת הדברות, אלא גם העשרה מאמרות, ומכיון שהעשרה מאמרות כתובים בתורה הרי גם הם תורה, ועי\"ז שיש בתורה ענינים השייכים לעולם, הנה בכח זה אפשר לפעול גם בעולם שגם הנה\"ב יהי' לו אהבה לאלקות. והנה, ע\"י היחוד דנה\"ב בנה\"א, שגם הנה\"ב יש לו אהבה לאלקות, נעשית עלי' גם בנה\"א, דאף שהנשמה עצמה אינה צריכה תיקון וכל ירידתה הוא רק לברר את הנה\"ב<sup data-n=\"2055\">76</sup>, מ\"מ, עי\"ז שנה\"א מבררת את הנה\"ב נעשית עלי' גם בנה\"א, שמתעלית למעלה משרשה ומקורה לאשתאבא בגופא דמלכא<sup data-n=\"2056\">77</sup>.\nז) <b>וזהו</b> מ\"ש זה יתנו כל העובר על הפקודים מחצית השקל, ואיתא בזהר<sup data-n=\"2057\">78</sup> מאן דעבר על פיקודא דאורייתא, היינו שגם אלו שעברו על פיקודא דאורייתא, הנה גם בהם אפשר להיות ענין התשובה ובירור נה\"ב, וענין זה נעשה ע\"י מחצית השקל, זה יתנו גו' מחצית השקל, שהוא מחצה מעשרים גרה, והיינו, שהעבודה היא רק בעשר כחות דנה\"ב, שהרי העשר כחות של נה\"א אין צריכים תקון, והעבודה היא רק בעשר כחות דנה\"ב שגם הוא יבוא לאהבה את הוי'. והכח על זה הוא שקל הקודש עשרים גרה השקל, דקאי על התורה שיש בה לא רק עשרת הדברות אלא גם עשרה מאמרות, עשרים גרה, שזהו הכח על נתינתמחצית השקל שהוא בירור נה\"ב. וממשיך בכתוב מחצית השקל תרומה לה', שע\"י העבודה דזה יתנו גו' מחצית השקל, שהו\"ע בירור נה\"ב, נעשה גם מחצית השקל תרומה לה', דתרומה הוא מלשון הרמה<sup data-n=\"2058\">79</sup>, והו\"ע העלי' שנעשית בנה\"א ע\"י בירור נה\"ב. ומקדים בכתוב כי תשא את ראש בני ישראל, דענין הנשיאת ראש הוא היפך הענין דכובד ראש שנעשה ע\"י חטא העגל, שהו\"ע אחד עם חטא עה\"ד, כמובן ממארז\"ל<sup data-n=\"2059\">80</sup> בשעה שבא נחש על חוה הטיל בה זוהמא, ישראל שעמדו על הר סיני פסקה זוהמתן, ובחטא העגל חזרה זוהמתן<sup data-n=\"2060\">81</sup>. והתיקון לזה הוא ונתנו איש כפר נפשו גו' מחצית השקל, שהו\"ע בירור נה\"ב, ועי\"ז נעשה גם מחצית השקל תרומה לה', שנעשה עלי' גם בנה\"א. ועי\"ז נעשה גם תיקון הענין דכובד ראש שלמעלה, שמתמלא החסרון שלמעלה, ועי\"ז מתמלא גם החסרון שלמטה, ונמשך בבני חיי ומזוני רויחי.\n**********",[["1980","1","תשא ל, יב-יג. – חלק מהמאמר שולב ונדפס בלקו\"ש ח\"ד ע' 1196 ואילך."],["1981","2","שם, טז."],["1982","3","תנחומא תרומה ח."],["1983","4","בהבא לקמן – ראה ד\"ה כי תשא פר\"ת (סה\"מ פר\"ת ע' רסג ואילך). וראה גם אוה\"ת תשא ע' א'תתלג ואילך. ח\"ח ע' ג'צז ואילך. ד\"ה כי תשא תרכ\"ח (סה\"מ תרכ\"ח ע' קמו ואילך). תרס\"ה (סה\"מ תרס\"ה ע' קפט ואילך)."],["1984","5","קהלת ב, יד."],["1985","6","תמיד לב, א."],["1986","7","אבות פ\"ב מ\"א."],["1987","8","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא</a> רפל\"ז. פל\"ט (נב, ב). סהמ\"צ להצ\"צ כ, ב בהגהה. \"היום יום\" כ\"ה אייר."],["1988","9","אבות פ\"ד מ\"ב."],["1989","10","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו\"ת בחוקותי מה, ג</a>. סה\"מ תרח\"ץ ע' נב. וש\"נ."],["1990","11","משלי ה, ג."],["1991","12","שם, ד."],["1992","13","פכ\"ט."],["1993","14","תהלים נא, ה."],["1994","15","אבות פ\"ב מ\"ט."],["1995","16","שם מ\"י."],["1996","17","מדרש שמואל לאבות שם. וראה לקו\"ש ח\"ד ס\"ע 1198 ואילך."],["1997","18","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>."],["1998","19","ראה מלכים-א א, כא ובפרש\"י. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380923\" data-slug=\"likkutei-torah\" data-id=\"4001380923\">לקו\"ת שם. נצבים נא, א</a>. סה\"מ קונטרסים ח\"א קצא, ב ואילך. ועוד."],["1999","20","יבמות כ, א."],["2000","21","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370002\" data-slug=\"torah-or\" data-id=\"3901370002\">תו\"א בראשית א, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380391\" data-slug=\"likkutei-torah\" data-id=\"4001380391\">לקו\"ת נשא כ, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380970\" data-slug=\"likkutei-torah\" data-id=\"4001380970\">דרושים לר\"ה סב, ד</a>. ועוד."],["2001","22","יבמות קכב, א. גיטין סו, א. וראה לקו\"ת תצא לו, ג. לז, ג."],["2002","23","ח\"ג קפז, א."],["2003","24","פל\"ה."],["2004","25","מיכה ב, יג."],["2005","26","ויק\"ר ספל\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380452\" data-slug=\"likkutei-torah\" data-id=\"4001380452\">לקו\"ת בהעלותך לה, ג</a>."],["2006","27","זכרי' ד, ב."],["2007","28","בהעלותך ח, ד."],["2008","29","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380441\" data-slug=\"likkutei-torah\" data-id=\"4001380441\">לקו\"ת שם לב, ד</a>."],["2009","30","מגילה כט, א. ספרי מסעי לה, לד."],["2010","31","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380860\" data-slug=\"likkutei-torah\" data-id=\"4001380860\">לקו\"ת תצא לה, סע\"ד</a>."],["2011","32","ראה זוהר ח\"א רמד, סע\"ב ואילך. ח\"ב קיד, א."],["2012","33","ישעי' מב, ח. וראה דרמ\"צ קפה, א. ועוד."],["2013","34","שלח טו, מא."],["2014","35","נוסח הגש\"פ."],["2015","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380517\" data-slug=\"likkutei-torah\" data-id=\"4001380517\">לקו\"ת שלח נא, ב</a>."],["2016","37","ברכות ל, ב."],["2017","38","אור תורה להה\"מ (הוצאת קה\"ת) יט, סע\"ד ואילך. קח, סע\"ג. ועוד."],["2018","39","ראה סהמ\"צ להצ\"צ שרש מצות התפלה פ\"א (דרמ\"צ קטו, א)."],["2019","40","רמב\"ם הל' תפלה פ\"א ה\"א-ב."],["2020","41","סנהדרין מו, א."],["2021","42","ברכות ו, א."],["2022","43","דברי הימים-א יז, כא."],["2023","44","שער א (דרוש עיגולים ויושר) ענף ב."],["2024","45","בתחילתו. וראה גם אוה\"ת בא ע' רסב. המשך תרס\"ו ס\"ע ג ואילך. ע' תקט. ובכ\"מ."],["2025","46","בראשית ב, טו."],["2026","47","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381324\" data-slug=\"likkutei-torah\" data-id=\"4001381324\">לקו\"ת שה\"ש מט, רע\"א</a>."],["2027","48","ראה תיב\"ע עה\"פ. זוהר ח\"א כז, א. ח\"ב קסה, ב. תקו\"ז תכ\"א (סב, א). תנ\"ו (פח, ב). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381322\" data-slug=\"likkutei-torah\" data-id=\"4001381322\">לקו\"ת שם מח, ג</a> ואילך."],["2028","49","פע\"ח שער הזמירות ספ\"ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380941\" data-slug=\"likkutei-torah\" data-id=\"4001380941\">לקו\"ת</a> דרושים לר\"ה נה, ג. ובכ\"מ. וראה סה\"מ מלוקט ח\"ב ע' פב. וש\"נ."],["2029","50","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נח, א</a>). סה\"מ תרנ\"ז ע' רא. עטר\"ת ע' ק ואילך. ד\"ה באתי לגני תשי\"א (סה\"מ מלוקט ח\"א ע' ג. תורת מנחם – התוועדויות ח\"ב ע' 193 ואילך)."],["2030","51","ברכות לא, א."],["2031","52","הובא במקומות שצויינו בהערה 4. וראה מאמרי אדה\"ז: תקס\"ג ח\"ב ע' תקו ואילך; מאמרז\"ל ע' מ."],["2032","53","שער הפסוקים להאריז\"ל וישלח לב, כט. ספר הליקוטים להאריז\"ל ויחי מז, כח. שם מח, ב. פע\"ח שער הלולב פ\"א. סהמ\"צ להצ\"צ טו, ב – בשם הזוהר. ובכ\"מ."],["2033","54","תהלים לג, ו."],["2034","55","ב\"ר פ\"א, ד. וראה לקו\"ת שה\"ש יז, סע\"ד. סה\"מ ה'ש\"ת ע' 17. ובכ\"מ."],["2035","56","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381267\" data-slug=\"likkutei-torah\" data-id=\"4001381267\">לקו\"ת שם לד, ג</a>."],["2036","57","ואתחנן ו, ד-ה."],["2037","58","סהמ\"צ להצ\"צ קצט, א. וראה ספר הערכים-חב\"ד (כרך א) ערך אהבת ה' ס\"א (ע' רסז). וש\"נ."],["2038","59","זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער א (שער עשר ולא תשע) פ\"ט. תניא שעהיוה\"א פ\"ז (פב, א)."],["2039","60","אדה\"ז או\"ח סל\"ב ס\"ב (ממג\"א שם סק\"א)."],["2040","61","פ' ראה יד, א."],["2041","62","תהלים לח, ה."],["2042","63","האזינו לב, טו."],["2043","64","פסחים נד, א. ועוד."],["2044","65","ואתחנן ו, ה."],["2045","66","משנה ברכות נד, א. ספרי ופרש\"י עה\"פ."],["2046","67","בראשית ב, ז."],["2047","68","ברכות סא, א."],["2048","69","תהלים קלט, ה."],["2049","70","ראה לקו\"ת חוקת נו, ג ואילך."],["2050","71","משלי יד, ד. וראה לקו\"ת האזינו עה, ריש ע\"ד. ובכ\"מ."],["2051","72","ראה יהל אור עה\"פ (ע' תקכא ואילך)."],["2052","73","סנהדרין צט, ב. וראה סה\"מ תרפ\"ט ע' 218 ואילך."],["2053","74","איוב ה, ז."],["2054","75","משלי טז, כו."],["2055","76","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>) מעץ חיים שער כו (שער הצלם) פ\"א."],["2056","77","זח\"א ריז, ב."],["2057","78","ח\"ג קכב, א."],["2058","79","ראה אוה\"ת תרומה ס\"ע א'שנה ואילך. סה\"מ תש\"ט ע' 150. ובכ\"מ."],["2059","80","שבת קמו, רע\"א."],["2060","81","זוהר ח\"א נב, ב. ח\"ב קצג, ב."]]],[1400130038,"<h3>מבה\"ח וער\"ח אדר, ה'תשי\"ג.</h3>\nבלתי מוגה\n<b>א</b>. כ\"ק אדמו\"ר שליט\"א אמר את המאמר ד\"ה כי תשא.\n***\n<b>ב</b>. על הפסוק \"אם כסף תלוה\" שבפרשת השבוע<sup data-n=\"2061\">1</sup>, איתא במכילתא<sup data-n=\"2062\">2</sup> \"כל אם ואם שבתורה רשות, חוץ מזה . . חובה ולא רשות, אתה אומר חובה, או אינו אלא רשות, כשהוא אומר העבט תעביטנו<sup data-n=\"2063\">3</sup>, חובה ולא רשות\".\nוההסברה בזה<sup data-n=\"2064\">4</sup> – שכיון שהתורה צריכה ליתן רשות למלוה ליטול משכון מהלוה, הרי זה הוכחה שההלואה היא חובה:\nאם תמצי לומר שההלואה היא רשות, והיינו, שיש לו ברירה שלא להלוות כל עיקר, הרי כשנותן הלואה <i>מרצונו</i>, יכול ליתנה באיזה אופן שירצה – על משכון דוקא, ולמה צריכה התורה <i>ליתן רשות</i> למלוה ליטול משכון מהלוה?\nומזה מוכח שזהו \"חובה ולא רשות\", היינו, שהמלוה <i>חייב</i> ליתן ההלואה, והחידוש הוא – שאעפ\"כ נתנה לו התורה רשות ליטול משכון מהלוה<sup data-n=\"2065\">5</sup>, והיינו, שעם היות המשכון בבעלותו של הלוה, יש למלוה רשות למנוע ממנו את ההשתמשות בו.\n<b>ג</b>. ועוד דיוק במ\"ש \"העבט תעביטנו\" – שגם כאשר יש ללוה כלים (ליתנם בתור משכון), אין המלוה יכול לטעון שהלוה ימכור את כליו, אלא חייב ליתן לו הלואה.\n– ולהעיר, שכל עיקר מצות הלואה הוא באופן שיש ללוה ברירה אחרת, כי, במצב שאין ללוה שום ברירה, הרי החיוב ליתן לו הוא מצד \"וחי אחיך עמך\"<sup data-n=\"2066\">6</sup> (ולא אמרו \"חייך קודמין\" אלא כשביד אחד קיתון שלמים וכו'<sup data-n=\"2067\">7</sup>, שהוא דבר השוה לשניהם בשוה כו'<sup data-n=\"2068\">8</sup>). והחידוש שבמצוה \"אם כסף תלוה\" הוא, שגם כאשר יש ללוה ברירה אחרת, מצוה להלותו.\nומטעם זה צריכה התורה לומר \"ואל ירע לבבך בתתך לו\"<sup data-n=\"2069\">9</sup> – כיון שיש אפשרות שירע לבבו מנתינת ההלואה, בחשבו, שמאחר שיש ללוה כלים, יכול למכרם, וא\"כ, למה לו ליתן לו הלואה, ולכן צריך להזהיר ש\"אל ירע לבבך גו'\".\nוטעם הדבר – כהמשך הכתוב – \"כי בגלל הדבר הזה וגו'\", כפי שדרשו חז\"ל<sup data-n=\"2070\">10</sup> ש\"בגלל\" הוא לשון \"גלגל\", \"גלגל הוא שחוזר בעולם\", אם לא תתן לו אני מהפך את הגלגל כו'.\nועוד זאת, ש\"גלגל\" (\"בגלל\") הוא גם מלשון גלגול, היינו, שיתכן שבגלגול הקודם היית אתה הלוה וחברך (שבא עתה ללות ממך) הי' המלוה, ולכן עליך להלוות לו כו' (לפרוע מה שהלוה לך)<sup data-n=\"2071\">11</sup>.\nוזהו גם מ\"ש \"אם כסף תלוה גו' את העני <i>עמך</i>\", שהעני הוא \"עמך\" (כמותך) – כיון שבגלגול הקודם היית אתה העני הלוה.\n<b>ד</b>. והנה, כיון שהקב\"ה צוה לבנ\"י מצות הלואה, מקיים גם הוא מצוה זו – כדרשת חז\"ל<sup data-n=\"2072\">12</sup> על הפסוק<sup data-n=\"2073\">13</sup> \"מגיד דבריו ליעקב גו'\", \"מה שהוא עושה הוא אומר לישראל לעשות\" – שנותן לישראל כחות שיוכלו לקיים תומ\"צ, והיינו, שנתינת הכחות נקראת הלואה, ותשלום ההלואה הוא ע\"י כללות העבודה.\nוכפי שמבאר כ\"ק מו\"ח אדמו\"ר בהמאמר דיו\"ד שבט דהשנה הקודמת (ליו\"ד שבט תש\"י)<sup data-n=\"2074\">14</sup>, \"שבכדי שיהי' בכח האדם לנהל עסקו (עסק הרוחני) ולהרויח (שזהו\"ע העלי' שנעשית ע\"י העבודה בירידת הנשמה למטה), נותנים לו מלמעלה כחות על זה, והוא בהיתר עיסקא . . (ש)גם להמלוה מגיע תועלת שהוא הגדלת והוספת האור בעולמות שלמעלה וכו'\"<sup data-n=\"2075\">15</sup>.ומזה מובן שכדי שהקב\"ה יתן הלואה לבנ\"י, צריכים בנ\"י לקיים מצות הלואה, היינו, לעסוק הן בהלואה לעני, ליתן לו \"די מחסורו אשר יחסר לו\"&lt;3&gt;, \"אפילו סוס לרכוב עליו כו'\" (אם הי' רגיל בכך)<sup data-n=\"2076\">16</sup>, והן בגמילות חסדים שהיא בין לעניים ובין לעשירים<sup data-n=\"2077\">17</sup>, כיון שגם העשיר זקוק למי שלמטה ממנו,\n– וע\"ד שיש מעלה ברגל על הראש<sup data-n=\"2078\">18</sup>, שלכן נאמר במשה רבינו \"שש מאות אלף רגלי העם אשר אנכי בקרבו\"<sup data-n=\"2079\">19</sup>, שהגילוי דאנכי בקרבו של משה נעשה ע\"י \"רגלי העם\" דוקא<sup data-n=\"2080\">20</sup>, וכמארז\"ל<sup data-n=\"2081\">21</sup> \"כלום נתתי לך גדולה אלא בשביל ישראל\". ועד\"ז בנוגע לאתפשטותא דמשה שבכל דרא ודרא<sup data-n=\"2082\">22</sup>, שכל הגדולה של רבותינו נשיאינו היא בשביל בנ\"י המקושרים אליהם –\nוכאשר יהודי עוסק בהלואה – אזי מלוה הקב\"ה לו, ובמילא, גם אם נמצא במעמד ומצב ירוד עד ש\"החרש הי' לבם\"<sup data-n=\"2083\">23</sup>, אין לו ליפול ברוחו, כי בודאי נותן לו הקב\"ה את הכחות הדרושים להתגבר ולעבוד עבודתו כו'.\n<b>ה</b>. וענין זה מצינו גם בנוגע ל\"מחצית השקל\" – ש\"כל מי שלא יתן ממשכנין אותו ולוקחין עבוטו בעל כרחו\"<sup data-n=\"2084\">24</sup>.\nובהקדמה:\nהסיבה לכך שיש \"מי שלא יתן\" מחצית השקל (שלכן יש צורך למשכן אותו) היא – להיותו \"עני\"; עני בגשמיות כפשוטו, או עני ברוחניות, \"אין עני אלא בדעת\"<sup data-n=\"2085\">25</sup>, שאינו מבין את גודל החשיבות והצורך שבנתינת מחצית השקל.\n– לדעתו, נתינת מחצית השקל היא עשיית טובה לה\"כביכול\"... בה בשעה שהאמת היא שזוהי עשיית טובה <i>לעצמו</i>, ובזה גופא – לא רק טובה לנפש האלקית, אלא גם טובה להגוף, היינו, שזוהי טובתו גם בגשמיות.וההסברה בזה – כמדובר לעיל (בהמאמר<sup data-n=\"2086\">26</sup>) שע\"י התפלה שפועלת מילוי החסרון למעלה, נעשה בדרך ממילא <i>מילוי החסרון למטה</i>, גם בגשמיות.\nויש להוסיף, שענין זה הוא גם כאשר החסרון הוא (לא רק בהמשכה למטה, אלא) גם <i>בשרש</i> למעלה, שאז צריכים להמשיך ממקום נעלה יותר שלמעלה מסדר השתלשלות [ע\"ד שמצינו<sup data-n=\"2087\">27</sup> לגבי רבי אלעזר בן פדת שאמר לו הקב\"ה \"אלעזר בני ניחא לך דאפכי' לעלמא מרישא כו'\"] – הנה ע\"י התפלה, ובפרט תפלה בציבור (וכפי שסיפר כ\"ק אדמו\"ר מהורש\"ב נ\"ע<sup data-n=\"2088\">28</sup> אודות הפירוש ש\"ציבור\" קאי על עשר כחות הנפש), אזי מתמלאים הבקשות גם בנוגע <i>למילוי החסרון למטה בגשמיות</i>, כפי שמצינו<sup data-n=\"2089\">29</sup> ברבי ש\"אחתינהו לר' חייא ובניו (שתפלתן נשמעת), אמר משיב הרוח ונשבה זיקא אמר מוריד הגשם ואתא מיטרא\".\n[אלא, ש\"בזמן הגלות אחר החורבן\" נעשה בלבול בסדר ההמשכה כו', ועל זה אמרו רז\"ל<sup data-n=\"2090\">30</sup> \"אין בידינו לא משלות הרשעים וכו'\", כמבואר באגרת התשובה<sup data-n=\"2091\">31</sup>. אבל מצד סדר ההמשכה, הנה ע\"י מילוי החסרון למעלה נעשה בדרך ממילא גם מילוי החסרון למטה, כנ\"ל].\nאמנם, להיותו \"עני בדעת\", כאמור, אינו מבין כל זה, ובמילא, <i>אינו רוצה</i> ליתן מחצית השקל, או שהוא עני בגשמיות כפשוטו, ובמילא, <i>אינו יכול</i> ליתן.\nוהעצה לזה – ש\"ממשכנין אותו ולוקחין עבוטו בעל כרחו\", דכיון שירצה לפדות את עבוטו, אזי ילוה ממון ליתן מחצית השקל, ויטול את עבוטו. וכיון שלוה ממון בשביל דבר מצוה (ליתן מחצית השקל) – יעזור לו השי\"ת שיוכל לפרוע את ההלוואה, כמארז\"ל<sup data-n=\"2092\">32</sup> שבכגון-דא אומר הקב\"ה \"לוו עלי ואני פורע\".\nומזה מובן הענין ד\"ממשכנין אותו\" ביחס לנתינת מחצית השקל בעבודה הרוחנית, שהו\"ע בירור עשר הכחות (עשר גרה) דנה\"ב (כמדובר לעיל בהמאמר<sup data-n=\"2093\">33</sup>) – שנותנים לו את הכחות הדרושים לעבודה דבירור נה\"ב, שיוכל למלא ולהשלים את כוונת ירידת הנשמה בגוף.<b>ו</b>. ועוד ענין בזה – שממשכנין אותו אפילו בערב שבת<sup data-n=\"2094\">34</sup>.\nוביאור הענין בעבודת האדם:\nכאשר נמצאים בערב שבת, בסמיכות לה\"שנים אשר תאמר אין לי בהם חפץ<sup data-n=\"2095\">35</sup>, אלו ימי המשיח שאין בהם לא זכות ולא חובה\"<sup data-n=\"2096\">36</sup>, היינו, שלא יהי' בהם ענין הבחירה, כיון ש\"את רוח הטומאה אעביר מן הארץ\"<sup data-n=\"2097\">37</sup> – הרי לא נשאר זמן בשביל לנצל את הכחות.\nואעפ\"כ ממשכנין אותו – כי, עבודת התשובה היא בשעתא חדא וברגע חדא<sup data-n=\"2098\">38</sup>, ועל ידה ממלא החסרון למעלה,\nובמילא נמשך גם מילוי החסרון למטה, שנמשכת הברכה בבני חיי ומזוני רויחי.\n[כ\"ק אדמו\"ר שליט\"א אמר, שנוסף לכך שיום הש\"ק זה הוא שבת מברכים החודש, כמו כל שבת מברכים החודש, הרי זה שבת מברכים חודש <i>אדר</i>, ולכן, צריכה להיות איזה הוספה – במשקה, ניגון שמח, או ריקוד].\n***\n<b>ז</b>. בשבת מברכים זה ישנה מעלה נוספת – שהוא גם ערב ר\"ח, \"מחר חודש\", שאין הפסק בין שבת לר\"ח (דלא כבשאר שבת מברכים, שיש הפסק דימי החול בין שבת לר\"ח), ובמילא, ישנם בו ב' המעלות: המעלה דשבת, וגם המעלה דר\"ח.\nובהקדמה – שנוסף לכך שמצינו ביחזקאל<sup data-n=\"2099\">39</sup> שר\"ח אינו נקרא יום המעשה, מצינו גם שמעלתו דומה למעלת שבת (ויו\"ט), כמ\"ש<sup data-n=\"2100\">40</sup> \"מדוע את הולכת אליו היום לא חודש ולא שבת\" [ומ\"ש כאן \"שבת\" – קאי על יו\"ט, שהרי מכאן למדו ש\"חייב אדם להקביל פני רבו ברגל\"<sup data-n=\"2101\">41</sup>], ומזה שהכתוב משוה ר\"ח לשבת, מוכח, שר\"ח הוא במדריגת שבת (יו\"ט).\nוכאמור, בשבת מחר חודש (ששייך כבר לר\"ח) ניתוסף בשבת גם המעלה דר\"ח.<b>ח</b>. וביאור המעלה דראש חודש:\n\"ישראל מונין ללבנה\"<sup data-n=\"2102\">42</sup>. וא' הטעמים לזה – לפי שדומין ללבנה<sup data-n=\"2103\">43</sup>, דכשם שהלבנה היא לפעמים בירידה (בסוף החודש) ופעמים בעלי' (בתחלת החודש), כך ישראל כו'<sup data-n=\"2104\">44</sup>.\nוהענין בזה<sup data-n=\"2105\">45</sup> – שעל ידי זה שלפעמים הלבנה היא בירידה, אזי עלייתה היא בגדלות יותר מהחמה, דאם לא כן, אין מעלה בהלבנה לגבי החמה, שהרי החמה היא תמיד בגדלות, ואילו הלבנה, רק לפעמים היא בגדלות. ועכצ\"ל, שלפעמים הלבנה היא בגדלות יותר מהחמה, וענין זה נעשה עי\"ז שהיא בקטנות ביותר, שאז מתחילה עלייתה להיות בגדלות יותר.\nוזהו שאמרו חז\"ל<sup data-n=\"2106\">46</sup> \"ליקרו צדיקים בשמך (\"המאור הקטן\"), יעקב הקטן . . דוד הקטן\" – כיון שיש מעלה בענין הקטנות (ירידה), שעי\"ז דוקא באים לעלי' גדולה ביותר.\nוע\"ד שמצינו שסותר על מנת לבנות חשיב מלאכה<sup data-n=\"2107\">47</sup>, דאף שזהו ענין של סתירה, מ\"מ, כיון שכוונת הסתירה היא על מנת לבנות, הרי הסתירה עצמה היא בכלל התחלת הבנין, ועד להתחלת בנין נעלה יותר – לעד ולעולמי עולמים – שאי אפשר לבנותו ללא הקדמת הסתירה (דלא כהבנין הקודם שנבנה ללא סתירה, בנין עראי, שעכשיו סותרים אותו)<sup data-n=\"2108\">48</sup>.\nוכן הוא בכללות הענין דירידת הנשמה בגוף, מאיגרא רמה לבירא עמיקתא<sup data-n=\"2109\">49</sup>, ירידה לצורך עלי' – שהעלי' שלאחרי הירידה היא לא רק לה\"איגרא רמה\" שמשם היתה הירידה (דא\"כ לא הי' כדאי כל ענין הירידה), אלא עלי' לדרגא נעלית יותר, שאי אפשר לבוא אלי' לולי הקדמת הירידה<sup data-n=\"2110\">50</sup>.\nומזה מובן גודל המעלה דראש חודש – מולד הלבנה – שבו מתחילה היציאה מהמעמד ומצב של הירידה, ולבוא להעלי' היותר גדולה (שבאה לאחרי הקדמת הירידה).וההוראה מזה – שאין לבוא למעמד ומצב של יאוש ח\"ו כאשר יודעים שנמצאים במצב של ירידה כו'<sup data-n=\"2111\">51</sup>.\n<b>ט</b>. ועוד ענין בראש חודש – שבו נהגו הנשים איסור בעשיית מלאכה<sup data-n=\"2112\">52</sup>.\nוענינו בעבודת האדם – שר\"ח קשור עם הענין דקבלת עול, ספירת המלכות (אשה).\nוהענין בזה – שכאשר הולכים ע\"פ השכל בלבד, יכולים להכשל כו', ויש צורך והכרח בענין הקבלת עול דוקא<sup data-n=\"2113\">53</sup>.\nויש לקשר ענין זה עם המבואר לעיל (בהמאמר<sup data-n=\"2114\">54</sup>) בענין \"זה יתנו גו' מחצית השקל\"<sup data-n=\"2115\">55</sup> – שכללות הענין דבירור נה\"ב (שזהו\"ע מחצית השקל) נעשה (לא ע\"י דרכים משלו (\"אייגענע דרכים\"), אלא) <i>בכח התורה</i> דוקא.\nואלה הטוענים שבזמנינו נתחדשו בעולם דברים חדשים שלא היו בזמן המקרא, בזמן הגמרא והפוסקים כו', ובמילא לא מדובר אודותם בתורה, ולכן צריכים <i>לחדש</i> ענינים חדשים בתורה,\n– כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע כותב בא' הקונטרסים שלו<sup data-n=\"2116\">56</sup> \"ע\"ד הלצה\", שישנם כאלה \"שמחדשים <i>חדושים ממש</i>, היינו מה שלא נאמרו למשה רבינו, כי כל מה שתלמיד ותיק עתיד לחדש נאמר למשה מסיני . . וא\"כ הרי זה רק גילוי ההעלם בלבד ולא דבר חדש מעיקרו . . אבל התלמיד שאינו הגון הנ\"ל מחדש חידושים ממש <i>שלא נאמרו למשה מסיני</i>\"... –\nהנה דעה זו (שיש ענינים שהתורה אינה מדברת אודותם) היא דעה של אפיקורסים (אלא שהם אינם יודעים שזוהי אפיקורסות) – שהרי איתא בזהר<sup data-n=\"2117\">57</sup> \"קוב\"ה אסתכל באורייתא וברא עלמא\", וכן איתא במדרש<sup data-n=\"2118\">58</sup> \"התורה אומרת אני הייתי כלי אומנתו של הקב\"ה\", ועכצ\"ל, שכל הענינים שישנם בעולם – גם ענינים כאלה שלכאורה אין להם שייכות כלל לתורה – ישנם בתורה, ולולי זאת שנמצאים בתורה, לא היו בעולםכלל. ועוד זאת – שעיקר ענין התורה הוא לברר את העולם<sup data-n=\"2119\">59</sup> (וע\"ד שהנשמה עצמה לא צריכה תיקון, וירידתה למטה היא כדי לברר את הגוף ונה\"ב וחלקו בעולם<sup data-n=\"2120\">60</sup>).\nצריכים לידע איפוא שכשם שכאשר מתעוררת שאלה בהלכות בשר בחלב וכיו\"ב, אזי מעיינים בשלחן-ערוך, כמו כן בכל ענין וענין צריכים לעיין בתורה כדי לידע כיצד להתנהג, כולל גם בעניני הרשות.\n– האמת היא שאצל יהודי לא שייך המושג של \"דברי הרשות\", כי אם, חיוב (מצוה) או איסור, אלא שיש ענינים שקודם שבאים במגע עם יהודי ה\"ה \"דברי הרשות\", אבל לאח\"ז צריך להפכם לחלק המצוה<sup data-n=\"2121\">61</sup>.\nובמילא כדי לידע כיצד להתנהג בכל ענין וענין צריכים לעיין בתורה, ובפרט בתורת החסידות שבה ישנם כל הענינים, וכמ\"ש אדמו\"ר הזקן בהקדמה לספר התניא (בנוגע לכניסה ל\"יחידות\") שיש בו \"כל התשובות על כל השאלות\".\n<b>י</b>. בהפטרה ד\"מחר חודש\" נאמר<sup data-n=\"2122\">62</sup> \"ונפקדת כי יפקד מושבך גו'\".\nוהענין בזה – ע\"ד שמצינו שמחשבה מועלת<sup data-n=\"2123\">63</sup>, היינו, שהמחשבה שיהודי חושב על חבירו, ובפרט מחשבה של צדיק ונשיא הדור, מועילה להוציא מן המיצר אל המרחב<sup data-n=\"2124\">64</sup>, ובאופן שנמשך בגשמיות בפועל ממש.\n– שמע\"צ<sup data-n=\"2125\">65</sup> ושמח\"ת תרצ\"ג הי' כ\"ק מו\"ח אדמו\"ר בריגא, והגיע לשם גם אחד מאברכי התמימים שבא מרוסיא. כ\"ק מו\"ח אדמו\"ר דיבר אז בענין מחשבה מועלת, והאברך הנ\"ל, שהי' קצת... – שאל אצל הרבי: \"און וואָס האָט יענער פון דעם\"?\nואחר זמן אמר לו כ\"ק מו\"ח אדמו\"ר: ואי' היית בחג הסוכות שעבר?!...\n**********",[["2061","1","כב, כד."],["2062","2","עה\"פ."],["2063","3","פ' ראה טו, ח."],["2064","4","ברשימת ההנחה חסר הביאור ע\"פ נגלה (המו\"ל)."],["2065","5","ראה אנציק' תלמודית ערך הלואה ע' רטו-ז, ובהנסמן שם."],["2066","6","בהר כה, לו."],["2067","7","ב\"מ סב, א."],["2068","8","תניא אגה\"ק סט\"ז."],["2069","9","פ' ראה טו, יו\"ד."],["2070","10","ראה בחיי עה\"פ – ע\"פ שבת קנא, ב. ועוד."],["2071","11","ראה פרדס דוד עה\"ת פ' ראה שם."],["2072","12","שמו\"ר פרשתנו פ\"ל, ט."],["2073","13","תהלים קמז, יט."],["2074","14","ד\"ה טעמה כי טוב סחרה תש\"ט פ\"א (סה\"מ תש\"ט ע' 28)."],["2075","15","בזכרון אחדים – שנזכר גם הענין דעבודה צורך גבוה (ראה ד\"ה לא תהי' משכלה דש\"פ משפטים אשתקד (תורת מנחם – התוועדויות ח\"ד ע' 324 ואילך. וש\"נ)), וכנראה מקומו כאן (המו\"ל)."],["2076","16","כתובות סז ב. ספרי ופרש\"י עה\"פ. רמב\"ם הל' מתנות עניים פ\"ז ה\"ג."],["2077","17","סוכה מט, ב."],["2078","18","ראה לקו\"ת ר\"פ נצבים. ובכ\"מ."],["2079","19","בהעלותך יא, כא."],["2080","20","ראה ד\"ה וקבל היהודים תרפ\"ז פ\"ה (סה\"מ תרפ\"ז ע' קטו)."],["2081","21","ברכות לב, א."],["2082","22","תקו\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א)."],["2083","23","ראה שבת קמז, ב."],["2084","24","רמב\"ם הל' שקלים פ\"א ה\"ט – משקלים פ\"א ה\"ג."],["2085","25","כתובות סח, סע\"א. נדרים מא, רע\"א."],["2086","26","פ\"ד (לעיל ע' 345 ואילך)."],["2087","27","תענית כה, א."],["2088","28","ראה \"התמים\" ח\"ב ע' מה ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021201\" data-slug=\"likkutei-sichot\" data-id=\"1300021201\">לקו\"ש ח\"ב ע' 477</a> ואילך."],["2089","29","ב\"מ פה, ב (ובפרש\"י)."],["2090","30","אבות פ\"ד מט\"ו."],["2091","31","פ\"ו (צו, ב)."],["2092","32","ביצה טו, ב. שו\"ע אדה\"ז או\"ח סרמ\"ב ס\"ג."],["2093","33","פ\"ז (לעיל ע' 350 ואילך)."],["2094","34","ברשימת ההנחה – שכן איתא בירושלמי (לע\"ע לא מצאנו ענין זה בירושלמי בנוגע למחצית השקל. – ולהעיר מב\"ב ח, ב: \"ממשכנין על <i>הצדקה</i> ואפילו בערב שבת\") – המו\"ל."],["2095","35","קהלת יב, א."],["2096","36","שבת קנא, ב."],["2097","37","זכרי' יג, ב."],["2098","38","זח\"א קכט, סע\"א."],["2099","39","מו, א ובמפרשים שם. וראה גם שמואל-א כ, יט ובמפרשים. לקו\"ת ברכה צו, ד. ובכ\"מ."],["2100","40","מלכים-ב ד, כג."],["2101","41","ר\"ה טז, ב. וש\"נ."],["2102","42","סוכה כט, א."],["2103","43","ראה סוכה שם. ב\"ר פ\"ו, ג. אוה\"ת בראשית ד, סע\"ב ואילך. ועוד."],["2104","44","ראה חדא\"ג מהרש\"א לחולין ס, ב."],["2105","45","ראה אוה\"ת שם יו\"ד, א ואילך."],["2106","46","חולין שם."],["2107","47","ראה שבת לא, ב. ועוד."],["2108","48","ראה גם סה\"מ מלוקט ח\"ד ע' שלד ואילך."],["2109","49","ע\"פ לשון חז\"ל – חגיגה ה, ב."],["2110","50","ראה בלקו\"ת לפי הנסמן ב\"מפתח ענינים\" ערך \"נשמות; ירידה צורך עלי'\"."],["2111","51","חסר המשך הענין (המו\"ל)."],["2112","52","טושו\"ע או\"ח סתי\"ז. וראה גם תורת מנחם – התוועדויות ח\"ב ע' 85 ואילך."],["2113","53","אולי ההמשך להמדובר לעיל הוא שהעלי' מקטנות לגדלות היא ע\"י קב\"ע דוקא (המו\"ל)."],["2114","54","פ\"ו (לעיל ע' 350)."],["2115","55","תשא ל, יג."],["2116","56","קונטרס עץ החיים פל\"א."],["2117","57","ח\"א קלד, סע\"א. ח\"ב קסא, רע\"ב. ח\"ג קעח, א."],["2118","58","ב\"ר בתחלתו."],["2119","59","ראה גם ד\"ה באתי לגני תשמ\"ג (התוועדויות תשמ\"ג ח\"ב ע' 881 ואילך)."],["2120","60","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>) מע\"ח שער כו (שער הצלם) פ\"א."],["2121","61","ראה גם \"רשימות\" חוברת מד."],["2122","62","שמואל-א כ, יח."],["2123","63","ראה לקו\"ד ח\"א בתחלתו."],["2124","64","בזכרון אחדים, ההמשך להמדובר לעיל הוא – שע\"י הענין ד\"ונפקדת גו'\", מחשבה מועלת, נעשית העלי' מקטנות לגדלות, מן המיצר אל המרחב (המו\"ל)."],["2125","65","לקו\"ד שם."]]],[1400140002,"התוועדויות\n(ז' אדר – יום ב' דחג השבועות)"],[1400140003,"– לקבוצת תלמידי הישיבה, בחדרו הק' –\nבלתי מוגה\n<b>א</b>. ידוע מ\"ש באגה\"ק<sup data-n=\"1\">1</sup> ונתבאר בספר השיחות דכ\"ק מו\"ח אדמו\"ר<sup data-n=\"2\">2</sup>, שנוסף על החיוב דכל בנ\"י בכללות התומ\"צ, יש לכל אחד מצוה פרטית שבה צריך להיות \"זהיר טפי\"<sup data-n=\"3\">3</sup>, כיון שמצוה זו היא ה\"שער\"<sup data-n=\"4\">4</sup> שדרכו עולים כל עניני העבודה מלמטה למעלה, ודרכו נמשכים כל ההמשכות מלמעלה למטה.\nונוסף על האמור ששייך לכאו\"א מישראל, הן לתלמידים יושבי אוהל והן לבעלי עסקים – יש בזה עוד ענין השייך במיוחד לתלמידי הישיבה:\nתלמידים שזיכו והביאו אותם ללמוד בישיבה, ובפרט ישיבה כזו שבה לומדים נגלה וחסידות ביחד, והנהלת הישיבה מספקת להם את כל צרכיהם הגשמיים והרוחניים – צריכים לידע שה\"שער\" דרכו עוברים כל עניניהם, הן עניני העליות מלמטה למעלה, והן עניני ההמשכות מלמעלה למטה בגשמיות ורוחניות, הוא – <i>הנהלת הישיבה</i>, אשר, המינוי שלהם הוא – ככל הענינים – בהשגחה פרטית, וכמארז\"ל<sup data-n=\"5\">5</sup> ש\"אפילו ריש גרגיתא מן שמיא מנו לי'\", ועאכו\"כ בנוגע להנהלה של ישיבה, ובפרט הנהלה שנתמנתה והיא באחריותו של כ\"ק מו\"ח אדמו\"ר, נשיא ישראל בכלל ונשיא החסידים בפרט, הרי בודאי שדרכה עולים ונמשכים כל הענינים השייכים לתלמידי הישיבה.\n<b>ב</b>. כלפי מה הדברים אמורים?\nנמסר לי ע\"י הנהלת הישיבה ע\"ד חלישות בענין המשמעת, וברגש האחריות כלפי דרכי וסדרי הישיבה.\nובכן, מה שעבר עבר, ואין צועקין על העבר, אבל מכאן ולהבא צריכים לתקן את הדבר – לקבל את מרות ההנהלה באופן מוחלט,ולשמור את דרכי וסדרי הישיבה בלימוד הנגלה והחסידות בכל מאת האחוזים.\nואם ישנם טענות כלפי ההנהלה על חסרונות כו' – הרי נוסף לכך שיתכן שאינם אלא חסרונות מדומים, הנה גם אם ישנם טענות צודקות, יש להציע את הדברים בפני ההנהלה, אבל בנוגע לפועל יש לציית להנהלת הישיבה – שהרי פשוט שההנהגה במוסד של הרבי צריכה להיות בהתאם לרצונו של הרבי שמינה את הנהלת הישיבה,\nולא לנסות לילך בכח עצמו, בדרך היחיד – כי, נוסף לכך שספק גדול אם יצליחו בכך, ומסתמא, כיון שכ\"ק מו\"ח אדמו\"ר מינה את הנהלת הישיבה, <i>אי אפשר</i> לילך בדרך אחרת, הרי, גם אם מצליחים בסופו של דבר ע\"י הליכה בכח עצמו בדרך היחיד – לשם מה לבזבז כחות בשביל פתיחת פתח בכותל עבה (\"אויסהאַקן אַ טיר דורך אַ גראָבע וואַנט\") בה בשעה שישנו פתח מן המוכן שבו יכולים לילך בדרך המלך, דרך הסלולה לרבים.\n<b>ג</b>. כל האמור נוגע עוד יותר לתלמידים שבאו מארץ ישראל, דכיון שע\"פ דין אסור לצאת מארץ ישראל לחוץ לארץ אלא על מנת ללמוד תורה<sup data-n=\"6\">6</sup> – ורק בתנאי זה קיבלו הסכם מהרבי לבוא לכאן – מוטלת עליהם אחריות כפולה לציית לחלוטין להנהלת הישיבה, ואין להם היתר להתנהג באופן אחר אפילו כי הוא זה, שאז, לא מקיימים את התנאי של הרבי, ועוברים על לא תעשה כו'.\nוכמו כן בנוגע לשאר התלמידים שבאו לכאן מחוץ לארץ, וכן אלה הדרים כאן – שגם הם צריכים לציית לחלוטין להנהלת הישיבה, ולהזהר שלא יהי' אצלם מעמד ומצב ד\"שנה ופירש (לא לגמרי ח\"ו, אלא אפילו רק באופן של ירידה מקדושה יתירה לקדושה פחותה) יותר מכולן\"<sup data-n=\"7\">7</sup>.\n<b>ד</b>. השי\"ת יעזור לכם לקבל על עצמכם החלטות טובות הן בנוגע לשמירת סדרי הישיבה בנגלה ובחסידות, והן בנוגע לכללות ההנהגה גם מחוץ לסדרי הישיבה (בחדר הפרטי או בבית) – כרצונו של הרבי שה\"עול\" של תלמידי הישיבה יהי' גם מחוץ לסדרי הישיבה באותו אופן כמו בסדרי הישיבה.\n– תקותי שלא יהי' צורך בריבוי התבוננות בכהנ\"ל, ובודאי שלאיהי' צורך במסירת נפש גדולה, שהרי גם בשכל אנושי מובן הדבר בפשטות.\nוהעיקר – שלא לדחות את קבלת ההחלטות טובות לאחר ריבוי זמן, אלא לעשות זאת תיכף ומיד, בערב זה.\nועי\"ז תצליחו בכל הענינים, בלימוד הנגלה ובלימוד החסידות, וגם בהסתדרות בגשמיות.\n**********",[["1","1","ס\"ז (קיב, א)."],["2","2","קיץ ה'ש\"ת ע' 22. וראה גם סה\"מ תש\"ח ע' 240."],["3","3","ראה שבת קיח, ב."],["4","4","ראה זח\"א ח, א."],["5","5","ברכות נח, סע\"א."],["6","6","רמב\"ם הל' מלכים פ\"ה ה\"ט."],["7","7","פסחים מט, ב."]]],[1400140004,"<h3>לשלוח לאנ\"ש שי' בכל מרחבי תבל</h3><h3>לקראת ימי הפורים, ה'תשי\"ג</h3>\nשבת זכור וגו' ושמחת פורים והתוועדות פעילה.\n<b>מנחם שניאורסאהן</b>"],[1400140005,"(הנחה בלתי מוגה)\n<b>ויהי</b> אומן את הדסה היא אסתר<sup data-n=\"8\">1</sup>, ואיתא בגמרא<sup data-n=\"9\">2</sup> קרי לה הדסה וקרי לה אסתר, וממשיך בגמרא, למה נקרא שמה הדסה על שם הצדיקים שנקראו הדסים, וכן הוא אומר<sup data-n=\"10\">3</sup> והוא עומד בין ההדסים, ולמה נקראת שמה אסתר, על שם שהיתה מסתרת דברי', שנאמר<sup data-n=\"11\">4</sup> אין אסתר מגדת. ועוד דעה בגמרא שם, למה נקראת אסתר שהיו אומות העולם קורין אותה על שום אסתהר. וצריך להבין מהו ענין ב' השמות דהדסה ואסתר. וגם, מה נוגע איך היו אומות העולם קורין אותה. והענין בזה<sup data-n=\"12\">5</sup>, כידוע<sup data-n=\"13\">6</sup> שאסתר היא ספירת המלכות, ויש בה ב' מדריגות, מדריגה עליונה שנקראת הדסה, ומדריגה תחתונה שנקראת אסתר, ועל זה הוא אומר הדסה היא אסתר, שגם המדריגה התחתונה שנקראת אסתר, היא הדסה<sup data-n=\"14\">7</sup>. וצריך להבין ביאור הענין, והפועל יוצא מזה בעבודה, כידוע מ\"ש כ\"ק מו\"ח אדמו\"ר<sup data-n=\"15\">8</sup> וחזר על זה כמ\"פ דכל ענין ההשכלה הוא רק הקדמה לעבודה, וכל ענין שישנו בהשכלה, אפשר להביא (אַראָפּטראָגן) ממנו בכן בעבודה, ובמילא מוכרחים להביא ממנו בכן בעבודה.\nב) <b>והענין</b> הוא, דהנה איתא בגמרא<sup data-n=\"16\">9</sup> אסתר מן התורה מנין דכתיב<sup data-n=\"17\">10</sup> ואנכי הסתר אסתיר פני ביום ההוא, והיינו שהפנים דלמעלה (פני) הם בבחינת הסתר. דהנה, אף שאין לו גוף ואין לו דמות הגוף<sup data-n=\"18\">11</sup>, מ\"מ הרי ידוע שיש למעלה בחינת פנים ימין שמאל ואחור. וזהו מ\"ש אסתיר פני, היינו שבבחינת הפנים למעלה יש כמו שהוא בגילוי ויש כמו שהוא בהסתר. והענין בזה, דפנים הוא בחינת מלכות דאצילות (כדלקמן), ויש בה ב' מדריגות, כמו שהיא באצילות, שאז נקראת הדסה ע\"שהצדיקים, דלהיות שבאצילות כתיב<sup data-n=\"19\">12</sup> לא יגורך רע, לכן כמו שהיא באצילות נקראת הדסה ע\"ש הצדיקים, ויש כמו שהמלכות נעשית עתיק לבריאה שאז היא בהסתר, ואז נקראת אסתר ע\"ש שמסתרת דברי'. ועל זה אומר הדסה היא אסתר, היינו שגם בחינת מלכות כמו שנעשית עתיק לבריאה ומשתלשלת למטה מטה, יש בה כל הבחינות והענינים שישנם במלכות כמו שהיא באצילות.\n<b>וביאור</b> הענין שמלכות דאצילות נקראת פנים, הנה, בחינת פנים בכללות הוא בחינת עצמות אוא\"ס שלמעלה מהשתלשלות, וכללות ההשתלשלות הוא בחינת חיצוניות ואחור. ובפרטיות המדריגות בהשתלשלות גופא, הנה אצילות הוא בחינת פנים, ובי\"ע הוא חיצוניות ואחור<sup data-n=\"20\">13</sup>, כמ\"ש הרמ\"ז<sup data-n=\"21\">14</sup> שד' המדריגות פנים ימין שמאל ואחור הם ד' עולמות אבי\"ע, ואצילות היא בחינת פנים. והענין בזה, שחכמה נקראת פנים<sup data-n=\"22\">15</sup>, ולהיות שאבא עילאה מקננא באצילות<sup data-n=\"23\">16</sup>, לכן כללות האצילות הוא בחינת פנים, וגם בחינה היותר אחרונה שבאצילות, מלכות דאצילות, הנה בהיותה באצילות ה\"ה ג\"כ בבחינת פנים. אבל כמו שהיא יורדת ונעשית עתיק לבי\"ע, שזהו רק הארת המלכות בלבד<sup data-n=\"24\">17</sup>, ובזה גופא רק החיצוניות שבה, הנה זהו בחינת הסתר, ועז\"נ ואנכי הסתר אסתיר פני ביום ההוא, שהמלכות שהיא בחינת פנים (פני) מסתתרת (הסתר אסתיר) בבי\"ע (ביום ההוא).\nג) <b>ועוד</b> טעם שהמלכות נקראת פנים לפי שהיא הפנימיות דנשמות ישראל, כמ\"ש<sup data-n=\"25\">18</sup> וזאת לפנים בישראל, זאת היא בחינת מלכות<sup data-n=\"26\">19</sup>, והיא לפנים בישראל, היינו הפנימיות דנשמות ישראל. והענין הוא<sup data-n=\"27\">20</sup>, דאיתא בע\"ח<sup data-n=\"28\">21</sup> שיש ניצוץ קטן מאד שהוא בחינת אלקות כו' (מדריגה התחתונה שבבורא) וזה הניצוץ מתלבש בכח ניצוץ אחד נבראכו' הנקרא יחידה. וכמובן גם ממ\"ש במדרש<sup data-n=\"29\">22</sup> חמשה שמות נקראו לה נפש רוח נשמה חי' יחידה, היינו, שגם יחידה היא רק שם בלבד<sup data-n=\"30\">23</sup>, ועצם הנשמה הוא למעלה גם מבחינת היחידה, כי, בחינת היחידה הו\"ע ניצוץ אחד נברא, ועצם הנשמה הוא הניצוץ בורא, והוא הפנימיות של הנשמה. וזהו בחינת מלכות שנקראת פנים, הפנימיות דנשמות ישראל. דהנה, ידוע שנפש היא בחינת עשי', רוח הוא בחינת יצירה, נשמה בחינת בריאה, חי' בחינת אצילות, ויחידה היא בחינת כתר, היינו בחינת אריך, והניצוץ בורא שמתלבש בהניצוץ נברא הוא בחינת עתיק. וכמו\"כ גם בא\"ק שהוא מחשבה הקדומה על כללות ההשתלשלות, שיש שם בחינת לבושים ובחינת ספירות, בחינת לבושים הוא מחצב הנשמות, ובחינת ספירות הוא מחצב הספירות<sup data-n=\"31\">24</sup>, הנה בחינת יחידה שהיא הניצוץ נברא היא ממחצב הנשמות, אבל הניצוץ בורא (שמתלבש בניצוץ נברא) הוא ממחצב הספירות, שבזה שייך לומר מדריגה תחתונה שבבורא. ואף שעצם ואמיתת ענין בורא הוא למעלה מהספירות, שהם אורות בכלים שנמצאו ונאצלו מאוא\"ס, מ\"מ, הספירות הם אלקות ממש, שהרי איהו וחיוהי וגרמוהי חד<sup data-n=\"32\">25</sup>, היינו שגם הלבושים דאצילות אינם נפרדים והם אלקות, ומכ\"ש שהלבושים דא\"ק הם אלקות, וכ\"ז הוא בנוגע ללבושים שהם התפשטות בלבד, ומכ\"ש הספירות דאצילות, ובפרט הספירות דא\"ק, הרי הם אלקות ממש. ובאמת הנה הניצוץ בורא הוא למעלה גם ממחצב הספירות, דהניצוץ בורא הוא בחינת עתיק כנ\"ל, וכמו\"כ הוא גם בא\"ק, שהניצוץ בורא הוא בחינת עתיק דא\"ק, כידוע<sup data-n=\"33\">26</sup> שיש בחינת עתיק לעילא מגולגלתא דא\"ק, שהוא בחינת מלכות דא\"ס. דכמו שמלכות דאצילות נעשית עתיק לבריאה, כמו\"כ מלכות דאצילות דכללות, שהיא בחינת מלכות דא\"ס, נעשה עתיק לבריאה דכללות שהוא א\"ק. והניצוץ בורא שהוא הפנימיות דנשמות ישראל הוא בחינת מלכות דא\"ס, עתיק דא\"ק. ומשום זה הנה גם כמו שהמלכות באה בסדר השתלשלות עד מלכות דאצילות, נקראת המלכות פנים.ד) <b>והנה</b> ב' מדריגות הנ\"ל בבחינת המלכות שנקראת פנים, כמו שהיא בגילוי באצילות, וכמו שבאה בהסתר להיות עתיק לבריאה, ישנם גם בכללות נשמות ישראל (וזאת לפנים בישראל) ובכל נשמה ונשמה בפרט, שיש בה ב' בחינות<sup data-n=\"34\">27</sup>, בחינת ישראל, ל\"י רא\"ש<sup data-n=\"35\">28</sup>, ובחינת יעקב, יו\"ד עק\"ב<sup data-n=\"36\">29</sup>, שהם עצם הנשמה והארת הנשמה. דהנה<sup data-n=\"37\">30</sup>, ידוע שלא כל הנשמה מתלבשת בגוף, והיינו, שהכחות פנימיים שמתלבשים בכלים אינם עצם הנשמה, כי עצם הנשמה אינה יכולה להתלבש בגוף, שהרי אפילו מלאך בשליש עולם עומד<sup data-n=\"38\">31</sup>, וא\"כ הנשמה שהיא למעלה ממלאך, הרי בודאי שאינה יכולה להתלבש בגוף, ומה שמתלבש בגוף הוא רק הארת הנשמה לבד, בחינת יעקב, ועצם הנשמה הוא בחינת ישראל. ומצד ב' המדריגות הנ\"ל שבנשמה, יש חילוקים גם באופן העבודה.\n<b>והענין</b> בזה, דהנה, בעבודה דאהבה, דלית פולחנא כפולחנא דרחימותא<sup data-n=\"39\">32</sup>, כתיב<sup data-n=\"40\">33</sup> ואהבת גו' בכל לבבך ובכל נפשך ובכל מאדך. האהבה דבכל לבבך היא כמ\"ש<sup data-n=\"41\">34</sup> לאהבה את הוי' אלקיך גו' כי הוא חייך, והיינו שכאשר יתבונן שהחיות אלקי מחי' ומהווה את העולם בכל עת ובכל שעה והוא (האדם המתבונן) בתוכו, היינו, שאלקות הוא חיי העולם וחיי נפשו, והוא חיים וטוב, כמ\"ש<sup data-n=\"42\">35</sup> ראה נתתי לפניך את החיים ואת הטוב ואת המות ואת הרע, דרוחניות הוא חיים וטוב, וגשמיות הוא מות ורע לפי שאין לה קיום מצד עצמה כלל, הנה התבוננות זו מביאה להיות ובחרת בחיים<sup data-n=\"43\">36</sup>, שיהי' חפצו ורצונו באלקות, שזהו\"ע לאהבה את הוי' אלקיך כי (לפי ש)הוא חייך, שזוהי האהבה דבכל לבבך. ואהבה זו היא מוגבלת, דכיון שבאה מההתבוננות בחיות העולמות בכלל והאדם בפרט שהחיות הוא בבחינת גבול, לכן גם האהבה היא בהגבלה. ולמעלה מזה היא האהבה דבכל נפשך, שעז\"נ<sup data-n=\"44\">37</sup> אפילו נוטל את נפשך, ואהבה זו באהע\"י ההתבוננות שכל חיות העולמות הוא רק הארה בלבד, והיינו שמרגיש את חיות העולמות ומתבונן שחיות זו היא רק הארה בלבד, שהרי במחשבה אחת נבראו העולמות<sup data-n=\"45\">38</sup>, ואפילו באדם אין תפיסת מקום למחשבה אחת לגבי כללות כח המחשבה ומכ\"ש לגבי נפשו ולגבי עצם נפשו, ומכ\"ש למעלה שמחשבה א' היא רק הארה בלבד, ומהתבוננות זו בא להאהבה דבכל נפשך. אמנם באמת הנה גם אהבה זו קשורה בהגבלה, דכיון שבאה מההתבוננות שחיות העולמות הוא רק הארה בלבד, והיינו שהוא מרגיש את חיות העולמות ושולל שהוא רק הארה, לכן גם היא קשורה בהגבלה. וב' מדריגות אלו באהבה, האהבה המוגבלת דבכל לבבך, והאהבה דבכל נפשך שהיא קשורה עכ\"פ עם הגבלה, הם מצד בחינת יעקב, שהיא רק הארת הנשמה בלבד. אך תכלית העבודה היא לבוא לבחינת אהבה דבכל מאדך, שהוא בלי גבול לגמרי, דאף שהוא מאד שלך, מ\"מ הוא למעלה מהגבלה לגמרי<sup data-n=\"46\">39</sup>. ואהבה זו באה מצד ההתבוננות בהפלאת אוא\"ס, איך שהוא מופלא מסדר השתלשלות, ועוד יותר שהוא מופלא מצד עצמו, שעי\"ז בא להאהבה דבכל מאדך, דלהיות שבאה מצד ההתבוננות באוא\"ס איך שהוא מופלא ומרומם מצ\"ע, לזאת הנה גם האהבה היא מרוממת מצ\"ע, היינו שהוא מרומם מכל עניניו והגבלותיו גם בדרך שלילה. ואהבה זו היא מצד בחינת ישראל, בחינת המקיפים דהנשמה, הפנימיות והעצמיות של הנשמה.\nה) <b>אך</b> בזמן הגלות כתיב ואנכי הסתר אסתיר פני גו', שהאהבה דבכל מאדך שמצד בחינת ישראל (פנימיות הנשמה, פני) היא בהסתר. דהנה, סדר העבודה הוא שבכדי לבוא להאהבה דבכל מאדך צ\"ל הקדמת העבודה שע\"פ טו\"ד שהיא האהבה דבכל לבבך ובכל נפשך, ודוקא אח\"כ נותנים לו מלמעלה בדרך מתנה גם האהבה דבכל מאדך. ולכן, כאשר חסרה העבודה שע\"פ טו\"ד אזי אין לו גם האהבה דבכל מאדך. ובפרט כאשר הוא משוקע בעניני תאוה וחמדה, שאז האהבה היא מסתתרת ומשוקעת בעניני תאוותיו, דעם היות שאהבה זו באה מלמעלה בדרך מקיף, מ\"מ, הרי זה שהאהבה היא בדרך מקיף הוא מה שהאהבה היא בהעלם מצד עצמה, אבל ע\"י שהוא משוקע בעניני תאוה, אין זה רק שהאהבה היא בהעלם מצד עצמה, אלא שמתעלמת בעניני תאוותיו. וזהו כללות הענין דזמן הגלות, שהוא היציאה מארץ ישראל (מ'איז אַוועק פוןארץ ישראל), בחינת לי ראש&lt;28&gt;, וזהו\"ע חוץ לארץ, היינו חוץ מבחינת לי ראש. ועל זה איתא בזהר<sup data-n=\"47\">40</sup> אני ישנה<sup data-n=\"48\">41</sup> בגלותא, שזמן הגלות הו\"ע של שינה, שחסרה ההתבוננות וההשגה כו', ולכן גם האהבה דבכל מאדך שמצד בחינת ישראל היא בהעלם.\n<b>אמנם</b> עם היות שאני ישנה בגלותא, מ\"מ, ולבי ער<sup data-n=\"48\">41</sup>, דלבי שהוא פנימיות החיות הוא ער גם בזמן הגלות. ואף שנתבאר דבזמן הגלות הוא הסתר אסתיר פני, דפני שהוא הפנימיות הוא בהעלם, מ\"מ אין זה סותר למ\"ש ולבי ער. והענין בזה, דהנה, ישנו אור העצם וכח העצם (אור הנשמה וכח הנשמה). וענין האהבה הוא אור, דגם בחינת האהבה דבכל מאדך להיותה אהבה, הו\"ע של אור, ובפרט שבאה מצד ההכרה עצמית מה שעצם הנשמה מכרת בעצמות א\"ס ב\"ה, ע\"ד מה דאיתא<sup data-n=\"49\">42</sup> בן ג' שנים הכיר אברהם את בוראו<sup data-n=\"50\">43</sup>, וכיון שהאהבה באה מצד הכרה, הרי היא בחינת אור. ולכן, בזמן הגלות שאין בחינת האור, האהבה היא בהעלם, ועז\"נ אני ישנה בגלותא. אבל מ\"מ ולבי ער, לפי שכח העצם ישנו גם בזמן הגלות, והו\"ע המס\"נ, דמס\"נ הו\"ע הכח, וראי' לזה, שהרי גם בקל שבקלים שאין בו בחינת אור, יש בו ג\"כ כח המס\"נ, לפי שענין המס\"נ הו\"ע הכח, וכח המס\"נ ישנו בגילוי גם בזמן הגלות, ואדרבה, בזמן הגלות הוא בגילוי יותר מכמו בזמן הבית, כמו שאמר רבינו הזקן<sup data-n=\"51\">44</sup> בשם הבעש\"ט עה\"פ<sup data-n=\"52\">45</sup> כן בקדש חזיתיך שאמר דוד המלך בשם כנסת ישראל, בשעה שהי' בארץ צי' ועיף שאז צמאה לך נפשי גו', אזי אמר כן בקדש חזיתיך, הלואי בקדש חזיתיך, ולכן ענין המס\"נ הוא בגילוי יותר בזמן הגלות מכמו בזמן הבית. וזהו שהנסיונות בזמן הגלות הם יותר מכמו בזמן הבית, וכיון שאין הקב\"ה בא בטרוניא עם בריותיו<sup data-n=\"53\">46</sup>, עכצ\"ל שבזמן הגלות ניתנו כחות גדולים יותר, שזהו כח המס\"נ, שבזמן הגלות הוא בגילוי ביותר<sup data-n=\"54\">47</sup>, וכמו באנשים פשוטים שאין בהם בחינת אור, שדוקא אצלם כח המס\"נ הוא ביותר.\n<b>וע\"י</b> כח המס\"נ שמצד כח הנשמה שישנו בגילוי בזמן הגלות, מתגלה גם אור הנשמה, שהיא בחינת ההכרה והאהבה דבכל מאדך הנ\"ל.והענין בזה, דאיתא במדרש<sup data-n=\"55\">48</sup> אין לך שעה קשה כאותה שעה שכתב בה ואנכי הסתר אסתיר פני, וביחד עם זה, הנה מאותה שעה (דוקא) אני מחכה לו, שנאמר<sup data-n=\"56\">49</sup> וחכיתי להוי' המסתיר פניו. והנה, מ\"ש חכיתי (ולא לשון תקוה סתם), הוא כמאמר<sup data-n=\"57\">50</sup> למאן דדחקין במילי דחוכמתא יעשה למחכה לו<sup data-n=\"58\">51</sup>, שגילוי זה הוא למעלה מהגילוי דגן עדן ולמעלה מהשתלשלות, וגילוי זה נעשה דוקא ע\"י המס\"נ ועבודת הנסיונות שבזמן הגלות, וכידוע<sup data-n=\"59\">52</sup> ההפרש בין בירורים לנסיונות, שעבודת הבירורים היא לברר את הניצוץ האלקי המלובש בדבר הגשמי, והעבודה היא ע\"י קירוב, משא\"כ בנסיונות שהניצוץ הוא בהעלם, דאף שגם בנסיונות יש ניצוץ אלקי שלכן יש לו קיום, מ\"מ, הניצוץ הוא נכבה (אויסגעלאָשן) בו, וכמו ניצוץ בדבר האסור, ולכן העבודה אינה בהדבר, כי אם בהאדם, שיעמוד בנסיון. וע\"י עבודת הנסיונות והמס\"נ שבזמן הגלות שהוא מצד כח העצם, מתגלה גם אור העצם, שהוא האהבה דבכל מאדך שבאה מצד ההכרה עצמית דעצם הנשמה בעצמות א\"ס ב\"ה.\nו) <b>וזהו</b> ויהי אומן את הדסה היא אסתר, דגם בחינת אסתר שהיא בבחינת הסתר אסתיר פני, מ\"מ הדסה היא אסתר, כיון שמצד ההסתר דוקא נעשה חכיתי להוי' המסתיר פניו. והיינו, שגם בבחינת יעקב, שהיא הנשמה המלובשת בגוף, יש כל הבחינות דישראל, שזהו עצם הנשמה. דכמו שהוא בהשתלשלות שבבחינת המלכות כמו שנעשית עתיק לבריאה יש בה כל הבחינות כמו שהיא באצילות, כמו\"כ בהנשמה המלובשת בגוף יש בה כל הבחינות שיש בעצם הנשמה, שזהו\"ע הדסה היא אסתר. וענין זה מתגלה ע\"י המס\"נ (כנ\"ל), שזהו\"ע הדסה (היא אסתר), כדאיתא במסכת סנהדרין<sup data-n=\"60\">53</sup> עה\"פ והוא עומד בין ההדסים, דקאי על חנני' מישאל ועזרי', שאצלם הי' ענין המס\"נ בפועל, והיינו, לא כמו המס\"נ בכח שהיתה בשעת מ\"ת, שעל כל דבור ודבור פרחה נשמתם<sup data-n=\"61\">54</sup>, שמס\"נ זו היתה מלמעלה, כי אם מס\"נ בפועל שבזמן הגלות, שהיא ע\"י עבודה ויגיעה דוקא, שלכן, דוקא בימי הפורים (בזמן הגלות) קיימו<sup data-n=\"62\">55</sup> את אשר החלו<sup data-n=\"63\">56</sup> לעשות בשעת מ\"ת<sup data-n=\"64\">57</sup>, והיינו, שע\"י המס\"נ הוא התגלות עצםהנשמה. אמנם, המשכת הכח לנשמה היא ע\"י התורה. וזהו מ\"ש ויהי אומן את הדסה, דאומן קאי על התורה, כמ\"ש<sup data-n=\"65\">58</sup> ואהי' אצלו אמון, והתורה אומרת אני הייתי כלי אומנתו של הקב\"ה<sup data-n=\"66\">59</sup>. ובפרטיות יותר, כדאיתא במדרש<sup data-n=\"66\">59</sup> עה\"פ ואהי' אצלו אמון, אמון פדגוג אמון מוצנע אמון מכוסה, דאמון מכוסה קאי על המצוות שהם בחינת לבושים, ואמון פדגוג אמון מוצנע קאי על גליא דתורה ונסתר דתורה. והו\"ע נתינת כח ועוז לנשמות ישראל ע\"י התורה שהיא עוז ותושי'<sup data-n=\"67\">60</sup>, עוז לנה\"א ותושי' לנה\"ב<sup data-n=\"68\">61</sup>, שמתשת כח נה\"ב שמעלים על הקדושה ונותנת כח ועוז בעבודת הנה\"א לעמוד בתוקף עוז, ועד לכח המס\"נ, שעי\"ז מתגלה גם אור העצם, שהוא האהבה דבכל מאדך שמצד הכרת עצם הנשמה בעצמות א\"ס ב\"ה, כמאמר<sup data-n=\"69\">62</sup> חבוקה ודבוקה בך יחידה לייחדך.\n**********",[["8","1","אסתר ב, ז."],["9","2","מגילה יג, א."],["10","3","זכרי' א, ח."],["11","4","אסתר ב, כ."],["12","5","בהבא לקמן – ראה ד\"ה ויהי אומן עטר\"ת (סה\"מ עטר\"ת ע' שח ואילך עם הערות מכ\"ק אדמו\"ר שליט\"א). תשכ\"ד."],["13","6","עץ חיים שער מו (שער כסא הכבוד) פ\"ו. ובכ\"מ."],["14","7","ראה אוה\"ת מגילת אסתר (הוצאת תש\"נ) ע' טז."],["15","8","ראה סה\"מ תרח\"ץ ס\"ע קסד ואילך. סה\"ש קיץ ה'ש\"ת ע' 44 ואילך. ובכ\"מ."],["16","9","חולין קלט, ב."],["17","10","וילך לא, יח."],["18","11","פיוט \"יגדל\"."],["19","12","תהלים ה, ה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, סע\"ג</a> ואילך. ובכ\"מ."],["20","13","ראה גם אוה\"ת תשא ע' ב'לד ואילך. סה\"מ תרע\"ח ע' רטז ואילך. תש\"ה ע' 59 ואילך."],["21","14","לזח\"ג צג, ב."],["22","15","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600516\" data-slug=\"or-hatorah-hb\" data-id=\"8316600516\">אוה\"ת נ\"ך ח\"א ע' תקטז</a>."],["23","16","רמ\"ז לזח\"ב רכ, ב. תו\"א משפטים עה, א. סה\"מ תרצ\"ו ע' 199. וש\"נ."],["24","17","אולי נאמר: רק מלכות (היינו שאין בה בחינת החכמה) שהיא הארה בלבד."],["25","18","רות ד, ז."],["26","19","ראה זח\"ג רצז, סע\"ב. ועוד. פרדס שער כג (שער ערכי הכינויים) מערכת זאת."],["27","20","ראה גם סה\"מ תרע\"ח ע' ריג ואילך. תש\"ה ע' 54 ואילך."],["28","21","שער מב (שער דרושי אבי\"ע) פ\"א. הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">לקו\"ת פ' ראה כז, א</a>."],["29","22","ב\"ר פי\"ד, ט. דב\"ר פ\"ב, לז. בכמה מקומות (ודפוסים) הוא בשינוי הסדר. אבל כ\"ה (כבפנים – נרנח\"י) בעץ חיים שם. ובכ\"מ."],["30","23","ראה גם סה\"מ תרצ\"ו ס\"ע 56 ואילך. וש\"נ."],["31","24","שערי קדושה להרח\"ו ח\"ג שער ב. וראה גם ביאורי הזוהר להצ\"צ ח\"א ע' ערב ואילך."],["32","25","תקוני זוהר בהקדמה (ג, ב)."],["33","26","ע\"ח שער ט (שער שבירת הכלים) פ\"ו. זהר הרקיע לזח\"א טו, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380299\" data-slug=\"likkutei-torah\" data-id=\"4001380299\">לקו\"ת</a> הוספות לויקרא נא, ד."],["34","27","ראה סה\"מ תרע\"ח ע' ריד ואילך. תש\"ה ע' 57 ואילך."],["35","28","שער הפסוקים להאריז\"ל וישלח לב, כט. ספר הליקוטים להאריז\"ל ויחי מז, כח. שם מח, ב. פע\"ח שער הלולב פ\"א. סהמ\"צ להצ\"צ טו, ב – בשם הזוהר. ועוד."],["36","29","פרדס שער כג (שער ערכי הכינויים) בערכו. ע\"ח שער ג (שער סדר האצילות) פ\"ב. תו\"א ויצא כא, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380599\" data-slug=\"likkutei-torah\" data-id=\"4001380599\">לקו\"ת בלק ע, ב</a>. ובכ\"מ."],["37","30","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a>. ובכ\"מ."],["38","31","ראה חולין צא, ב. ב\"ר פס\"ח, יב. לקו\"ת שם. סה\"מ תש\"ח ע' 280 ובהערה שם."],["39","32","ראה זוהר ח\"ב נה, ב. ח\"ג רסז א. קונטרס העבודה ספ\"א. פ\"ג ואילך. ד\"ה לא תהי' משכלה תשי\"ב (תורת מנחם – התוועדויות ח\"ד ע' 328 ואילך)."],["40","33","ואתחנן ו, ה."],["41","34","נצבים ל, כ."],["42","35","שם, טו."],["43","36","שם, יט."],["44","37","משנה ברכות נד, א."],["45","38","ראה זח\"ב כ, א. רעו, ב (בהוספות). לקו\"ת שה\"ש ט, ב."],["46","39","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">תו\"א מקץ לט, סע\"ג</a> ואילך. ובכ\"מ."],["47","40","ח\"ג צה, א."],["48","41","שה\"ש ה, ב."],["49","42","נדרים לב, סע\"א. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201014\" data-slug=\"likkutei-sichot\" data-id=\"1300201014\">לקו\"ש ח\"כ ע' 14</a> ואילך."],["50","43","ראה סה\"מ עת\"ר ע' קלב. וראה סה\"מ תרע\"ח ע' רטז. תש\"ה ע' 59."],["51","44","סה\"מ תרפ\"ט ע' 215. וראה כתר שם טוב (קה\"ת, תשנ\"ט) הוספות סימן סד. וש\"נ."],["52","45","תהלים סג, ג."],["53","46","ע\"ז ג, סע\"א."],["54","47","ראה סה\"מ תרמ\"ח ע' קפז ואילך. תרפ\"ה ע' רס ואילך. ובכ\"מ."],["55","48","ב\"ר פמ\"ב, ג. וראה הערת כ\"ק אדמו\"ר שליט\"א בסה\"מ עטר\"ת שם (ע' שיב)."],["56","49","ישעי' ח, יז."],["57","50","זח\"א קל, ב. נתבאר בהמשך תרס\"ו ע' עח ואילך."],["58","51","ישעי' סד, ג."],["59","52","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380794\" data-slug=\"likkutei-torah\" data-id=\"4001380794\">לקו\"ת פ' ראה יט, ג</a>. ובכ\"מ."],["60","53","צג, א."],["61","54","שבת פח, ב."],["62","55","אסתר ט, כז. שבת שם, א."],["63","56","שם, כג."],["64","57","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370438\" data-slug=\"torah-or\" data-id=\"3901370438\">תו\"א מג\"א צח, א</a>. ועוד."],["65","58","משלי ח, ל."],["66","59","ב\"ר בתחילתו."],["67","60","מכילתא בשלח טו, ב. ויק\"ר פל\"א, ה. סנהדרין כו, ב."],["68","61","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a>."],["69","62","נוסח הושענות (יום ג)."]]],[1400140006,"<h3>בס\"ד. פורים (מאמר ב')<sup data-n=\"70\">*</sup> ה'תשי\"ג</h3>\n<b>על</b> כן קראו לימים האלה פורים על שם הפור<sup data-n=\"71\">1</sup>, וע\"פ הידוע<sup data-n=\"72\">2</sup> ששמו של כל דבר מורה על ענינו, מובן, דזה שקראו לימים האלה פורים על שם הפור הוא לפי שעיקר היו\"ט דפורים הוא הגורל (פור הוא הגורל<sup data-n=\"73\">3</sup>). וצריך להבין (כמו שמדייק בתו\"א ד\"ה זה<sup data-n=\"74\">4</sup>), דלכאורה, הרי לא זה הי' [עיקר<sup data-n=\"75\">5</sup>] הנס. ולהוסיף, דהגורל שהפיל המן (לא רק שלא זה הי' הנס, אלא אדרבה) הי' חלק מהגזירה [ובלשון המגילה<sup data-n=\"76\">6</sup> הפיל פור הוא הגורל להומם ולאבדם], ומזה שימים אלה נקראים בשם פורים על שם הפור, משמע שזה (הגורל) הוא עיקר הנס דפורים, ועד שהנס נקרא על שם זה. ולכאורה הי' אפשר לבאר ע\"פ מה שאיתא בגמרא<sup data-n=\"77\">7</sup> דכשנפל הפור בחודש אדר שמח (המן) שמחה גדולה, אמר נפל לי פור בירח שמת בו משה, ולא הי' יודע שבשבעה באדר מת ובשבעה באדר נולד. ועפ\"ז הי' אפשר לומר, דזה שימים האלה נקראים על שם הפור הוא לפי שהנס דפורים הי' זה שנפל הפור בחודש אדר, החודש שבו נולד משה מושיען של ישראל. אבל ביאור זה עצ\"ע, כי מזה שהיו\"ט נקרא פורים על שם הפור, משמע, שהשייכות דהנס לפור היא (לא רק לזה שנפל הפור בחודש אדר, אלא גם) לענין הפור עצמו. ואדרבה, עיקר הנס הי' מצד הפור הוא הגורל. דגורל הוא ענין נעלה ביותר, שמזה נמשך הנס. וזה שנפל הגורל על חודש אדר שבו נולד מושיען של ישראל הוא (כמו כל הענינים שהיו בהנס דפורים, שהם) תוצאה מעיקר ענינו, פורים על שם הפור.ב) <b>ויובן</b> זה ע\"פ המבואר בתו\"א<sup data-n=\"78\">8</sup> דפורים ויום הכפורים שייכים זל\"ז<sup data-n=\"79\">9</sup>. דפירוש יום <i>כ</i>פורים הוא כמו פורים [ויתירה מזו, דמזה שיום הכפורים הוא <i>כ</i>פורים (בכ\"ף הדמיון בלבד), מוכח, שפורים הוא נעלה יותר מיוהכ\"פ<sup data-n=\"80\">10</sup>]. ומהשייכות דיוהכ\"פ ופורים היא, שבשניהם הו\"ע הגורל. דביוהכ\"פ הפילו גורל על שני השעירים<sup data-n=\"81\">11</sup>, וגם פורים הוא על שם הפור הוא הגורל. ועוד ענין בהשייכות דפורים ויוהכ\"פ, ששניהם הם למעלה משם הוי'<sup data-n=\"82\">12</sup>. דביוהכ\"פ כתיב<sup data-n=\"83\">13</sup> <i>לפני</i> הוי' תטהרו, למעלה מהוי'<sup data-n=\"84\">14</sup>. וגם בנוגע לפורים ידוע<sup data-n=\"85\">15</sup> דהטעם שלא נזכר שם הוי' בכל מגילת אסתר<sup data-n=\"86\">16</sup> הוא לפי שבפורים הוא גילוי אוא\"ס שלמעלה מהוי'.\n<b>וביאור</b> השייכות דשני הענינים בההשוואה דיוהכ\"פ ופורים [שבשניהם הו\"ע הגורל, וששניהם הם למעלה משם הוי'<sup data-n=\"87\">17</sup>], יובן בהקדים דענין הגורל הוא למעלה מהשכל<sup data-n=\"88\">18</sup>. שהרי גורל הוא (בכלל<sup data-n=\"89\">19</sup>) בשני דבריםשוים [וכמו שני השעירים דיוהכ\"פ שהיו שוים במראה ובקומה ובדמים<sup data-n=\"90\">20</sup>], דכאשר אחד מהם הוא טוב יותר, אין מקום לגורל, ודוקא כששני הדברים הם שוים, כיון שמצד השכל א\"א להכריע באיזה מהם לבחור, סומכים אז על הגורל שלמעלה מהשכל. ועד\"ז הוא למעלה, דגורל הוא למעלה מהשתלשלות [דחכמה היא ראשית ההשתלשלות, וגורל שהוא למעלה מהחכמה הוא למעלה מהשתלשלות]. ועפ\"ז, ההשוואה דפורים ויוהכ\"פ, שבשניהם הו\"ע הגורל, הוא – גילוי אוא\"ס שלמעלה מהשתלשלות. וזהו הקשר דשני הענינים בההשוואה דיוהכ\"פ ופורים, שבשניהם הו\"ע הגורל וששניהם הם למעלה מהוי', כי הוי' הוא השתלשלות (יו\"ד חכמה ה' בינה וכו'), וזה שיוהכ\"פ ופורים הם למעלה מהוי' הוא שהגילוי דיוהכ\"פ ודפורים הוא למעלה מהשתלשלות<sup data-n=\"91\">21</sup>, ענין הגורל.\nג) <b>והנה</b> ידוע<sup data-n=\"92\">22</sup> במעלת הגורל, שהוא למעלה (לא רק מהשכל, אלא) גם מהרצון שלמעלה מהשכל. שהרי כשאדם מטיל גורל הוא מחליט דכמו שיפול הגורל כן יהי' רצונו. דמזה מוכח שהגורל מגיע בדרגא שלמעלה גם מהרצון, שלכן הרצון הוא כפי הגורל. ועד\"ז הוא למעלה, דענין הגורל הוא בבעל הרצון שלמעלה מרצון. ועפ\"ז יש לומר, שהקשר דשני הענינים בההשוואה דיוהכ\"פ ופורים (שבשניהם הו\"ע הגורל וששניהם הם למעלה מהוי') הוא, כי ההתחלה דשם הוי' היא הקוץ שעל היו\"ד, שרומז על הרצון שלמעלה מחכמה<sup data-n=\"93\">23</sup>, וזה שיוהכ\"פ ופורים הם למעלה מהוי' (למעלה גם מהקוץ שעל היו\"ד) הוא שביוהכ\"פ ובפורים הוא המשכת וגילוי בחינת בעל הרצון (שלמעלה מרצון)<sup data-n=\"94\">24</sup>, ענין גורל.ד) <b>ועפ\"ז</b> יש לבאר הקשר דשני הפירושים ביום הכפורים – שביום זה מתכפרים כל הענינים הבלתי רצויים (כפורים כפשוטו), ושיום זה הוא כמו פורים (שהדמיון דיוהכ\"פ לפורים הוא שביוהכ\"פ הפילו גורל, כמו פורים על שם הפור הוא הגורל) – כי שלימות הכפרה על הענינים שעשו היפך הרצון דתומ\"צ הוא כשהמשכת הכפרה היא מאוא\"ס בעל הרצון (שלמעלה מהרצון דתומ\"צ)<sup data-n=\"95\">25</sup>. וזהו הקשר דשני הפירושים ביום כפורים, דזה שיוהכ\"פ הוא כמו פורים על שם הפור הוא הגורל, היינו שגם ביוהכ\"פ הוא ההמשכה מבעל הרצון (דוגמת ההמשכה דפורים), הוא טעם וביאור על זה שהוא יום כפורים כפשוטו, שבו מתכפרים הענינים הבלתי רצויים. וזהו מה שהכפרה דפורים היא נעלית יותר מהכפרה דיוהכ\"פ<sup data-n=\"96\">26</sup>, דיוהכ\"פ אינו מכפר אלא עם התשובה<sup data-n=\"97\">27</sup> והכפרה שהיתה לכל היהודים בימי הפורים ה\"ז יום שמחה<sup data-n=\"98\">28</sup>, כי עיקר ענין הגורל (המשכת בחינת בעל הרצון) הוא בימי הפורים, דהימים עצמם נקראים בשם פורים על שם הפור, ולכן, הכפרה שהיתה בימי הפורים אין בה הגבלות<sup data-n=\"99\">29</sup>, ויום הכפורים הוא <i>כ</i>פורים<sup data-n=\"100\">30</sup> בכ\"ף הדמיון בלבד, ואין יוהכ\"פ מכפר אלא עם התשובה.\nה) <b>וצריך</b> להבין, דלפי הנ\"ל שע\"י הפור הוא הגורל הוא המשכת אוא\"ס בעל הרצון, שעי\"ז נתכפרו כל הענינים הבלתי רצויים, מה היתה סברתו של המן הרשע (שקטרג על היהודים<sup data-n=\"101\">31</sup>) להפיל פור הואהגורל. גם צריך להבין מ\"ש על כן קראו לימים האלה פורים על שם <i>ה</i>פור, דהפור (בה\"א הידיעה) קאי על הפור שנאמר לפנ\"ז היינו הפור שהפיל המן, והרי הפור שהפיל המן הי' ענין בלתי רצוי ולמה נקראים ימים האלה פורים על שם פור זה. ונקודת הביאור בזה, שמצד הדרגא דהשתלשלות, כיון שבדרגא זו מעשה התחתונים תופס מקום, עיקר ההשפעה היא לישראל, לפי שישראל הם מקיימים תומ\"צ, ואפילו אלו שהם היפך צדיקים הם מלאים מצוות כרמון<sup data-n=\"102\">32</sup>. וכמ\"ש<sup data-n=\"103\">33</sup> השקיפה ממעון קדשך מן השמים וברך את עמך את ישראל, שמצד בחינת שמים [שמים הוא שם מים<sup data-n=\"104\">34</sup>, ומים הוא חכמה ראשית ההשתלשלות], נשפעים הברכות לישראל<sup data-n=\"105\">35</sup>. וכיון שגם המן הרשע ידע שלאחרי כל הקטרוגים שקטרג על ישראל אין שום דמיון בינו ובין ישראל [שלכן, מצד הדרגא דהשתלשלות אין שייך שהמן <i>הרשע</i> ינצח ח\"ו את ישראל שגם הפחותים שבהם מלאים מצוות כרמון], לכן הפיל פור הוא הגורל, דכיון שבהדרגא דלמעלה מהשתלשלות (גורל) אין מעשה התחתונים תופס מקום, והכל שוים שם, כחשיכה כאורה<sup data-n=\"106\">36</sup>, לכן חשב שמצד דרגת הגורל שלמעלה מהשתלשלות יש מקום שהוא ינצח ח\"ו את ישראל.\nו) <b>ויש</b> לקשר זה עם המבואר במק\"א<sup data-n=\"107\">37</sup> בענין אחשורוש, דאחשורוש הוא אחש ורוש<sup data-n=\"108\">38</sup>. חש הוא מלשון שתיקה [כדאיתא בגמרא<sup data-n=\"109\">39</sup> מאי חשמל כו' עתים חשות עתים ממללות], והשתיקה דחש היא למעלה מדיבור<sup data-n=\"110\">40</sup>, ע\"ד מלה בסלע שתיקותא בתרי<sup data-n=\"111\">41</sup>. דשרש הדיבור הוא בחכמה<sup data-n=\"112\">42</sup>,ושתיקה היא בכתר שלמעלה מהחכמה, כמארז\"ל<sup data-n=\"113\">43</sup> סיג לחכמה שתיקה<sup data-n=\"114\">44</sup>, דסיג לחכמה (סיג מלשון גדר ומקיף) הוא הכתר שלמעלה מהחכמה. ויש לקשר זה עם מה דאיתא במדרש<sup data-n=\"115\">45</sup> שאחשורוש זה הקב\"ה שאחרית וראשית שלו<sup data-n=\"116\">46</sup>, כי כתר הוא (בכלל) אור הסובב שלמעלה מהשתלשלות, דאור הסובב כולל אחרית וראשית בשוה, אחרית וראשית שלו<sup data-n=\"117\">47</sup>.\n<b>וצריך</b> להבין, דבגמרא<sup data-n=\"118\">48</sup> איתא דאחשורוש הוא על שם שהושחרו פניהם של ישראל בימיו, ואיך זה מתאים עם הפירוש שאחשורוש הוא מי שאחרית וראשית שלו. והענין הוא, דהיא הנותנת. דכיון שמצד הסובב שלמעלה מהשתלשלות אור וחושך שוים לפניו (כנ\"ל סעיף ה), לכן, מבחינת השתיקה (חש דאחשורוש) שלמעלה מדיבור נשתלשל (ע\"י ריבוי צמצומים וכו') השתיקה שלמטה מדיבור<sup data-n=\"119\">49</sup>, שהאלקות הוא בהעלם (העלם כפשוטו שלמטה מגילוי), ועד להשתיקה דכרחל לפני גוזזי' נאלמה<sup data-n=\"120\">50</sup>, דלא רק <i>שהאלקות</i> אינו מאיר בגילוי אלא שגם <i>הקליפה</i> מסתרת על האלקות, קליפת נוגה שנקראת חש<sup data-n=\"121\">51</sup>, ועד שמתחברת עם גקה\"ט, רוש<sup data-n=\"122\">52</sup>.\nז) <b>ויש</b> לומר, דהטעם על זה שהמן הפיל פור בכדי להגיע לבחינת הגורל שלמעלה מהשתלשלות, אף שאז [בימי אחשורוש, גם קודם שהפיל פור] היתה ההנהגה מצד למעלה מהשתלשלות, הוא, לפי שבחינת הגורל הוא למעלה יותר גם מבחינת אחשורוש מי שאחרית וראשית שלו. והענין הוא, דמזה עצמו שנקרא בשם אחשורוש מי שאחרית וראשית שלו, מוכח, שגם לגבי' ישנם הענינים דאחרית וראשית<sup data-n=\"117\">47</sup>, אלא שהם שוין לגבי'. [ולהעיר ממ\"ש<sup data-n=\"123\">53</sup> עשה משתה לכל שריו ועבדיו ואח\"כ לכל העםהנמצאים בשושן, ומבואר בלקו\"ת<sup data-n=\"124\">54</sup> שהגילוי שהי' לכל העם הי' למטה במדריגה מהגילוי שהי' לשריו ועבדיו. ולהוסיף, שגם בהגילוי שהי' לכל העם היו כו\"כ חילוקי דרגות, הראוי לחצר לחצר הראוי לגינה לגינה הראוי לביתן לביתן<sup data-n=\"125\">55</sup>. ויש לומר, שמצד בחינת ההשתלשלות, הגילוי הוא רק לשרים ועבדים, וזה שהי' הגילוי גם לכל העם (ועד לאלה שראויים רק לחצר) הוא לפי שהגילוי הי' מבחי' אחשורוש שאחרית וראשית שלו. ומ\"מ הגילוי להעם הי' למטה מהגילוי לשריו ועבדיו (וגם בהגילוי להעם היו כמה דרגות), כי זה שאחרית וראשית שלו הוא <i>שלגבי'</i> אחרית וראשית הם בשוה, אבל בנוגע להגילוי שלו בעולמות, בעולמות העליונים (ראשית) הוא בגילוי יותר מבעולמות התחתונים (אחרית)<sup data-n=\"126\">56</sup>]. משא\"כ בבחינת הגורל אין מלכתחילה הענין דראשית ואחרית, כמובן מזה שהגורל הוא (בכלל) בשני דברים <i>שוים</i> (כנ\"ל סעיף ב). וכמו שהוא בנוגע להענינים דראשית ואחרית (מעלה ומטה), עד\"ז הוא בנוגע לקדושה וסט\"א, שמצד הדרגא דאחשורוש יש חילוק בין קדושה לסט\"א, אלא שמצד הרוממות שלו אין זה תופס מקום (כ\"כ), ולכן אפשר להיות יניקה גם לסט\"א [ח\"ש דק\"נ ורוש דגקה\"ט<sup data-n=\"127\">57</sup>], ועד שתהי' התגברות הסט\"א על הקדושה – הושחרו פניהם של ישראל<sup data-n=\"127\">57</sup> [וי\"ל ע\"ד שממית בידים תתפש והיא בהיכלי מלך<sup data-n=\"128\">58</sup> (אף שהיא מלכלכת את ההיכל), כי מצד רוממותו של המלך אינו נותן לב להקפיד לגרשה<sup data-n=\"129\">59</sup>], אבל לא להשמידם ח\"ו. וכשביקש המן להשמיד את כל היהודים (ח\"ו היל\"ת) הפיל פור הוא הגורל<sup data-n=\"130\">60</sup>, דכיון שבבחינת הגורל אין מלכתחילה חילוק בין קדושה לסט\"א [ובפרט לפי המבואר לעיל (סעיף ג' וד') שהגורל הוא לא רק למעלה מהשתלשלות אלא למעלה גם מהרצון דתומ\"צ], לכן חשב שעי\"ז יוכל ח\"ו להפיק את זממו.\nח) <b>והנה</b> כמו שגורל הוא למעלה מהשכל ולמעלה גם מהרצון, עד\"ז הוא בנוגע לבחירה שהוא למעלה משכל ולמעלה גם מרצון.דכאשר שכלו מחייב שדבר זה ראוי לבחור בו, וגם כשהוא רוצה באיזה דבר (רצון שלמעלה מהשכל), הרי הוא מוכרח בזה ואין זה בחירה חפשית, ואמיתית ענין הבחירה הוא כשהבחירה שלו היא לא מצד השכל וגם לא מצד הרצון<sup data-n=\"131\">61</sup>, אלא שכך בוחר בבחירתו החפשית. והחילוק בין גורל ובחירה הוא, דכשאדם עושה גורל ומחליט דכמו שיפול הגורל כן יהי' רצונו, הרצון שלו הוא לא מצד האדם אלא מפני שכן נפל הגורל, ובחירה היא <i>שהאדם</i> הוא הבוחר. ומזה מובן, דבחירה היא למעלה מגורל. דגורל הוא הדרגא בנפש שהיא <i>מוגדרת ומוכרחת</i> בזה ששני הדברים הם שוים לגבה, וענין הבחירה הוא <i>שאינו</i> מוגדר ומוכרח באיזה דברים, כולל דברים שוים לגבי', וביכלתו לבחור במה שירצה.\n<b>ויש</b> לומר, דבבחירה ישנם שני הענינים. הדרגא דנפש שלמעלה משכל שלגבה שני הדברים הם בשוה – דרגת הגורל, וזה שהוא בוחר כמו שרוצה (הגם ששני הדברים הם שוים (לגבי')) הוא בא מעצם הנפש. וע\"י הבחירה, ההמשכה מהעצם להדרגא דגורל (הדרגא שלגבה שני הדברים הם בשוה), גם הגורל (הגם שמצד עצמו אפשר להיות בשני האופנים) הוא כפי הבחירה. וע\"ד מ\"ש<sup data-n=\"132\">62</sup> אתה תומיך גורלי, שהקב\"ה תומך את הגורל שיהי' כפי בחירת העצמות. וזהו מ\"ש<sup data-n=\"133\">63</sup> יבחר לנו את נחלתינו את גאון יעקב גו', דביעקב כתיב<sup data-n=\"134\">64</sup> יעקב חבל נחלתו ותרגם אונקלוס יעקב עדב אחסנתי' דעדב הוא גורל<sup data-n=\"135\">65</sup>, וענין יבחר גו' את גאון יעקב הוא<sup data-n=\"136\">66</sup>, שגם בדרגת הגורל שלמעלה מהשתלשלות שהכל שוים שם, הבחירה היא בישראל דוקא.\nט) <b>וזהו</b> על כן קראו לימים האלה פורים על שם הפור, שנפילת הגורל למעלה היתה כפי כוונת ובחירת העצמות, דהגם שאח עשו ליעקב מ\"מ ואוהב את יעקב ואת עשו שנאתי<sup data-n=\"137\">67</sup>. דע\"י המס\"נ דישראל במשך כל השנה<sup data-n=\"138\">68</sup>, דענין המס\"נ הוא מעצם הנשמה, היינו מצד הבחירהדעצם הנשמה בהעצמות<sup data-n=\"139\">69</sup>, עי\"ז נמשך ונתגלה בחירת העצמות בישראל, ועי\"ז, גם הגורל דלמעלה הי' שליהודים יהי' אורה ושמחה וששון ויקר<sup data-n=\"140\">70</sup>, ואת המן ואת בניו יתלו על העץ<sup data-n=\"141\">71</sup>. ומדייק הכתוב <i>ה</i>פור בה\"א הידיעה שקאי על הפור שהפיל המן (כנ\"ל סעיף ה), כי ע\"י הנס דפורים נתגלה שגם הפור שהפיל המן הי' מלכתחילה בשביל הגילוי דבחירת העצמות בישראל. וזהו שנפל הפור בחודש אדר, החודש שבו נולד מושיען של ישראל, כי נפילת הפור מלכתחילה היתה בכדי שיתגלה שגם הפור עצמו, אף שיש בו מקום לשני הצדדים [ויתירה מזה שבחיצוניות הי' נראה שהפור הוא לטובתו של המן ועד שהיתה הגזירה], הפנימיות של הפור הי' גם מלכתחילה כפי בחירת העצמות, ואוהב את יעקב ואת עשו שנאתי.\n<b>ועד\"ז</b> הוא בנוגע להעץ אשר הכין לו<sup data-n=\"142\">72</sup>, לו לעצמו<sup data-n=\"143\">73</sup>, דהטעם שעשה עץ גבוה חמישים אמה הוא<sup data-n=\"144\">74</sup> כי רצה להגיע לשער הנו\"ן שלמעלה מהשתלשלות ששם הוא כחשיכה כאורה, והנס דפורים הי' שגם מצד הדרגא דלמעלה מהשתלשלות (גורל, שער הנו\"ן) תלו את המן על העץ, ואז נתגלה שגם זה שהכין העץ מלכתחילה הי' לו, לעצמו.\n<b>וזהו</b> ענין פורים, שבימי הפורים בכל שנה ושנה, נמשך שגם בדרגת הפור שלמעלה מהשתלשלות יהי' יבחר לנו את נחלתינו את גאון יעקב גו' ומחה אמחה את זכר עמלק גו'<sup data-n=\"145\">75</sup>, בגאולה השלימה בקרוב ממש.\n**********",[["70","*","המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א לקראת פורים ה'תנש\"א (המו\"ל)."],["71","1","אסתר ט, כו."],["72","2","ראה שעהיוה\"א פ\"א. תשובות וביאורים (קה\"ת תשל\"ד) סימן א' (אגרות-קודש ח\"א ס\"ע רפח ואילך)."],["73","3","אסתר ג, ז. ט, כד."],["74","4","בהוספות קכב, א ואילך. וכן מדייק בד\"ה זה באוה\"ת מג\"א (קה\"ת, תש\"נ) ע' קצד. [ד\"ה הנ\"ל שבתו\"א ישנו גם (בשינויים) בסה\"מ תקס\"ח ח\"א ע' פב ואילך. ועם הגהות וכו' – באוה\"ת שם ע' קצז ואילך. שם ס\"ע רכב ואילך]."],["75","5","כ\"ה בתו\"א, סה\"מ תקס\"ח ואוה\"ת שם. ואולי אפ\"ל, שגם זה שנפל הפור בחודש אדר, הוא נס (כדלקמן בפנים), ולכן מדייק שאין זה <i>עיקר</i> הנס."],["76","6","ט, כד."],["77","7","מגילה יג, ב."],["78","8","מג\"א צב, ד. שם צה, סע\"ד. הוספות קכא, א."],["79","9","ראה גם תקו\"ז תכ\"א (נז, ב) \"פורים אתקריאת על שם יום הכפורים\". ולכאורה, פירוש התקו\"ז ופירוש התו\"א שבהערה הבאה ש\"<i>כ</i>פורים\" הוא כמו פורים, הם שני פירושים הפכים. דלפירוש התקו\"ז שפורים נקרא על שם יום הכפורים – יוהכ\"פ הוא למעלה מפורים, ולפירוש התו\"א שיום הכפורים הוא <i>כ</i>פורים (בכ\"ף הדמיון בלבד) – פורים הוא למעלה מיוהכ\"פ.\nוהנה בתקו\"ז שם \"פורים אתקריאת על שם יום הכפורים דעתידין לאתענגא בי' ולשינויי לי' מעינוי לעונג\". ועפ\"ז הי' אפ\"ל (בדוחק עכ\"פ), דמ\"ש בתו\"א שיוהכ\"פ הוא <i>כמו</i> פורים – הוא בנוגע ליוהכ\"פ כמו שהוא עכשיו (יום עינוי), ומ\"ש בתקו\"ז שיוהכ\"פ הוא למעלה מפורים – הוא בנוגע ליוהכ\"פ כמו שיהי' לע\"ל דעתידין לאתענגא כו'. אבל, להביאור דלקמן ס\"ד [שהגורל דיוהכ\"פ הוא רק בנוגע לשני השעירים], וכן להביאור שבתורת שלום שבהערה 30, אין חילוק לכאורה בין יוהכ\"פ עכשיו ליוהכ\"פ לע\"ל, וכמובן גם מזה שגם לע\"ל יהי' נקרא בשם יום <i>כ</i>פורים."],["80","10","תו\"א שם קכא, א. ולהעיר מהדיעה (מדרש משלי פ\"ט) שכל המועדים עתידים להבטל, גם יוהכ\"פ, חוץ מפורים."],["81","11","אחרי טז, ח ואילך."],["82","12","אוה\"ת ויצא רכה, א. מג\"א ע' קפט. וראה גם אוה\"ת תבוא שבהערה 17."],["83","13","אחרי טז, ל."],["84","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380198\" data-slug=\"likkutei-torah\" data-id=\"4001380198\">לקו\"ת אחרי כח, סע\"ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380958\" data-slug=\"likkutei-torah\" data-id=\"4001380958\">ר\"ה נט, סע\"ד</a>. וראה גם אוה\"ת שבהערה 12. ובכ\"מ."],["85","15","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370447\" data-slug=\"torah-or\" data-id=\"3901370447\">תו\"א מג\"א ק, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370541\" data-slug=\"torah-or\" data-id=\"3901370541\">קכא, רע\"ג</a>. ובכ\"מ."],["86","16","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211201\" data-slug=\"likkutei-sichot\" data-id=\"1300211201\">לקו\"ש חכ\"א ע' 201</a>, ובהנסמן בהערות שם."],["87","17","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450638\" data-slug=\"or-hatorah-hb\" data-id=\"8316450638\">אוה\"ת תבוא ע' תתשח</a> \"יוהכ\"פ ופורים בחד דרגא, כי ביוהכ\"פ לפני הוי' תטהרו, וכן בפורים פור הוא הגורל\". דמזה משמע ש\"לפני הוי'\" וגורל הם (בכללות) ענין אחד."],["88","18","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370539\" data-slug=\"torah-or\" data-id=\"3901370539\">תו\"א</a> מג\"א (הוספות) קכא, א. שם קכג, ג. אוה\"ת מג\"א ע' כח. שם ע' סב ואילך. שם ע' קסד (בענין גורל <i>דפורים</i>). וראה גם אגה\"ק סוס\"ז. ספר הליקוטים – דא\"ח צ\"צ ערך גורל. סה\"מ תרס\"ה ע' רו. תרפ\"ח ע' קיז ואילך. ועוד."],["89","19","אבל <i>שייך</i> גם בדברים שאינם שוים – אף שאז מחייב השכל שצריך לבחור בזה שהואטוב יותר – כי לפעמים מחליט שהרצון שלו יהי' לא כמו שהשכל מחייב אלא כמו שיפול הגורל. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370549\" data-slug=\"torah-or\" data-id=\"3901370549\">תו\"א מג\"א קכג, ג</a> \"<i>שמבטל</i> הבחירה שע\"פ הדעת אלא יתלה הדבר רק כמו שהוא יפיל הגורל גם שיהי' לנגד הדעת\". וראה הערה הבאה."],["90","20","יומא סב, א (במשנה). רמב\"ם הל' עבודת יוהכ\"פ פ\"ה הי\"ד.\nוזה שבדיעבד גם כשאינם שוים הם כשרים (יומא שם, רמב\"ם שם), הוא – כי גם אז שייך ענין הגורל, כבהערה הקודמת. אלא <i>שמצותן</i> שיהיו שניהם שוין – כי גורל <i>בכלל</i> הוא בשוין."],["91","21","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370447\" data-slug=\"torah-or\" data-id=\"3901370447\">תו\"א מג\"א ק, ב</a>."],["92","22","שם קכא, א. אוה\"ת מג\"א ע' כח. קסד. קסז. קעא."],["93","23","אגה\"ת פ\"ד (צד, ב)."],["94","24","ראה גם אוה\"ת שם ע' כח \"לפני הוי', למעלה מבחי' שם הוי', שהיו\"ד הוא בחי' חכמה ורצון*, כ\"א בחי' בעל הרצון\".\n*) <i>לכאורה הכוונה להיו\"ד וקוצו</i>."],["95","25","ראה בארוכה סה\"מ מלוקט ח\"ד ע' ז. וש\"נ."],["96","26","ראה גם סה\"מ תרכ\"ח ע' קי וסה\"מ תרס\"א ע' ריט, דיוהכ\"פ אינו מכפר על הכל [דבעבר על כריתות ומיתות ב\"ד, גמר כפרתו היא ע\"י יסורים, וכשחילל את השם גמר כפרתו היא ע\"י מיתה (יומא פו, א. רמב\"ם הל' תשובה פ\"א ה\"ד)], ובימי הפורים, אף שהחטא שלהם הי' שנהנו מסעודתו של אותו רשע (מגילה יב, א) שזה הי' חילול ש\"ש בפרהסיא, מ\"מ נתכפר להם גם זה. והחידוש שבפנים (ע\"פ תו\"א שבהערה 28) הוא, שגם בהעבירות שיוהכ\"פ מכפר, יש מעלה בפורים לגבי יוהכ\"פ."],["97","27","ראה יומא פה, ב. רמב\"ם שם ה\"ג-ד. ולהעיר מתוספות ישנים יומא שם, שגם לדעת רבי \"צריך תשובה לכפרה <i>גמורה</i>\"."],["98","28","כן משמע ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370539\" data-slug=\"torah-or\" data-id=\"3901370539\">תו\"א מג\"א קכא, א</a>."],["99","29","בתו\"א שם משמע שהכפרה בימי הפורים היתה ע\"י המס\"נ שלהם. ויש לומר, שעיקר הכפרה היתה מצד הגורל (המשכה מבעל הרצון), וזה שהוצרכו גם למס\"נ – ראה לקמן ס\"ט. ועצ\"ע."],["100","30","ולהעיר מסה\"ש תורת שלום ע' 219, שגם בהגורל עצמו יש חילוק בין הגורל דיוהכ\"פ והגורל דפורים. <i>עיי\"ש</i>."],["101","31","ראה ד\"ה חייב אינש עטר\"ת סוס\"ג (סה\"מ עטר\"ת ע' שו), תרפ\"א (תש\"ח) סוס\"ד (סה\"מ תרפ\"א ע' קצא. ה'תש\"ח ע' 118). ד\"ה בלילה ההוא ה'ש\"ת (סה\"מ ה'ש\"ת ריש ע' 9). ובכ\"מ."],["102","32","עירובין יט, א. חגיגה בסופה."],["103","33","תבוא כו, טו. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370161\" data-slug=\"torah-or\" data-id=\"3901370161\">תו\"א מקץ לה, א</a>. סה\"מ עטר\"ת שם (ע' שה). ה'ש\"ת שם (ע' 6)."],["104","34","חגיגה יב, א."],["105","35","ויש לומר, דמ\"ש \"וברך <i>את עמך</i> את ישראל\" הוא לרמז, שמצד בחינת \"שמים\" נשפעים הברכות גם לאלה שהם בחינת \"עם\" – דשם עם מורה על היפך השבח (במדב\"ר פ\"כ, כג) – כי גם הם מלאים מצוות כרמון, כנ\"ל בפנים."],["106","36","תהלים קלט, יב."],["107","37","אוה\"ת מג\"א ס\"ע כד ואילך."],["108","38","כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370527\" data-slug=\"torah-or\" data-id=\"3901370527\">תו\"א</a> מג\"א (הוספות) קיח, א. אבל הביאור שם הוא באופן אחר."],["109","39","חגיגה יג, סע\"א ואילך."],["110","40","ראה חגיגה שם (ריש ע\"ב) \"בשעה שהדיבור יוצא מפי הקב\"ה חשות ובשעה שאין הדיבור יוצא מפי הקב\"ה ממללות\", שמזה מובן שהשתיקה דחש היא למעלה מדיבור. וראה תו\"א שבהערה 44."],["111","41","מגילה יח, א."],["112","42","אגה\"ק ס\"ה (קז, א)."],["113","43","אבות פ\"ג מי\"ג."],["114","44","ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370053\" data-slug=\"torah-or\" data-id=\"3901370053\">תו\"א לך לך (יב, סע\"ב</a>. שם, ד) בענין חש דחשמל שהו\"ע סיג לחכמה שתיקה."],["115","45","הובא במאו\"א ע' א אות קפב. וראה גם מחיר יין להרמ\"א עה\"פ אסתר א, יב-יג, מרקאנטי ויצא כט, י (\"באגדה אמרו\"). ערכי הכינויים (לבעל סדר הדורות) ערך אחשורוש."],["116","46","להעיר מאוה\"ת שמביא שם בחצע\"ג (לפי הפירוש שאחשורוש הוא אחש ורוש) שאחשורוש הוא זה שאחרית וראשית שלו."],["117","47","ראה סה\"מ תרס\"ט ס\"ע קנד ואילך."],["118","48","מגילה יא, א."],["119","49","ראה אוה\"ת מג\"א ע' א-ב בענין ב' הבחינות דשתיקה (שלמעלה מדיבור ושלמטה מדיבור)."],["120","50","ישעי' נג, ז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380682\" data-slug=\"likkutei-torah\" data-id=\"4001380682\">לקו\"ת מסעי פט, ג</a>."],["121","51","ע\"ח שער מ\"ט (שער ק\"נ) פ\"ג."],["122","52","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830002\" data-slug=\"or-hatorah-hb\" data-id=\"8158830002\">אוה\"ת שם (ע' ב</a>)."],["123","53","אסתר א, ג-ה."],["124","54","שמע\"צ צב, א – הובא באוה\"ת מג\"א ע' כז."],["125","55","מגילה יב, א."],["126","56","להעיר מהמשך תרס\"ו ע' נה, \"דעם היות דסוכ\"ע הוא למעלה כמו למטה, מ\"מ למטה הוא נמצא בהעלם ולמעלה מאיר בגילוי יותר\"."],["127","57","ראה לעיל ס\"ו."],["128","58","משלי ל, כח."],["129","59","סהמ\"צ להצ\"צ עז, ב. ובכ\"מ."],["130","60","אסתר ג, ו-ז.\nויש לומר דזהו מ\"ש \"בשנת שתים עשרה למלך אחשורוש הפיל פור גו'\", דנוסף על \"בשנת גו' למלך <i>אחשורוש</i>\" – \"הפיל פור הוא הגורל גו'\"."],["131","61","ראה סה\"מ ה'תש\"ג ע' 24 דענין הבחירה הוא \"שיכול לרצות ולא לרצות\"."],["132","62","תהלים טז, ה."],["133","63","שם מז, ה."],["134","64","האזינו לב, ט."],["135","65","ראה תרגום אחרי טז, ח. וראה גם ספרי האזינו שם \"אין חבל אלא גורל\". ובפירוש הראב\"ע שם \"חבל כמו גורל\"."],["136","66","ולהעיר מאוה\"ת מג\"א ע' סג."],["137","67","מלאכי א, ב-ג."],["138","68","ראה סה\"מ מלוקט ח\"ב ע' ער. <i>וש\"נ</i>."],["139","69","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא ספי\"ח</a> \"<i>שאי אפשר כלל</i> לכפור בה' אחד\". ומבואר במק\"א (ראה סה\"מ מלוקט ח\"ג ע' כז) דכיון שמס\"נ הוא גילוי היחידה שאין כנגדה לעו\"ז (בבואה דבבואה לית להו), לכן המס\"נ שלו הוא באופן <i>שאינו יכול</i> להיות נפרד ח\"ו.\nאבל מכיון שענין הבחירה הוא \"עמוד התורה והמצוה\" (רמב\"ם הל' תשובה פ\"ה ה\"ג), והבחירה היא מעיקרי מעלת עבודת האדם (סה\"מ תר\"ס ע' ח ואילך) – צריך לומר (וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041339\" data-slug=\"likkutei-sichot\" data-id=\"1300041339\">לקו\"ש ח\"ד ע' 1340</a> ואילך ושם בהערה 14), דזה שמצד היחידה <i>א\"א</i> להיות באופן אחר, אין זה שהיא <i>מוכרחת</i> בזה, אלא <i>שהבחירה</i> שלה בהעצמות <i>היא</i> השוללת שלא יהי' נתינת מקום ואפשרות להיות נפרד ח\"ו [וע\"ד \"להחליפם באומה אחרת <i>איני יכול</i>\" (פתיחתא דרות רבה ג. ובכ\"מ) שזהו מצד הבחירה שהקב\"ה בחר בישראל בבחירתו החפשית]. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191294\" data-slug=\"likkutei-sichot\" data-id=\"1300191294\">לקו\"ש חי\"ט ע' 281</a> ואילך ובהערות שם."],["140","70","אסתר ח, טז."],["141","71","שם ז, יו\"ד. ט, יד."],["142","72","שם ו, ד."],["143","73","ראה מגילה טז, א ובפרש\"י שם. וראה חדא\"ג מהרש\"א שם."],["144","74","סה\"מ ה'ש\"ת ע' 9-10."],["145","75","בשלח יז, יד (קרה\"ת דפורים)."]]],[1400140007,"בלתי מוגה\n<b>א</b>. כ\"ק אדמו\"ר שליט\"א נטל ידיו הק' לסעודה. ואח\"כ צוה לנגן ואמר מאמר ד\"ה ויהי אומן את הדסה.\n***\n<b>ב</b>. דובר לעיל (בהמאמר<sup data-n=\"146\">1</sup>) שפורים הוא בדרגא נעלית יותר ממתן תורה, כמובן ממ\"ש<sup data-n=\"147\">2</sup> \"וקבל היהודים את אשר החלו לעשות\", היינו, שבמ\"ת היתה התחלה בלבד (\"החלו\"), ובפורים היתה \"קבלה גמורה\"<sup data-n=\"148\">3</sup>, שמזה מובן שמ\"ת ופורים שייכים זל\"ז, שענינם אחד, אלא שפורים הוא בדרגא נעלית יותר.\nומהענינים בזה:\nמ\"ת ופורים – ענינם מסירת נפש: במ\"ת – כמארז\"ל<sup data-n=\"149\">4</sup> \"על כל דיבור ודיבור פרחה נשמתן\", ובפורים – שאף שהיתה הגזירה \"להשמיד להרוג ולאבד את כל היהודים\", \"מנער ועד זקן טף ונשים\"<sup data-n=\"150\">5</sup>, מ\"מ, מסרו נפשם על קידוש השם (שהרי אם רצו להמיר דתם לא הי' המן עושה להם כלום, שלא גזר אלא על היהודים, אלא שהם מסרו עצמן למות כל השנה כולה), ולא עלה להם מחשבת חוץ ח\"ו<sup data-n=\"151\">6</sup>.\nאבל אעפ\"כ, המס\"נ דמ\"ת אינה מגעת להמס\"נ דפורים, כי:\nהמס\"נ דמ\"ת היא: (א) מס\"נ בכח, היינו, מצד הנשמה – \"פרחה נשמתם\", (ב) והתעוררות המס\"נ באה מצד הגילויים מלמעלה – \"על כל דיבור ודיבור\", וכן כללות הענין ד\"כפה עליהם הר כגיגית\"<sup data-n=\"152\">7</sup>, שהו\"ע התגלות האהבה העליונה כו'<sup data-n=\"153\">8</sup>;\nמשא\"כ המס\"נ דפורים היא: (א) מס\"נ בפועל, מצד הגוף (שהרי הגזירה \"להשמיד גו'\" היתה על הגופים, ובמילא, זה שלא עלה להם מחשבת חוץ הו\"ע של מס\"נ בפועל, מצד הגוף), (ב) והתעוררות המס\"נבאה (לא מצד הגילויים מלמעלה, אלא) מצד עבודתם ויגיעתם של בנ\"י בכח עצמם.\n<b>ג</b>. ומזה מובן גם בנוגע לעבודה דפורים בכל שנה ושנה, כמ\"ש<sup data-n=\"154\">9</sup> \"והימים האלה נזכרים ונעשים בכל דור ודור\":\nכ\"ק מו\"ח אדמו\"ר אומר בא' משיחותיו<sup data-n=\"155\">10</sup>, שגם עתה ישנה מחשבת המן להשמיד להרוג ולאבד ח\"ו, ובמילא, צריכה להיות גם עתה העבודה דפורים – ענין המס\"נ בפועל, ובאופן של עבודה בכח עצמו, היינו, שלא להמתין על התעוררות מלמעלה, אלא לעמוד תמיד במעמד ומצב שמוכן הוא למסור נפשו בפועל.\nוהיינו, שנוסף על המס\"נ שבכל יום בעבודה דק\"ש, ומודגש באופן נעלה יותר באמירת \"שמע ישראל גו' הוי' אחד\"<sup data-n=\"156\">11</sup> ביוהכ\"פ, כמבואר בחסידות<sup data-n=\"157\">12</sup> שאפילו קל שבקלים עומד בתנועה של מס\"נ באמירת שמע ישראל ביוהכ\"פ – שכל זה הו\"ע של מס\"נ בכח, ומצד הגילויים מלמעלה – צריכה להיות גם העבודה שנפעלת בימי הפורים, שהו\"ע המס\"נ בפועל, ומצד עבודה בכח עצמו.\n<b>ד</b>. והנה, א' הענינים שבהם מתבטא אופן העבודה דמס\"נ, הוא, כאשר העבודה היא שלא בסדר והדרגה.\nולדוגמא – בנוגע ללימוד תורת החסידות, שישנם הטוענים שתחילה צריכים למלא כרסם בש\"ס ופוסקים, ואח\"כ ילמדו גם חסידות. ומסתייעים בזה מפס\"ד השו\"ע בהל' תלמוד תורה<sup data-n=\"158\">13</sup>.\nוהמענה לזה – שהעבודה צריכה להיות שלא בסדר והדרגה, שכן, כשם שהקלקול הי' שלא בסדר והדרגה, הנה גם התיקון צריך להיות שלא בסדר והדרגה. וע\"ד מ\"ש הרמב\"ם<sup data-n=\"159\">14</sup> שאף ש\"הדרך הישרה היא מדה בינונית שבכל דעה ודעה . . שהיא רחוקה משתי הקצוות כו'\", מ\"מ, \"אם הי' רחוק לקצה האחד, ירחיק עצמו לקצה השני וינהוג בו זמן רב עד שיחזור לדרך הטובה והיא מדה בינונית כו'\".\nובנוגע לעניננו: כיון שהעבודה צריכה להיות שלא בסדר והדרגה– אין להמתין עם לימוד תורת החסידות עד לאחר מילוי כרסו בש\"ס ופוסקים, אלא צריכים ללמוד תורת החסידות בד בבד עם לימוד ש\"ס ופוסקים.\n<b>ה</b>. ויש להוסיף עוד ענין בזה – בקשר ובשייכות לעניני הפורים:\nאיתא בגמרא<sup data-n=\"160\">15</sup> \"פורים שחל להיות בערב שבת רב אמר מקדימין (קריאת) פרשת זכור (לשבת שלפנ\"ז), ושמואל אמר מאחרין (שקורין פרשת זכור בשבת שלמחרת פורים). רב אמר מקדימין, כי היכי דלא תיקדום עשי' לזכירה [שאם יקראו פרשת זכור בשבת למחרת פורים, נמצא שקדמה עשי' (קיום המצוות דפורים, משתה ושמחה ומשלוח מנות וכו') לזכירה (פרשת זכור), וקרא אמר \"והימים האלה נזכרים ונעשים\", מעיקרא זכירה ואח\"כ עשי']. ושמואל אמר מאחרין, אמר לך, כיון דאיכא מוקפין דעבדי בחמיסר, עשי' וזכירה בהדי הדדי אתיין . . חל להיות (פורים) בשבת עצמה, אמר ר\"ה לדברי הכל אין מקדימין (\"דהא השתא לא קדמה עשי' לזכירה, וגבי מוקפין קדמה זכירה לעשי'\"<sup data-n=\"161\">16</sup>), ורב נחמן אמר עדיין היא מחלוקת\" (\"אף בזו אמר רב מקדימין, כדי שתקדם זכירה לעשי' דעיירות\"<sup data-n=\"161\">16</sup>).\nוענין זה תלוי בהחקירה הידועה<sup data-n=\"162\">17</sup> בנוגע לדברים שצריכים להעשות זה אחר זה – אי מהני כשנעשים בבת אחת. כלומר: האם החיוב הוא שענין זה יבוא <i>אחר</i> ענין זה דוקא, ובמילא, אם באים בבת אחת, לא מהני, או ש\"זה <i>אחר</i> זה\" לאו דוקא, אלא עיקר העיכוב הוא שהמאוחר לא יהי' לפני המוקדם, ובמילא, אם באים בבת אחת, שפיר דמי.\nועד\"ז בנוגע לזכירה ועשי' (\"נזכרים ונעשים\") – האם יש הכרח בהקדמת הזכירה דוקא, או שעיקר העיכוב הוא ש\"לא תיקדום עשי' לזכירה\", אבל אם לא קדמה עשי' לזכירה אלא בהדי הדדי אתיין, שפיר דמי.\nובנוגע לעניננו: להדעה ש\"אחר זה\" לאו דוקא, אלא עיקר העיכוב הוא שהמאוחר לא יהי' לפני המוקדם – יכולים שפיר לעשות שניהם יחד: למלא כרסו בש\"ס ופוסקים, ובה בשעה לעסוק גם בלימוד ועבודת החסידות<sup data-n=\"163\">18</sup>.\n***<b>ו</b>. בנוגע לקריאת המגילה – איתא במשנה<sup data-n=\"164\">19</sup>: \"מהיכן קורא אדם את המגילה ויוצא בה י\"ח, ר\"מ אומר כולה, ר' יהודה אומר מאיש יהודי, רבי יוסי אומר מאחר הדברים האלה\". ובגמרא<sup data-n=\"165\">20</sup>: \"וכולן מקרא אחד דרשו, ותכתוב אסתר המלכה ומרדכי היהודי את כל תוקף<sup data-n=\"166\">21</sup> (על תוקף הקפיד להזכיר), מאן דאמר כולה, תוקפו של אחשורוש (ומתחילתה היא מדברת בתוקפו עד סופה), ומאן דאמר מאיש יהודי, תוקפו של מרדכי וכו'\".\nוכיון שההלכה היא שחייבים לקרוא את המגילה כולה<sup data-n=\"167\">22</sup>, מוכח, שצריכים להזכיר \"תוקפו של אחשורוש\".\nולכאורה צריך להבין:\nבשלמא \"תוקפו של מרדכי\" – ה\"ז ענין הקשור עם תוקף הנצחיות דבנ\"י, והיינו, שהנשמה היא נצחית, ובמילא, גם הגוף – שעמו קשורה הנשמה, ועל ידו עובדת עבודתה בקיום התומ\"צ (כמבואר בתניא<sup data-n=\"168\">23</sup> שאי אפשר לנשמה לקיים מצוות מעשיות אלא ע\"י התלבשותה בגוף) – נצחי הוא, שזהו\"ע תחיית המתים, שהגוף הגשמי (שבו ועל ידו עבדה הנשמה עבודתה כל משך חיי האדם) יקום לתחי'.\nאבל מהו תוכן הענין שצריכים להזכיר \"תוקפו של אחשורוש\"?\n<b>ז</b>. ויובן בהקדם ב' הפירושים ב\"אחשורוש\":\nבמאורי אור<sup data-n=\"169\">24</sup> איתא (בשם המדרש) ש\"אחשורוש\" קאי על הקב\"ה, \"שאחרית וראשית שלו\".\nובמדרש<sup data-n=\"170\">25</sup> איתא \"כל מקום שנאמר במגילה זו למלך אחשורוש, במלך אחשורוש (כפשוטו, מלך מדי ופרס) הכתוב מדבר, וכל מקום שנאמר למלך סתם, משמש קודש (וחול)\", היינו, שקאי (לפעמים) על הקב\"ה, \"מלכו של עולם\"<sup data-n=\"171\">26</sup>.\nוב' פירושים אלו – אם אחשורוש קאי על הקב\"ה או להבדיל על מלך מדי ופרס – לא זו בלבד שאינם סותרים זל\"ז, אלא מתאימים ותלויים זב\"ז, כדלקמן.\n<b>ח</b>. ובהקדמה – שכאשר הקב\"ה בוחר בדבר מסויים למלאשליחות שלו, אזי הדבר (שעל ידו מתמלאת השליחות) טפל ובטל להשליחות, וגם כאשר מציאות הדבר בעוה\"ז היא במדה גדולה יותר מהשליחות שמתבצעת על ידה, מ\"מ, טפלה ובטלה היא להשליחות,\n– וע\"ד שמצינו בהלכות שבת לענין מלאכת הוצאה, ש\"המוציא אוכלין פחות מכשיעור בכלי (שיש בו שיעור), פטור אף על הכלי, שהכלי טפלה לו\"<sup data-n=\"172\">27</sup>, והיינו, שעם היות הכלי גדול יותר מהאוכלין שבו, מ\"מ, כיון שכוונתו בהוצאת הכלי היא בשביל האוכלין, והכלי הוא <i>משמש</i> להאוכל, אזי הכלי טפל להאוכלין. ועד\"ז מצינו בהלכות ברכות הנהנין, שהברכה על העיקר פוטרת את הטפל, גם כאשר הטפל גדול בכמות יותר מן העיקר, כיון שאצל האדם האוכלו נחשב הוא לטפל<sup data-n=\"173\">28</sup>. ואם הדברים אמורים בעניני העולם, עאכו\"כ בעניני רשות וחול המשמשים לעניני קדושה, שהם טפלים ובטלים אל הקדושה. –\nועד שכל מציאותה היא – השליחות,\nולכן, המעלה שישנה בהשליחות, נעשית גם בהדבר שעל ידו מתמלאת השליחות (שכל מציאותו היא השליחות) – ע\"ד המבואר בתניא<sup data-n=\"174\">29</sup> לענין בירור וזיכוך הגוף, שכיון שלימוד התורה וקיום המצוות נעשה ע\"י הגוף (שהרי גם לימוד התורה צ\"ל בדיבור, ועקימת שפתיו הוי מעשה<sup data-n=\"175\">30</sup>, ועאכו\"כ מצוות מעשיות ממש), הנה גם הגוף מתברר ומזדכך כו'.\n<b>ט</b>. ועפ\"ז יש לבאר הקשר והשייכות דב' הפירושים ב\"אחשורוש\":\n\"אחשורוש\" – קאי אמנם על אחשורוש כפשוטו, מלך מדי ופרס;\nאבל, כיון שכל מציאותו של אחשורוש היא שעל ידו הי' הנס דפורים, ועל ידו ניתוספה מצוה מדרבנן, שעל זה אמרו חז\"ל<sup data-n=\"176\">31</sup> חביבין וחמורין עלי דברי סופרים כו',\n– [ולהעיר מדברי הגמרא<sup data-n=\"177\">32</sup> \"מגילה נקראת ספר ונקראת אגרת\", ומבואר בחסידות<sup data-n=\"178\">33</sup> \"ההפרש בין בחי' ספר לבחי' אגרת . . ממה שאנו רואים שהספר הוא נצחי . . אך האגרת אינו נכתב אלא לפי שעה בלבדולא להתקיים כלל כי הרי אחר קריאתו את האגרת יקחנו וישרפנו או משליכו ואין צריך לו עוד לעולם כו'\", והמגילה – אף שנקראת בשם \"אגרת\", נקראת גם בשם \"ספר\", כפי שלמדים ממ\"ש<sup data-n=\"179\">34</sup> \"כתוב זאת זכרון בספר\", \"בספר מה שכתוב במגילה\"<sup data-n=\"180\">35</sup>],\nלכן, שייך שפיר לומר ש\"אחשורוש\" – שכל מציאותו היא שעל ידו הי' הנס דפורים – הוא מי שאחרית וראשית שלו.\nוזהו תוכן הענין דהזכרת \"תוקפו של אחשורוש\" – כי, גם להפירוש דאחשורוש כפשוטו, מלך מדי ופרס, מתגלה ומתבטא על ידו \"תוקפו של אחשורוש\", שאחרית וראשית שלו.\n<b>י</b>. וזהו מ\"ש<sup data-n=\"181\">36</sup> \"הוא אחשורוש המולך מהודו ועד כוש\" – דכיון שאחשורוש הוא \"מי שאחרית וראשית שלו\", לכן הוא \"מולך מהודו ועד כוש\":\n\"הודו\" ו\"כוש\" הם ב' הפכים, כי: \"כוש\" – מלשון שחרות, כמ\"ש \"כי אשה כושית לקח\"<sup data-n=\"182\">37</sup>, \"היהפוך כושי עורו\"<sup data-n=\"183\">38</sup> – מורה על דרגא תחתונה כו'. ו\"הודו\" – מלשון הודאה, למעלה מטעם ודעת – מורה על דרגא נעלית בקדושה.\nואחשורוש הוא \"המולך מהודו ועד כוש\", כי, אחשורוש \"שאחרית וראשית שלו\" קאי על דרגא שלמעלה מהשתלשלות, ששם אין הגבלות דאחרית וראשית (מטה ומעלה), וע\"ד מ\"ש<sup data-n=\"184\">39</sup> \"אני ראשון ואני אחרון\", שראשון ואחרון בהשואה, ולכן הוא המולך מהודו ועד כוש, מעומק רום עד עומק שפלות<sup data-n=\"185\">40</sup>.\n<b>יא</b>. וב' ענינים אלה (ראשית ואחרית, הודו וכוש) ישנם גם אצל בנ\"י שעליהם נאמר<sup data-n=\"186\">41</sup> \"בנים אתם להוי' אלקיכם\" – שיש בהם ענין ההודאה וביטול לאלקות, וביחד עם זה, יש להם גם כח הבחירה [שנלקח מהבחירה שבעצמותו ית'<sup data-n=\"187\">42</sup>, ולכן ניתן רק לבנ\"י, להיותם מושרשים בהעצמות שבחר בישראל עמו] לבחור בההיפך ח\"ו, בחי' כוש.\nוהנה, בזמן שלפני פורים עירבבו בנ\"י ב' הענינים דהודו וכוש:מחד גיסא – הי' זה הזמן שקודם ובסמיכות להגאולה (מגלות בבל), בחי' הודו, ולאידך גיסא – נהנו מסעודתו של אותו רשע<sup data-n=\"188\">43</sup>, בחי' כוש.\nומצד זה גרמו נתינת כח ללעו\"ז – שהרי החיות והיניקה שנמשכת ללעו\"ז היא באמצעות בנ\"י<sup data-n=\"189\">44</sup> – שאחשורוש (כפשוטו) המולך מהודו ועד כוש, גזר גזירה על בנ\"י.\nאמנם, עי\"ז שעמדו כל השנה כולה במס\"נ שלמעלה מטעם ודעת, מס\"נ מצד עצם הנשמה שלמעלה מהכחות הגלויים שבהם שייכת ההתחלקות דהודו וכוש – הגיעו בבחי' אחשורוש שאחרית וראשית שלו, בחי' שלמעלה מהשתלשלות, שאחרית וראשית בהשואה, ועי\"ז נעשה ביטול הגזירה.\n<b>יב</b>. וענין זה מתבטא גם בהעבודה דפורים – שהיא באופן ד\"לא ידע בין ארור המן לברוך מרדכי\"<sup data-n=\"190\">45</sup>:\n\"ארור המן\" – קאי על העבודה ד\"סור מרע\", ו\"ברוך מרדכי\" – קאי על העבודה ד\"עשה טוב\".\nוהנה, אף שהעבודה ד\"עשה טוב\" (\"ברוך מרדכי\") היא נעימה וחביבה יותר מאשר העבודה ד\"סור מרע\" (\"ארור המן\"), שהרי בעבודה ד\"סור מרע\" צריכים להתעסק עם הרע, וכל המתאבק עם מנוול מתנוול גם כן<sup data-n=\"191\">46</sup> – מ\"מ, נעשית העבודה ד\"סור מרע\" <i>באותה נעימות וחביבות</i> כמו העבודה ד\"עשה טוב\" (\"לא ידע בין ארור המן לברוך מרדכי\"), כיון שאינו מתחשב עם עצמו (ה\"געשמאַק\" שלו), אלא עומד בתנועה של מס\"נ לבעל הרצון, שהוא למעלה מהגדרים דהודו וכוש, ובמילא, עושה כל מה שדורש בעל הרצון באותה נעימות וחביבות.\n<b>יג</b>. וזהו גם מה שכ\"ק מו\"ח אדמו\"ר תבע מכל אחד מאתנו ב' קצוות:\nמחד גיסא – להיות מונחים ושקועים (\"ליגן\") בלימוד התורה, גליא דתורה ונסתר דתורה, תורת החסידות, רזין ורזין דרזין – שזהו עומק רום,\nובה בשעה – להשפיע על יהודי ולעוררו על שמירת שבת, טהרתהמשפחה באופן הכי פשוט, ולדבר עם ילד יהודי שאינו יודע מאומה אודות יהדות, לקרבו ליהדות.\nוע\"י ההתעסקות בב' הקצוות יחדיו, ממהרים וממשיכים ביאת משיח – ש\"הנה זה עומד אחר כתלנו\"<sup data-n=\"192\">47</sup> – החל מביאת משיח הפרטי<sup data-n=\"193\">48</sup>, אצל כאו\"א בעניניו הפרטיים, ובמילא גם ביאת משיח לכל ישראל, ולכל העולם כולו.\n***\n<b>יד</b>. משתדלים<sup data-n=\"194\">49</sup> לקיים ולחזק את המנהגים העתיקים.\n– אילו היו לנו כתפיים רחבות, עינים לראות ואזנים לשמוע, לב להבין ומוח להשכיל – לא היינו מוכרחים להשתמש דוקא בדרך הסלולה, אלא היינו יכולים לילך גם בדרך חדשה ולהגיע אל המטרה, לעלות בית א-ל. אבל כיון שחסרים הענינים הנ\"ל, מוכרחים אנו לילך בדרכים שסללו לנו. ואז הולכים על אחריותם ועל כתפיהם של אלה שהראו וסללו את הדרכים. ולכן משתדלים לייסד מחדש את ההנהגות, אפילו אם (מצד כמה טעמים) נפסקו לזמן מה.\nכ\"ק אדמו\"ר (מהורש\"ב) הי' נוהג לאסוף מעות (או מורה שיתנדבו) – בעת התוועדות – שלש פעמים בשנה: שמחת תורה, י\"ט כסלו ופורים. בשמחת תורה הי' אוסף עבור \"תומכי תמימים\", בפורים – עבור הענינים שלו (מוסדות, תמיכה לאנשים פרטיים וכיוצא בזה), ובי\"ט כסלו – עבור שני הענינים<sup data-n=\"195\">50</sup>.\nכיון שכל הענינים האמורים קיימים גם עתה, וההצטרכות היא גדולה יותר – ישתתף כל אחד עתה בענין זה.\nועי\"ז, נוסף על מעלת הצדקה בכלל, שמביאה הצלחה בגשמיות, כמארז\"ל<sup data-n=\"196\">51</sup> \"עשר בשביל שתתעשר\", וכן ברוחניות, כפי שכותב רבינו הזקן בתורה אור<sup data-n=\"197\">52</sup> שע\"י מצות הצדקה נעשים מוחו ולבו זכים אלף פעמים ככה, ומובן מהגהת הצמח-צדק<sup data-n=\"198\">53</sup> שהלשון \"אלף פעמים\" אינו עלדרך רגילות וגוזמא, אלא אלף פעמים <i>ממש</i> – הרי לבד זאת, כאשר נותנים עבור הענינים שכ\"ק אדמו\"ר נ\"ע הי' אוסף עבורם, ובאותו זמן שהי' אוסף, שאז הוא עת רצון וסגולה לכך – ה\"ז מביא תוספת ברכה והצלחה, ויכולים לבוא אל כ\"ק אדמו\"ר נ\"ע, ולדרוש, ש\"ימשיך\" את כל ההבטחות בפועל.\nוענין זה שייך גם לאחרי ימי הפורים:\nובהקדמה – שבכללות החדשים יש חילוק בין חציו הראשון של החודש לחציו השני<sup data-n=\"199\">54</sup>, אבל בנוגע לעניני פורים הרי נאמר<sup data-n=\"200\">55</sup> \"והחדש אשר נהפך להם מיגון לשמחה ומאבל ליום טוב גו'\", היינו, שהענין ד\"ונהפוך הוא גו'\"<sup data-n=\"201\">56</sup>, עם כל עניני הפורים, ישנם בכל חודש אדר<sup data-n=\"202\">57</sup>.\nולכן, כל הנמצאים כאן, יכתבו לקרוביהם, ידידיהם ומכיריהם, שבמשך חודש זה יכולים להשתתף בכך, וכל מה שיתנו במשך חודש זה – ה\"ז יוכלל בהקופה דפורים.\nכל המשתתפים, הן על אתר והן אלה שישתתפו אח\"כ, יכולים לרשום על פתקא שמם<sup data-n=\"203\">58</sup> ושם אמם<sup data-n=\"204\">59</sup> והסכום שמנדבים, ויקראו זאת על ציון הקדוש של כ\"ק מו\"ח אדמו\"ר, וזה יעורר וימשיך תוספות ברכה והצלחה לכל אחד ואחת בכל המצטרך להם ולבני ביתם בגשמיות וברוחניות.\n***\n<b>טו.</b> דובר לעיל (ס\"ו ואילך) בענין \"תוקפו של אחשורוש\", ש\"אחרית וראשית שלו\", בעבודת האדם – שהעבודה צריכה להיות בכל התוקף בב' הקוין ד\"אחרית\" ו\"ראשית\" בשוה,\nולדוגמא – שהעבודה צריכה להיות הן בהקו ד\"סור מרע\" והן בהקו ד\"עשה טוב\", מבלי לעשות חשבונות איזו עבודה נעימה יותר,\nוכמו כן צריכה להיות העבודה הן בנוגע לעצמו והן בנוגע להזולת, מבלי לעשות חשבונות שיש לו עדיין ריבוי (\"פּלענטי\") עבודה עם עצמו,ובפרט בידעו מעשיו דיבוריו ומחשבותיו במשך כל היום וכל הלילה כו', וא\"כ, איך יכול להיות \"משפיע\" על הזולת, ובלשון חז\"ל<sup data-n=\"205\">60</sup>: \"סמוך לפלטירי' שלך לא הורשת\" – אלא כמ\"ש כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"206\">61</sup> שאין אתנו יודע עד מה בסוד הבירורים, ובמילא, אין לערוך חשבונות, אלא כל דבר המזדמן ליד, צריכים לחטוף ולעשותו תיכף ומיד<sup data-n=\"207\">62</sup>.\nוכאשר ההנהגה היא באופן של \"תקפו של אחשורוש\" – אזי נעשה ביטול הגזירה, ואדרבה, \"ונהפוך הוא\"&lt;56&gt;, שאומות העולם עצמם אומרים \"כתבו על היהודים כטוב בעיניכם\"<sup data-n=\"208\">63</sup>.\n<b>טז</b>. ויש להוסיף ולבאר גם המשך דברי הגמרא&lt;20&gt; בנוגע ל\"תוקפו של מרדכי\" – שענין זה קשור במיוחד עם ביטול הגזירה, עי\"ז ש\"נפל פחד מרדכי עליהם\"<sup data-n=\"209\">64</sup>:\nובהקדם דברי הגמרא<sup data-n=\"210\">65</sup> \"אמאי קרי לי' <i>יהודי</i> (אף ש\"מבנימין קאתי\", \"איש ימיני\"<sup data-n=\"211\">66</sup>), על שום שכפר בעבודה זרה, שכל הכופר בע\"ז נקרא יהודי\". ומזה מובן שביטול הגזירה נעשה ע\"י הכפירה בע\"ז.\n<b>יז</b>. ביאור הדברים:\nע\"ז ושיתוף – בפשטות – היינו שחושבים שיש עוד מציאות שיש לה איזה יכולת עצמית כו', והכפירה בע\"ז היינו שמאמינים ויודעים שהקב\"ה הוא השליט והבעה\"ב היחידי בכל העולם כולו.\nאמנם, תורת החסידות גילתה וביארה את האמונה וההשגה בהענין ד\"אין עוד\"<sup data-n=\"212\">67</sup>, \"אפילו בחללו של עולם\"<sup data-n=\"213\">68</sup> – שלא זו בלבד שאין שום דבר שיש לו יכולת עצמית, אלא עוד זאת, ש\"אין עוד\", שאין שום מציאות כלל – אפילו לא מציאות של דבר טפל (\"עוד שהוא לשון טפל\"<sup data-n=\"214\">69</sup>) – מלבדו ית',\nוההסברה בזה – כמ\"ש&lt;39&gt; \"מבלעדי אין אלקים\": \"אלקים\" בגימטריא הטבע<sup data-n=\"215\">70</sup>, ו\"מבלעדי אין אלקים\" היינו שגם מציאות הטבע– כללות הסדר דפנים ימין שמאל ואחור<sup data-n=\"216\">71</sup> – היא אלקות<sup data-n=\"217\">72</sup>, אלא שיש אלקות כפי שהוא בגילוי, ויש אלקות כפי שבא בהעלם והסתר דלבושי הטבע, ועד שיש העלם והסתר שהוא \"נגד ה' ממש לומר אני ואפסי עוד\"<sup data-n=\"218\">73</sup>; אבל האמת היא שגם העלם והסתר זה אינו אלא בשביל מילוי שליחותו של הקב\"ה, שהרי \"לית אתר (מקום וזמן או ענין) פנוי מיני'\"<sup data-n=\"219\">74</sup>.\nואמונה זו – דורשת תורת החסידות שתהי' (לא בדרך מקיף, אלא) בפנימיות, היינו, שתאיר ותחדור בכל כחות נפשו – שענין זה יכול להיות רק ע\"י הבנה והשגה, ולכן מבארת תורת החסידות כמה ביאורים והסברים בזה, ומביאה גם הסברים מספרי חקירה, וכמו הענין ש\"כל הנמצאים\" \"לא נמצאו אלא מאמתת המצאו\"<sup data-n=\"220\">75</sup> – שעי\"ז תבוא האמונה בפנימיות.\nוכאשר חסרה הידיעה ד\"אין עוד אפילו בחללו של עולם\", היינו, שחושב שיש עוד איזה מציאות ח\"ו מלבד אלקות – הנה אע\"פ שיודע שהקב\"ה הוא בעה\"ב על מציאות זו, מ\"מ, הא גופא שחושב שיש איזה מציאות והקב\"ה צריך לנהוג בעלות על מציאות זו – הרי זה בדקות דדקות ענין של ע\"ז<sup data-n=\"221\">76</sup>.\n<b>יח</b>. וכתוצאה מידיעה והשגה הנ\"ל באחדותו ית' – שצריכה להביא תועלת בעבודה כמו כל ידיעה והשגה – נעשית העבודה באופן ד\"תוקפו של אחשורוש\", שמתעסקים בכל עניני העבודה, ובכל דבר המזדמן ליד, ללא חשבונות איזו עבודה היא קלה ונעימה יותר, וכיו\"ב.\nובפרטיות יותר:\nהסיבה לכך שיש מקום לחלק בין העבודה ד\"סור מרע\" לעבודה ד\"עשה טוב\" – שההתעסקות בעניני טוב וקדושה היא נעימה וחביבה יותר מאשר ההתעסקות עם מציאות של רע ומנגד, כי (א) ההתעסקות עם מנגד צריכה להיות באופן של מלחמה, שזוהי עבודה קשה ביותר, (ב) גם כאשר מצליחים לנצח את המנגד, הרי זה באופן ד\"המתאבק עם מנוול מתנוול גם כן\" (כנ\"ל סי\"ב) – היא מפני שמתייחסים למציאות הרע כמציאות של <i>מנגד</i>;אבל כאשר ישנה הכפירה בע\"ז כדבעי, היינו, שיודעים שאין שום מציאות זולתו ית' – אזי יודעים שאין שום דבר הסותר ומנגד לאלקות, שהרי אין עצם מסתיר על עצם<sup data-n=\"222\">77</sup>, ואין זה אלא שרצה הקב\"ה שיהי' ענין של עבודה ויגיעה (ולא באופן של מתנה, שזהו \"נהמא דכיסופא\"<sup data-n=\"223\">78</sup>), ולכן נראה להגוף ונה\"ב שישנו העלם והסתר, אבל לאמיתתו של דבר אין שום דבר הסותר ומנגד לאלקות,\nוכיון שכן, הרי אין הבדל בין העבודה ד\"סור מרע\" לעבודה ד\"עשה טוב\", בין \"ארור המן\" ל\"ברוך מרדכי\" – שהרי לאמיתתו של דבר גם \"המן\" אינו מנגד, ואמיתית ענינו אינו אלא כדי שיתהפך לקדושה.\nובמילא, גם העבודה ד\"סור מרע\" \"ארור המן\" היא בנקל, ומתוך שמחה – כיון שיודעים שכל מציאות ההעלם אינו אלא <i>שנראה כן</i> כדי לעורר את ענין עבודה, וכאשר עומדים בתוקף ולא מתפעלים מה\"העלם\", אזי רואים גם בעיני בשר שההעלם אינו מציאות כלל, ומתהפך לקדושה.\nוכמו כן מובן גם בנוגע לההתעסקות בכל דבר הבא ליד – שמצד הידיעה ש\"אין עוד אפילו בחללו של עולם\", מונח אצלו בפשיטות גמורה שכל דבר הוא בהשגחה פרטית, וכיון שעתה נזדמנה לו עבודה זו, הרי בודאי שייכת היא לתפקידו ושליחותו שבשביל זה ירדה נשמתו למטה.\n<b>יט</b>. ועפ\"ז מובנת גם השייכות של הכפירה בע\"ז (\"יהודי, על שום שכפר בע\"ז\") ותוקפו של אחשורוש לענין נס פורים:\nכיון שע\"י הכפירה בע\"ז, ש\"אין עוד\", עד שאפילו דבר הנראה ל\"מנגד\" אינו מציאות מלבד אלקות, נעשית העבודה בכל הענינים בהשואה, \"לא ידע בין ארור המן לברוך מרדכי\" (כנ\"ל) – הרי זה נמשך ונתגלה גם <i>בגשמיות</i>, ובמילא מתבטלת הגזירה, ואדרבה, \"ונהפוך הוא\", כתוצאה מהענין ד\"ונהפוך הוא\" ברוחניות.\nומזה מובן גם בעבודתו הפרטית של כאו\"א מישראל, שכאשר יודע שכל הענינים הם אלקות, ולאמיתו של דבר אין רע – הרי זה נמשך גם בגשמיות, שרואה בעיני בשר שלא זו בלבד ש\"כל דעביד רחמנא לטב עביד\"<sup data-n=\"224\">79</sup>, היינו, שהכוונה בזה היא \"לטב\", אלא יתירה מזה, ש\"גם זולטובה\"<sup data-n=\"225\">80</sup>, שדבר זה גופא הוא לטובה<sup data-n=\"226\">81</sup>, בטוב הנראה והנגלה לו ולבני ביתו, בכל המצטרך לו ולהם.\n***\n<b>כ</b>. איתא בגמרא<sup data-n=\"227\">82</sup> \"נשים חייבות במקרא מגילה שאף הן היו באותו הנס\" – \"שאף על הנשים גזר המן כו'\", ו\"עיקר הנס הי' כו' ע\"י אסתר\"<sup data-n=\"228\">83</sup>.\nוכן מצינו בחנוכה<sup data-n=\"229\">84</sup>: \"נשים חייבות בנר חנוכה שאף הן היו באותו הנס\" – \"שגזרו יונים על כל בתולות הנשואות להבעל לטפסר תחלה (וכמ\"ש הרמב\"ם<sup data-n=\"230\">85</sup> ש\"פשטו ידם כו' בבנותיהם\"), ועל ידי אשה נעשה הנס\" (\"על ידי יהודית\"<sup data-n=\"228\">83</sup> – שכרתה את ראשו של שר צבא יון<sup data-n=\"231\">86</sup>).\nוכן בפסח<sup data-n=\"232\">87</sup>: \"נשים חייבות בד' כוסות הללו שאף הן היו באותו הנס\" – \"כדאמרינן<sup data-n=\"233\">88</sup> בשכר נשים צדקניות שבאותו הדור נגאלו\".\nכלומר: אע\"פ שבמצוות עשה שהזמן גרמא נשים פטורות<sup data-n=\"234\">89</sup>, מ\"מ, בפורים וכן בחנוכה ופסח חייבות גם הנשים, בגלל שייכותן להנס.\nוענין זה מודגש ביותר בפורים – שהרי לא זו בלבד שהנס הי' ע\"י מרדכי ואסתר בשוה, אלא עוד זאת, שעיקר הנס הי' ע\"י אסתר,\n[כמובן גם מזה שהנס דפורים אירע רק לאחר שלא הי' שום מוצא בדרך הטבע, כיון שנתבטלה גם התקווה שאפשר לסמוך על אסתר, (\"אחות יש לנו בבית המלך\"<sup data-n=\"235\">90</sup>), וכפי שאמר לה מרדכי \"רוח והצלה יעמוד ליהודים ממקום אחר\"<sup data-n=\"236\">91</sup>],\nועד שהמגילה נקראת על שמה דוקא – מגילת <i>אסתר</i>, וכדאיתא בגמרא&lt;35&gt; \"שלחה להם <i>אסתר</i> (דוקא) לחכמים כתבוני לדורות . . מצאו לו מקרא כתוב בתורה, כתוב זאת זכרון בספר&lt;34&gt; . . בספר, מה שכתוב במגילה\" (שלא מצינו זה בחנוכה, אף שגם שם נעשה הנס ע\"י אשה, וכן בפסח, שאף שבזכות נשים צדקניות נגאלו אבותינו ממצרים, מ\"מ, נקראת יצי\"מ על שם משה רבינו, \"גואל ראשון\" ש\"הוא גואל אחרון\"<sup data-n=\"237\">92</sup>).<b>כא</b>. וביאור א' הטעמים בהשייכות דנס פורים לנשים דוקא:\nאיתא במדרש<sup data-n=\"238\">93</sup> שביטול גזירת המן הי' עי\"ז שמרדכי קיבץ כ\"ב אלף תינוקות של בית רבן ולמד עמהם תורה. כלומר: עם היות מרדכי מגדולי ומנהיגי ישראל – למד <i>בעצמו</i> (לא ע\"י אחרים) עם תינוקות של בית רבן, ועי\"ז ביטל גזירת המן.\nובנוגע לחינוך ילדי ישראל – לא זו בלבד שחלקן של הנשים אינו פחות מחלקם של האנשים, אלא אדרבה, עיקר פעולת החינוך נעשית על ידי הנשים<sup data-n=\"239\">94</sup>, שכל אחת מהן עקרת הבית, עיקר ויסוד הבית יהודי, ועל ידה נעשה עיקר החינוך של תשב\"ר, שהם היסוד והקיום של עם ישראל.\n<b>כב</b>. והביאור בזה בפנימיות הענינים:\nמהחילוקים שבין פורים לחנוכה – שבחנוכה היתה הגזירה על הרוחניות דבנ\"י, ובפורים היתה הגזירה על הגשמיות דבני ישראל, על הגוף<sup data-n=\"240\">95</sup>.\nוהנה, בנוגע להגוף – כותב הרמב\"ם<sup data-n=\"241\">96</sup> \"היות הגוף בריא ושלם מדרכי (עבודת) ה' הוא\".\nוכמו כן ידוע הפתגם שאמר כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע לבנו כ\"ק מו\"ח אדמו\"ר<sup data-n=\"242\">97</sup>: ראה כמה יקר הוא זה – בהראותו על היד – שבשבילו שפכו (צוליב אים האָט מען אויסגעגאָסן) ריבוי תומ\"צ!\nוהענין בזה – כמבואר בדרושי חסידות<sup data-n=\"243\">98</sup>, ובפרט בד\"ה יביאו לבוש מלכות<sup data-n=\"244\">99</sup>, גודל מעלת הגשמיות, כולל גם הגוף הגשמי, ועד שבו דוקא ישנו כח העצמות<sup data-n=\"245\">100</sup> יותר מאשר בעולם האצילות.\nוענין זה מצינו גם במעלת תינוקות של בית רבן, כמארז\"ל<sup data-n=\"246\">101</sup> \"אין מבטלין תשב\"ר אפילו לבנין ביהמ\"ק\":על ביהמ\"ק נאמר<sup data-n=\"247\">102</sup> \"ועשו לי מקדש ושכנתי בתוכם\", בתוך כאו\"א מישראל<sup data-n=\"248\">103</sup>, ועל ידם – בכל העולם.\nואעפ\"כ, מעלת תשב\"ר גדולה יותר – כי, ענינו של ביהמ\"ק הוא השראת השכינה <i>ב</i>ישראל, היינו, שלאחרי שישנה מציאותם של בנ\"י, אזי משרה הקב\"ה שכינתו עליהם, ואילו מעלת תשב\"ר היא שעל ידם נעשה <i>עצם הקיום דבנ\"י</i>, שקשור עם עצמותו ית' (וע\"ד פתגם הנ\"ל אודות מעלת הגוף, שבשבילו ניתן ענין הרוחניות וריבוי תומ\"צ).\nולכן, כאשר היתה הגזירה על הגוף, היינו, על עצם מציאותם של בנ\"י – הי' גם ביטול הגזירה ע\"י תשב\"ר דוקא, הקשורים עם עצם הקיום דבנ\"י.\nוזהו שהאחריות דחינוך תשב\"ר מוטלת במיוחד על הנשים – כי, אשה ענינה ספירת המלכות, ועז\"נ \"אשת חיל עטרת בעלה\"<sup data-n=\"249\">104</sup>, שזהו מצד גודל מעלתה של ספירת המלכות שמושרשת בעצמות<sup data-n=\"250\">105</sup>, וגם הענין דתשב\"ר, עצם הקיום דבנ\"י, מעלת הגוף – נוגע וקשור עם העצמות.\nוזהו גם שביטול הגזירה בפורים הי' ע\"י אשה דוקא, ולכן שלחה אסתר לחכמים כתבוני לדורות, והמגילה נקראת על שמה, כנ\"ל.\n<b>כג</b>. וההוראה מזה בנוגע לימינו אלה:\nנזכר לעיל (ס\"ג) פתגם כ\"ק מו\"ח אדמו\"ר שגם עתה ישנה מחשבת המן, שזהו ענינו של עמלק שישנו בכל דור ודור, גם בדרא דמשיחא.\nוהעצה לזה – עי\"ז שנשי ישראל מחנכות את ילדיהם על טהרת הקודש, ללא פשרות, וללא חשבונות של תכלית בעוה\"ז הגשמי – שבשביל זה צריכים ללמדם שפת המדינה (אנגלית), ולהבטיח שיסיימו \"קאַלעדזש\" (אוניברסיטה), ולכל הפחות \"היי-סקול\" (בית ספר תיכון); עליהן לדעת שכל מה שקשור לתכלית הגשמית – יספק ויכלכל הקב\"ה, ואילו הן צריכות לספק ולכלכל את התכלית הרוחנית של הילדים.\nוכפי שהי' בימי הפורים – שבזמן גזירת המן לא למדו עם ילדי ישראל שפת מדי ופרס, לא לימדום כיצד להנצל מן הגזירה, ואפילו לא לימדום את חומרת המצב שבו נמצאים, אלא כך אמר להם מרדכי: ילדיישראל הנכם, וצריכים אתם ללמוד תורה! ולמד עמהם \"הלכות קמיצה\"<sup data-n=\"251\">106</sup> – לא רק ענינים הנוגעים למעשה בפועל, כמו הלכות תפילין וכיו\"ב, אלא גם הלכות קמיצה שבאותה שעה לא היו שייכים למעשה, כי אם מצד עצם הענין דהלכות <i>התורה</i> (כמבואר בתניא<sup data-n=\"252\">107</sup>); אלא מאי, מה תהי' התכלית שלכם, כיצד תוכלו לצאת לעולם? על זה – אמר להם מרדכי – אל תדאגו, <i>הקב\"ה</i> ידאג לכך, ואילו <i>אתם</i> צריכים לידע דבר אחד: הנכם ילדי ישראל, וצריכים אתם ללמוד תורתו של הקב\"ה. וכאמור, ע\"י הנהגה זו בטלה הגזירה.\nוכמו כן בימינו אלה, ובפרט בארצות-הברית, צריכות נשי ישראל לידע שאין לחשוב אודות תכלית גשמית עבור ילדיהן, כיצד יצליח הילד לצאת לעולם בהיותו \"בטלן\" שאינו יודע מאומה מעניני העולם, והרי זו בושה כלפי העולם וכו' – אין זו הדאגה שלהן, הן צריכות לדאוג לכך שהילדים ילכו בדרך התורה והמצוה, ועי\"ז תומשך הצלחה וישועה להילדים, לכל הבית, ולכל בתי בנ\"י<sup data-n=\"253\">108</sup>.\n***\n<b>כד</b>. (לאחר שניגנו ורקדו משך זמן, אמר כ\"ק אדמו\"ר שליט\"א:) בפורים צריך להיות ענין של נגינה וריקודים, ונוסף לזה, ישנו גם החיוב \"לבסומי בפוריא\" (להשתכר ביין)<sup data-n=\"254\">109</sup>. ומובן, שע\"י הניגונים והריקודים לא יוצאים י\"ח \"לבסומי בפוריא\"...\n– הן אמת ש\"כל העוסק במצוה פטור מן המצוה\"<sup data-n=\"255\">110</sup>, לפי שבכל מצוה כלולות גם כל שאר המצוות, ונמצא, שבשעה שעוסק במצוה עוסק הוא גם בהמצוה שפטור ממנה<sup data-n=\"256\">111</sup>, אבל אעפ\"כ, אין זה אלא מעין ודוגמא בלבד, ואינו דומה לקיום מצוה זו עצמה ממש. ולכן מצינו בזהר<sup data-n=\"257\">112</sup> שהינוקא הרגיש שלא קראו ק\"ש, אף שהיו פטורים מק\"ש מפני שעסקו במצוה<sup data-n=\"256\">111</sup>.\nובהחיוב ד\"לבסומי בפוריא\" גופא – ישנם כאלה שמקיימים חיוב זה ע\"י השינה<sup data-n=\"258\">113</sup>: שותים קצת יין, ואז נרדמים וישנים שינה עריבה יותר, ואומרים: \"שישו בני מעי\"<sup data-n=\"259\">114</sup>, שקיימו המצוה \"לבסומי בפוריא\" בתכלית ההידור, שהרי היו ישנים ביום זה כמה שעות יותר מרגילותם!...אבל אצל חסידים – הסדר הוא שאומרים \"לחיים\" כדי להרדים את הגוף ונה\"ב, ולעורר ולגלות את הנפש האלקית, להיות במעמד ומצב ד\"לא ידע בין ארור המן לברוך מרדכי\".\n(וסיים כ\"ק אדמו\"ר שליט\"א:) \"זאָגט לחיים\"! – אין זה מילתא דבדיחותא (\"ס'איז ניט קיין דזשאָק\"...), שהרי זה דין בשלחן ערוך<sup data-n=\"260\">115</sup>.\n***\n<b>כה</b>. איתא בגמרא&lt;82&gt; \"חייב אדם לקרות את המגילה בלילה ולשנותה ביום, שנאמר<sup data-n=\"261\">116</sup> למען יזמרך כבוד (ביום) ולא ידום (בלילה) ה' אלקי לעולם אודך\" (וקריאת המגילה שבח הוא שמפרסמין את הנס והכל מקלסין להקב\"ה).\nוכתבו הראשונים<sup data-n=\"262\">117</sup> שעיקר מצות קריאת המגילה הוא ביום, כיון שבמגילה נזכרו רק ימים (\"והימים האלה נזכרים ונעשים\"&lt;9&gt;). וביארו האחרונים<sup data-n=\"263\">118</sup> שהתוקף של קריאת המגילה כ\"דברי קבלה\" הוא רק ביום, וקריאת הלילה אינה אלא מצוה מדרבנן.\nולכן מצינו לכמה דעות<sup data-n=\"264\">119</sup> שבקריאת המגילה ביום – ספיקא לחומרא, כמו בדאורייתא, שזהו מצד התוקף של \"דברי קבלה\" – שהוא כמו דאורייתא – שיש לקריאת המגילה ביום (משא\"כ בקריאת המגילה בלילה, ספיקא לקולא).\n<b>כו</b>. וביאור הענין בעבודת האדם:\nמהחילוקים שבין יום ולילה – שעבודת ביהמ\"ק היתה ביום דוקא (עד שקיעת החמה), משא\"כ בלילה, שאז היו נועלין שערי העזרה<sup data-n=\"265\">120</sup>. וכן הוא גם למעלה – שהרי \"מלכותא דארעא כעין מלכותא דרקיעא\"<sup data-n=\"266\">121</sup> – שעבודת הנשמות היא ביום, משא\"כ בלילה, שאז הוא זמן שינה (גם למעלה), ותרעין דגן עדן אסתימו, ורק בפלגות ליליא תרעין דג\"ע פתיחין, וקוב\"ה אתא לאשתעשא עם צדיקייא בג\"ע<sup data-n=\"267\">122</sup>.\nוהענין בזה – שביום ישנו אור השמש, שמורה על האור והגילויד\"שמש הוי'\"<sup data-n=\"268\">123</sup> (וכמארז\"ל<sup data-n=\"269\">124</sup> \"שמשון על שמו של הקב\"ה נקרא שנאמר<sup data-n=\"270\">125</sup> כי שמש ומגן ה' אלקים\"), ואז תרעין דג\"ע פתיחין, וכן שערי ביהמ\"ק, משא\"כ בלילה, זמן החושך, העלם והסתר.\nאמנם, כדי שלא תהי' יניקה ושליטה לצד השמאל – שלזה צריכים לחשוש בלילה עוד יותר מאשר ביום – תיקנו חכמים תפלת ערבית בלילה (כנגד אברים ופדרים כו')<sup data-n=\"271\">126</sup>, ועוד זאת, ש\"האידנא קבעוה חובה\"<sup data-n=\"272\">127</sup>, שכן, מצד גודל החושך וההוספה בענינים דלעו\"ז, צריכה להיות הוספה גם בקדושה.\nוזהו שמצינו שאע\"פ שבגמרא<sup data-n=\"273\">128</sup> יש פלוגתא אם \"לא איברי ליליא אלא לשינתא\" או \"לא איברי ליליא אלא לגירסא\", מ\"מ, כבר נהגו ישראל שגם בלילה לומדים תורה, ובפרט פנימיות התורה<sup data-n=\"274\">129</sup>, כדי להאיר את חושך הלילה.\nובנוגע ללימוד התורה בלילה גופא, מצינו<sup data-n=\"275\">130</sup> שהבעש\"ט אמר שחציו השני של הלילה מתוקן כבר, והוא בא לתקן את חציו הראשון של הלילה – דכיון שענינו של הבעש\"ט הי' להאיר את החושך כפול ומכופל שלפני ביאת המשיח, לכן הי' עיקר לימודו בלילה בחציו הראשון של הלילה, כאשר תרעין דג\"ע סתימין, ולא בחציו השני של הלילה, כאשר תרעין דג\"ע פתיחין.\n<b>כז</b>. והנה, כללות הענין דהארת החושך כפול ומכופל דזמן הגלות קשור עם \"דברי סופרים\" דוקא:\nדברי סופרים – הם החומרות והסייגים שהוסיפו חכמים כדי שלא יבואו לעבור ח\"ו על דברי תורה, שזהו\"ע \"עשו משמרת למשמרתי\"<sup data-n=\"276\">131</sup>.\nוענין זה מודגש בעיקר בזמן הגלות, שאז ניתוספו עיקר החומרות והסייגים<sup data-n=\"277\">132</sup> – כי, מצד התגברות החושך יש צורך בזהירות יתירה שלא תהי' שליטה להחושך כו', והעצה לזה היא הוספת חומרות וסייגים כו'.\nובעומק יותר – שיש מעלה יתירה ב\"דברי סופרים\", כמארז\"ל&lt;31&gt; חביבים דברי סופרים יותר מדברי תורה, כיון נמשכים ממקום נעלהיותר<sup data-n=\"278\">133</sup>, ולכן בכחם דוקא יכולים להתגבר על חושך הגלות, ועד להאיר את חושך הגלות.\nוזהו שתפלת ערבית בלילה – שענינה להאיר את החושך (כנ\"ל) – היא מדרבנן (דברי סופרים) דוקא. ועד\"ז בנוגע למנהג ישראל ללמוד התורה בלילה – שהלימוד הוא (לא בתורה שבכתב, אלא) בתורה שבעל-פה דוקא<sup data-n=\"279\">134</sup>, ובפרט בפנימיות התורה, כנ\"ל.\nוזהו גם הטעם שקריאת המגילה ביום היא מן התורה (\"דברי קבלה\"), ובלילה מדרבנן – כיון שהארת חושך הלילה (שזהו\"ע קריאת המגילה בלילה) הוא בכח דברי סופרים דוקא.\n<b>כח</b>. אמנם, עפ\"ז הי' צריך להיות עיקר קריאת המגילה <i>בלילה</i> דוקא – דכיון שקריאת המגילה בגלל הנס דפורים הוא ענין שניתוסף בזמן הגלות, נמצא, שכללות הענין דקריאת המגילה הוא כדי להאיר את החושך, ואם כן, צריך להיות עיקר ענינו בלילה דוקא, ועכ\"פ, קריאת המגילה בלילה היתה צריכה להיות חמורה יותר מקריאת המגילה ביום.\nויש להביא סמך לזה – ממ\"ש רבינו הזקן בסידור<sup data-n=\"280\">135</sup> ש\"אין מברכין שהחיינו אלא בלילה ולא ביום\".\nאמנם, ידוע מ\"ש הצמח צדק<sup data-n=\"281\">136</sup> ש\"הגם כי מי אני לעורר על דבריו הקדושים, מ\"מ תורה היא כו'\", ופסק שיש לברך שהחיינו גם ביום. ובא' הביכלאך של הכת\"י<sup data-n=\"282\">137</sup> איתא ש\"בפורים שנת הכת\"ר (תרכ\"ה) פה ליובאוויטש ציוה אדמו\"ר (הצ\"צ) לברך שהחיינו בבוקר קודם קריאת המגילה\".\nוכמו כן בנוגע לחומר הענין – הרי בלילה ספיקא לקולא, וביום ספיקא לחומרא, כנ\"ל.\n<b>כט</b>. ויש לבאר הענין שבלילה ספיקא לקולא וביום ספיקא לחומרא – בעבודת האדם:\nכאשר יהודי יודע שפלות מצבו שנמצא במעמד ומצב של <i>לילה </i>וחושך – הרי בודאי לא יסמוך על שיקול דעתו לפסוק לעצמו הלכות במקום של ספק, בידעו שפלות מצבו שהוא \"עני בדעת\",\n– וע\"ד מ\"ש אדמו\"ר האמצעי בדרך חיים<sup data-n=\"283\">138</sup> משל העני, שמיד כשנזכר על מעמדו ומצבו, אזי בכה יבכה במר נפשו כו', ומזה מובן גם בנוגע לעני בדעת (\"אין עני אלא בדעת\"<sup data-n=\"284\">139</sup>) –\nולכן, אצלו אין חשש שבגללו יהי' צורך להחמיר בענין של ספק. וזהו גם שספיקא <i>דרבנן</i> לקולא – כיון שכל הענינים שהם מדרבנן, חומרות וסייגים, נועדו מלכתחילה עבור אלה שנמצאים במעמד ומצב של <i>חושך</i>, שאצלם אין חשש שבגללו יהי' צורך להחמיר בענין של ספק.\nאבל מי שיש לו חולי של ישות והרגש עצמו, ונדמה לו שהוא במעמד ומצב של <i>יום</i> – עלול הוא לסמוך על שיקול דעתו ולהתיר ענין של ספק, מפני שיש לו ידיעה באותיות הקטנות (\"ער קען ליינען די שווארצע פּינטעלאַך\"), על כל קושיא יש לו תירוץ, ומחזיק את עצמו ל\"למדן\", רשכבה\"ג... ולכן צריכים להבהיר ולומר לו: \"אל<sup data-n=\"285\">140</sup> תאמין בעצמך\"! בכל מקום של ספק אל תסמוך על עצמך, אלא עליך להדר ולהחמיר בכל החומרות.\n[וע\"ד מ\"ש רבינו יונה<sup data-n=\"286\">141</sup> בביאור הטעם שקרבן אשם תלוי, שבא על הספק, צריך להיות יותר ביוקר מקרבן חטאת הבא על הודאי – כי על עבירה ודאית אדם מתחרט בכל לבו (שהרי יהודי אינו רוצה ואינו יכול להיות נפרד מאלקות<sup data-n=\"287\">142</sup>), אבל ספק עבירה, הוא מתברך בלבבו לומר שמא לא עשיתי עבירה, ואינו מתחרט עלי' חרטה גמורה, ומשום זה החמירו בו יותר].\nוזהו הטעם שקריאת המגילה היא גם ביום, ולא עוד אלא שקריאתה ביום חמורה יותר מקריאתה בלילה – כי, כאשר נדמה לו שהוא במעמד ומצב של יום, הרי החושך שבו (שמשים חושך לאור) גדול ביותר, ובמילא זקוק הוא עוד יותר לקריאת המגילה ולהחמיר בה יותר, כדי לגרש את החושך שבו.\n<b>ל</b>. ומזה יש לימוד מוסר השכל לכאו\"א בכל מעמד ומצב – בנוגע לגודל הזהירות שצריכה להיות תמיד:במעמד ומצב של לילה – צריכה בודאי להיות הזהירות ע\"י סייגים וחומרות,\nואם נדמה לו שהוא במעמד ומצב של יום – צריכה להיות זהירות גדולה יותר, כיון שענין הישות הו\"ע קליפת עמלק, שעז\"נ<sup data-n=\"288\">143</sup> \"ראשית גוים עמלק\", ראשית ומקור לכל המדות הרעות<sup data-n=\"289\">144</sup>.\nוזהו גם כללות הענין דפורים שקשור עם מחיית עמלק, כמ\"ש<sup data-n=\"290\">145</sup> \"תמחה – ועי\"ז \"מחה אמחה\"&lt;34&gt; (הקב\"ה) – את זכר עמלק\",\n– ולהעיר, ש\"תמחה\" \"מחה אמחה\" ר\"ת אמת<sup data-n=\"291\">146</sup>, היינו, שעי\"ז מגיעים לבחי' \"אני ראשון ואני אחרון ומבלעדי אין אלקים\"&lt;39&gt;, שזהו\"ע ד\"אמת\", \"אל\"ף רישי' דאלפא ביתא מ\"ם באמצעיתה תי\"ו בסופה, לומר אני ראשון וגו'\"<sup data-n=\"292\">147</sup> –\nובכח זה נעשה \"אחריתו (של עמלק) עדי אובד\"<sup data-n=\"288\">143</sup>, שלא נשאר ממנו שריד ופליט,\nואז נעשה \"השם שלם והכסא שלם\"<sup data-n=\"293\">148</sup>, שעי\"ז זוכים להגאולה האמיתית והשלימה במהרה בימינו ע\"י משיח צדקנו.\n[כ\"ק אדמו\"ר שליט\"א צוה לנגן \"אני מאמין\"].\n***\n<b>לא</b>. [כ\"ק אדמו\"ר שליט\"א דיבר עם א' מהמסובים ע\"ד לימוד דא\"ח, והלה טען שאין לו חוש בזה, ואינו יודע מה יועיל לו וכו', ואמר לו כ\"ק אדמו\"ר שליט\"א: משל למה הדבר דומה – לנסיעה ברכבת, שהאדם הנוסע ברכבת אינו יודע את כל הטכניקה הקשורה באופן פעולת הרכבת, ואעפ\"כ, כשרוצה להגיע למחוז חפצו, עולה על הרכבת, וכאשר נמצאים על הרכבת, הרי בין אם מבינים את הטכניקה ובין אם לאו, פועלת הרכבת את פעולתה להביאו למחוז חפצו, וענינו בהנמשל – שלימוד החסידות מביא את האדם מעומק תחת לעומק רום. ואח\"כ אמר:]\nישנם בעולם ד' סוגים: דומם, צומח, חי, מדבר. – דומם הוא הסוג הנמוך ביותר, ומדבר הוא הסוג המעולה ביותר.ד' סוגים אלה אינם באופן שאין להם שייכות זל\"ז, כי אם באופן שהסוג היותר נעלה כולל גם את הסוג שלמטה ממנו, אלא שהוא מעולה יותר ממנו. כלומר: סוג הצומח אינו צומח בלבד, ללא שייכות כלל לדומם, אלא יש בו גם ענין הדומם, ונוסף לזה יש בו גם מעלת הצומח. ועד\"ז סוג החי, שיש בו גם הענין דדומם וצומח, ונוסף לזה יש בו גם מעלת החי. ועד\"ז סוג המדבר, שיש בו גם הענין דדומם צומח חי, ונוסף לזה יש בו גם מעלת המדבר.\nומובן, שכל זמן שהצומח מנצל רק את הדומם שבו, ולא את מעלת הצומח – לא התחיל למלא את התפקיד שבשבילו נברא. ועד\"ז בנוגע למדבר, שכל זמן שמנצל רק את הדומם צומח חי שבו, ולא את ה\"מדבר\" שבו, אין זה נחשב שמנצל רק שלשה רבעים שבו וחסר לו רביע, אלא יתירה מזה – שלא התחיל כלל למלא את עיקר תפקידו שבשבילו נברא.\nויתירה מזה: נוסף לכך שחסר לו (לא רק רבע, אלא) עיקר ענינו (מדבר), ויש בידו רק הטפל שבו (דצ\"ח, שאינם בערך וכלא חשיבי לגבי המדבר שבו), אלא עוד זאת, שאין לו אפילו את הטפל – כי, גם דצ\"ח שב\"מדבר\" צריכים להיות מושפעים מה\"מדבר\" ולהיות בדרגא נעלית יותר מדצ\"ח סתם (היינו, שהדצ\"ח עצמם מתעלים לבחי' מדבר), וא\"כ, כל זמן שאינו מנצל את המדבר שבו, לא ניצל אפילו את הדצ\"ח שבו.\n<b>לב</b>. והנה, בסוג המדבר גופא הסוג המעולה יותר הם בני ישראל. ומזה מובן שכשם שבצומח יש דבר נוסף על דומם, בחי יש דבר נוסף על צומח, ובמדבר יש דבר נוסף על חי, שזוהי נפש השכלית – כך יש אצל בנ\"י דבר נוסף על הנפש השכלית (בחי' המדבר), שזוהי הנשמה, נפש האלקית, עלי' נאמר<sup data-n=\"294\">149</sup> \"ויפח באפיו נשמת חיים\", ו\"מאן דנפח מתוכי' נפח\"<sup data-n=\"295\">150</sup> (שענין זה קאי לא רק על אדה\"ר, אלא גם על כאו\"א מישראל).\nוע\"פ הנ\"ל, מובן, שכאשר איש ישראל אינו מנצל את ה\"ישראל\" (\"דעם איד\") שבו, כי אם את ה\"אדם\" (מדבר) שבו, שמתנהג רק כאדם טוב בעל מדות טובות כפי שמתחייב מצד שכל אנושי – הרי לא זו בלבד שחסר אצלו <i>פרט אחד</i> במילוי תפקידו, ולא זו בלבד שחסר מילוי <i>עיקר</i> תפקידו, אלא עוד זאת, <i>שלא התחיל כלל למלא את תפקידו</i>, כי:\nגם הענינים הקשורים עם הנהגה במדות טובות שמחוייבת ע\"פ שכל אנושי, הנה אצל איש ישראל צ\"ל קיומם מפני שכן הוא רצונו שלהקב\"ה, שלכן, גם דיני גניבה וגזילה וכיו\"ב הם תורה מן השמים, וכמבואר בחסידות<sup data-n=\"296\">151</sup> שגם קיום המצוות ד\"משפטים\" צריך להיות באופן של קבלת עול כמו \"חוקים\".\nולכן, כאשר הנהגתו של יהודי היא רק מצד שכל אנושי – הרי אינו מנצל את ענינו, ונמצא, שהכחות המיוחדים שהקב\"ה נתן לו, שאינו מנצלם, הם לבטלה.\n<b>לג</b>. והנה, בין בנ\"י גופא ישנם אלה שזכו להגילוי דפנימיות התורה:\nבדורות הראשונים לא נתגלתה פנימיות התורה אלא ליחידי סגולה בלבד, ואפילו בזמן התנאים והאמוראים מארי קבלה מועטים היו, עד שבא הבעש\"ט וגילה תורת החסידות לכל בנ\"י, ואדמו\"ר הזקן הוסיף וגילה זאת בשכל אנושי, וכדברי כ\"ק מו\"ח אדמו\"ר<sup data-n=\"297\">152</sup> שהבעש\"ט הראה שכל יהודי אפילו פשוט שבפשוטים צריך להיות עובד הוי', ואדמו\"ר הזקן הראה את הדרך איך שכל יהודי אפילו פשוט שבפשוטים יכול להיות עובד הוי' – עי\"ז שגילה תורת החסידות בשכל אנושי באופן המובן לכל.\nומדור לדור מגלים רבותינו נשיאינו את תורת החסידות בהרחבה ובהתפשטות יותר, עד שכ\"ק מו\"ח אדמו\"ר גילה יקר תפארת גדולתו וכתרו של מלך בהרחבה ביותר, ולא רק בלשון הקודש, אלא גם באידית, ואפילו בלשונות אומות העולם, אנגלית וצרפתית.\nובכן: יהודים אלה שזכו ויש להם שייכות להבנה והשגה בפנימיות התורה, צריכים לדעת שזכו בזכות גדולה ביותר, אשר, כמה וכמה גדולים לא זכו לכך, ואילו הם זכו להתקשר עם בחי' סתים דקוב\"ה ע\"י לימוד סתים דאורייתא באופן של הבנה והשגה, שעל ידה נעשה יחוד נפלא ועצום (כמבואר בתניא<sup data-n=\"298\">153</sup>).\nובנוגע לכל הטענות למיניהם, שעדיין לא ראויים ללימוד החסידות, וצריכים תחילה להיות שלם ב\"סור מרע\", או למלא כריסו בש\"ס ופוסקים, וכיו\"ב – צריכים לידע שטענות אלה הם טענות של היצה\"ר כפי שמתלבש באיצטלא של משי (\"ווי ער איז אָנגעטאָן אין אַ זיידענע זופּיצע\")<sup data-n=\"299\">154</sup>,וכפי שהי' נקרא בפי כ\"ק מו\"ח אדמו\"ר<sup data-n=\"300\">155</sup>: \"דער קלוגינקער\", כיון שבא בתחבולות שונות באופן המתאים לכל אחד לפי ענינו, אשר, העצה לזה היא – \"מבטשין לי'\"<sup data-n=\"301\">156</sup> (כמבואר בתניא<sup data-n=\"302\">157</sup>). ובמילא, אין להתחשב בכל התירוצים והאמתלאות, אלא ללמוד חסידות בפועל, \"טאַפּאָרו-דאַ-פּלאַחו\"<sup data-n=\"303\">158</sup> (הגרזן על העץ, מעשה בפועל), תוך ידיעה שדבר זה הוא על כתפיהם של רבותינו נשיאינו שגילו תורת החסידות וסללו לנו את הדרך העולה בית א-ל.\nאמנם, כאשר לא מנצלים את הזכות שניתנה בגילוי תורת החסידות, אם מצד עצלות או מצד שאר טענות ותירוצים – הרי אפילו לא התחילו למלא את התפקיד שבשבילו נבראו, וגורמים שהכחות של הקב\"ה שהושקעו לגלות את תורת החסידות ולקרב אותו לתורת החסידות, ילכו לבטלה ח\"ו.\nוע\"ד המבואר באגה\"ק<sup data-n=\"304\">159</sup> בהנוגע לענין התפלה, שכאשר \"עלה רצונו (של המלך, מלכו של עולם) להתגלות לכל והעביר קול בכל מלכותו להקהל ולעמוד לפניו להראותם כבוד מלכותו ויקר תפארת גדולתו, מי שעומד . . ומתעסק בצרכיו כמה גרוע . . וגם הוא מתחייב בנפשו למלך על הראות קלונו ובזיונו את המלך כו'\" – כן הוא גם בנוגע להתגלות תורת החסידות:\nכאשר בשנת תשי\"ג אומר הקב\"ה ליהודי – ע\"י פלוני בן פלוני – הנני מראה לך יקר תפארת גדולתי, ליתן לך רזין דרזין, כתרו של מלך, שזוהי תורת החסידות – אין לך מרידה גדולה מהעדר השימת-לב לקבל את הגילוי דתורת החסידות.\nוכאשר ישנה שימת-לב לקבל את הגילוי דתורת החסידות, ולא יוצאים י\"ח בהלימוד בלבד, אלא מיישמים את הדברים בעבודה בפועל, לברר את הגוף ונפש הבהמית וחלקו בעולם – אזי יקויים מ\"ש בזהר<sup data-n=\"305\">160</sup> \"בהאי חיבורא דילך . . יפקון בי' מן גלותא (ומוסיף) ברחמים\", בחסד וברחמים<sup data-n=\"306\">161</sup>, ותבוא הגאולה השלימה למטה מעשרה טפחים, במהרה בימינו.\n***<b>לד</b>. איתא בגמרא<sup data-n=\"307\">162</sup> \"בואו ונחזיק טובה לאבותינו שאלמלא כו' אנו כמי שלא באנו לעולם\", \"לפי שהן חיים לעולם, וכל זמן שהן קיימין אין אנו חשובים כלום\".\nובנוגע לעניננו:\nכאשר יבוא משיח ותהי' תחיית המתים, שיעמדו האבות, תנאים ואמוראים, ומה שנוגע אלינו בפרט: אבותינו רבותינו הק' – הרי מבין כל אחד (אפילו שוטה שבשוטים הכי גדול) שלא תהי' לנו שום תפיסת מקום.\nוכיון שכן, צריכים לחטוף ולנצל את הזמן המועט שנשאר, כדי למלא את העבודה והשליחות שמצד כמה סיבות הוטלה על אחריותנו – להפיץ את תורת החסידות בזמן החושך כפול ומכופל, וכאמור לעיל (ס\"ח) שכאשר מתעסקים ומתמסרים למילוי השליחות, עד שענין זה נעשה כל מציאותו, אזי מתעלים למעמד ומצב אחר לגמרי.\nוכאשר פלוני בן פלוני ממלא ומשלים בפועל את העבודה שהתחיל לפעול משה רבינו, הבעש\"ט, הרב המגיד, אדמו\"ר הזקן, והנשיאים שלאחריו – להאיר לא רק את הגליא שבנפש ע\"י גליא שבתורה, אלא גם את הסתים שבנפש ע\"י סתים דאורייתא – הנה אע\"פ שזהו דור יתום, שמצד עצמו אינו שייך לעבודה נעלית זו, אלא שמצד חסד חנם זיכו אותנו להשלים את העבודה, הרי זה באופן שאין המצוה נקראת אלא על שם הגומרה<sup data-n=\"308\">163</sup>, וע\"י עבודה קטנה של גמר המלאכה נוטל הוא שכר כנגד כולם.\nוכפי שמצינו במלאכות שבת שאחת המלאכות היא \"המכה בפטיש\"<sup data-n=\"309\">164</sup>, דאף שלכאורה אינו עושה מאומה, שהרי המלאכה כבר נעשתה, והוא רק מכה בפטיש, מ\"מ, הרי זו מלאכה חשובה כמו כל המלאכות.\nועד\"ז בנדו\"ד: כאשר משלימים בפועל את המלאכה שהתחיל משה רבינו ולא גמרה, הבעש\"ט והרב המגיד לא גמרוה, ואדמו\"ר הזקן ורבותינו נשיאינו הבאים אחריו לא גמרוה, ואילו הוא, ע\"י הפצת תורת החסידות, יגמור את העבודה להמשיך עיקר שכינה בתחתונים, שזוהי כוונת כל ההשתלשלות – הרי אע\"פ שאינו אלא \"מכה בפטיש\", נחשב הדבר למלאכה, ולא עוד אלא שאין המצוה נקראת אלא על שם הגומרה.\nובמילא צריכים אנו לידע גודל הזכות שניתנה לנו – שע\"י תנועה קלה יכולים אנו להשלים בפועל את כל העבודה שנעשתה במשך כלהדורות שלפנינו, שהרי כל הענינים העיקריים שהיו צריכים להתייגע עליהם נעשו כבר, ועכשיו יכולים אנו ע\"י תנועה קלה, ללא יגיעה גדולה, להרויח גם את כל מה שנעשה בדורות שלפנינו ע\"י ריבוי יגיעה, כיון שאין המצוה נקראת אלא על שם הגומרה.\n[כ\"ק אדמו\"ר שליט\"א צוה לנגן הניגון \"קול ביער\"<sup data-n=\"310\">165</sup>].\n***\n<b>לה</b>. כ\"ק אדמו\"ר שליט\"א אמר מאמר שני – ד\"ה על כן קראו לימים האלה פורים<sup data-n=\"311\">166</sup>.\n[כהקדמה ובסמיכות לאמירת המאמר, כאשר רצינות ודביקות מיוחדת נראתה על פני קדשו – פתח כ\"ק אדמו\"ר שליט\"א וסיפר:\nבתקופת המהפיכה ברוסיא לאחרי מפלתו של הקיסר, הורה כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע להחסידים להשתתף בבחירות שנערכו במדינה. ובהתאם לכך הגיע למקום שבו התקיימו הבחירות גם אחד החסידים שהי' מופשט לגמרי מהוויות העולם, ולא ידע כלל מה מתרחש במדינה – שהרי צריך הוא לקיים את ההוראה של הרבי, וכמובן, לאחרי הקדמת טבילה במקוה וחגירת אבנט, כראוי לקיום הוראה של הרבי. לאחר שעשה מה שצריך לעשות בשביל הבחירות, כפי שהורו לו חבריו –ראה אנשים עומדים ומכריזים \"הוּ-רַה\", ועמד גם הוא והכריז: \"הוּ-רַע, הוּ-רַע, הוּ-רַע\"...\n(כל המסובים עמדו והכריזו בהתרגשות: \"הוּ-רַע, הוּ-רַע, הוּ-רַע\". ומיד לאח\"ז פתח כ\"ק אדמו\"ר שליט\"א ואמר את המאמר<sup data-n=\"312\">167</sup>)].\nאחרי המאמר צוה כ\"ק אדמו\"ר שליט\"א לנגן ניגון שלש תנועות (דהבעש\"ט, הרב המגיד ואדמו\"ר הזקן). ניגון אדמו\"ר הזקן בן ד' הבבות (וצוה לכפול בבא הרביעית – ג\"פ). \"ניע זשוריצי כלאָפּצי\".\n***<b>לו</b>. כיון שצריכים לחשוב כבר אודות ברכת המזון – הרי לפנ\"ז יש להזכיר גם אודות הענין ד\"שושן פורים\", שכבר עומדים בו:\nב\"שושן\" יש ב' פירושים<sup data-n=\"313\">168</sup>: א) ע\"ד \"שושנת העמקים\"<sup data-n=\"314\">169</sup>, שזוהי דרגא נעלית בקדושה. ב) ע\"ד מ\"ש \"כשושנה בין החוחים\"<sup data-n=\"315\">170</sup>, דקאי על ספירת המלכות, שנקראת שושנה, כפי ש\"רגלי' יורדות מות\"<sup data-n=\"316\">171</sup>, שזהו\"ע \"בין החוחים\", דקאי על לעו\"ז.\nוזהו הענין ד\"שושן פורים\" – לפעול ב\"שושנה בין החוחים\" (במעמד ומצב שצריכים להתעסק גם עם \"חוחים\") שתהי' \"שושנת העמקים\", כמרומז בכך שבשושן הי' הענין ד\"הרוג בשונאיהם\"<sup data-n=\"317\">172</sup> (בירור הלעו\"ז, חוחים) יותר מאשר בשאר העיירות, גם ביום ארבעה עשר<sup data-n=\"318\">173</sup>, ועי\"ז הי' הענין ד\"נוח (לא בארבעה עשר, כבשאר העיירות, אלא) בחמשה עשר בו\"<sup data-n=\"318\">173</sup>, שבו קיימא סיהרא באשלמותא<sup data-n=\"319\">174</sup>, שזהו\"ע נעלה ביותר, ע\"ד \"שושנת העמקים\".\n(וסיים כ\"ק אדמו\"ר שליט\"א:)\nיתן השי\"ת לכאו\"א מאתנו, הוא ובני ביתו, בתוך כלל ישראל, שנזכה להמעמד ומצב דעיר מוקפת חומה באופן ש\"אני אהי' לה גו' חומת אש גו'\"<sup data-n=\"320\">175</sup>, אשר, מצד מדריגה זו לא שייך כלל ענין של גלות, ובמילא תהי' גאולה שלימה ואמיתית שאין אחרי' גלות, במהרה בימינו.\n[כ\"ק אדמו\"ר שליט\"א ברך ברכת המזון על הכוס, ואח\"כ נתן בידו הק' לכל המסובים מ\"כוס של ברכה\".\nטרם צאתו אמר כ\"ק אדמו\"ר שליט\"א:]\n\"אַ גוטן יו\"ט\". ולהתראות בהתוועדות חסידית הבאה בהקדם האפשרי.\n**********",[["146","1","פ\"ו (לעיל ס\"ע 13)."],["147","2","אסתר ט, כג."],["148","3","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370432\" data-slug=\"torah-or\" data-id=\"3901370432\">תו\"א מג\"א צו, ג</a>."],["149","4","שבת פח, ב."],["150","5","אסתר ג, יג."],["151","6","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370434\" data-slug=\"torah-or\" data-id=\"3901370434\">תו\"א מג\"א צז, א</a>."],["152","7","שבת פח, א."],["153","8","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370441\" data-slug=\"torah-or\" data-id=\"3901370441\">תו\"א מג\"א צח, ד</a>."],["154","9","אסתר ט, כח."],["155","10","ראה שיחת פורים תש\"א (סה\"ש תש\"א ע' 77 ואילך). וראה גם מכתב י\"ב אדר שנה זו (אגרות-קודש ח\"ז ס\"ע קפו)."],["156","11","ואתחנן ו, ד."],["157","12","ראה מאמרי אדהאמ\"צ קונטרסים ע' קנ. וש\"נ."],["158","13","רמ\"א יו\"ד סרמ\"ו ס\"ד – מרמב\"ם הל' יסוה\"ת ספ\"ד. הל' ת\"ת לאדה\"ז פ\"א ה\"ד. שם פ\"ב ה\"א, ב, ט."],["159","14","הל' דעות פ\"א ה\"ד. פ\"ב ה\"ב."],["160","15","מגילה ל, א."],["161","16","פרש\"י שם."],["162","17","ציונים לתורה (להר\"י ענגל) כלל לה."],["163","18","חסר המשך השיחה (המו\"ל)."],["164","19","מגילה פ\"ב מ\"ג."],["165","20","שם יט, א (ובפרש\"י)."],["166","21","אסתר ט, כט."],["167","22","רמב\"ם הל' מגילה פ\"א ה\"ג. טושו\"ע או\"ח סתר\"צ ס\"ג."],["168","23","פל\"ה (מה, א). רפל\"ז (מז, א)."],["169","24","ע' א אות קפב. וראה בהנסמן לעיל בהמאמר (ע' 20) הערה 45."],["170","25","אסת\"ר פ\"ג, יו\"ד."],["171","26","יל\"ש אסתר רמז תתרנז (בתחלתו)."],["172","27","שבת צג, סע\"ב (במשנה). רמב\"ם הל' שבת ספי\"ח."],["173","28","ברכות מד, א. רמב\"ם הל' ברכות פ\"ג ה\"ה. טושו\"ע ואדה\"ז או\"ח סקי\"ב. סדר ברכת הנהנין לאדה\"ז פ\"ג."],["174","29","פל\"ז."],["175","30","סנהדרין סה, א."],["176","31","ראה שם פח, ב (במשנה). ירושלמי שם פי\"א ה\"ד. ועוד."],["177","32","מגילה יט, סע\"א."],["178","33","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370531\" data-slug=\"torah-or\" data-id=\"3901370531\">תו\"א מג\"א קיט, א</a>."],["179","34","בשלח יז, יד."],["180","35","מגילה ז, א."],["181","36","אסתר א, א."],["182","37","בהעלותך יב, א."],["183","38","ירמי' כג, כג."],["184","39","ישעי' מד, ו."],["185","40","ראה גם אוה\"ת מג\"א (הוצאת תש\"נ) ע' ג ואילך."],["186","41","פ' ראה יד, א."],["187","42","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380239\" data-slug=\"likkutei-torah\" data-id=\"4001380239\">לקו\"ת אמור לח, ב</a>."],["188","43","מגילה יב, א."],["189","44","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310077\" data-slug=\"tanya\" data-id=\"3401310077\">תניא אגה\"ת פ\"ו</a>. ובכ\"מ."],["190","45","מגילה ז, ב. וראה גם שיחת פורים דאשתקד סכ\"ז ואילך (תורת מנחם – התוועדויות ח\"ה ס\"ע 45 ואילך), ובהנסמן שם."],["191","46","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310033\" data-slug=\"tanya\" data-id=\"3401310033\">תניא ספכ\"ח</a>."],["192","47","שה\"ש ב, ט. וראה שהש\"ר פ\"ב, ח (ב)."],["193","48","ראה תניא אגה\"ק ס\"ד."],["194","49","שיחה זו הוגהה ע\"י כ\"ק אדמו\"ר שליט\"א, ונדפסה בהוספות ל<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021261\" data-slug=\"likkutei-sichot\" data-id=\"1300021261\">לקו\"ש ח\"ב ס\"ע 537</a> ואילך (במהדורא זו ניתוספו ע\"י המו\"ל עוד איזה ציוני מ\"מ)."],["195","50","ראה שיחת י\"ט כסלו שנת פר\"ת (סה\"ש תורת שלום ע' 243)."],["196","51","שבת קיט, א. וש\"נ."],["197","52","בראשית בתחלתו (א, ב)."],["198","53","נדפסה בלקו\"ת לג' פרשיות ג, א (ואח\"כ באוה\"ת בראשית (כרך ו) תתרכו, ב)."],["199","54","שו\"ת המיוחסות לרמב\"ן סרפ\"ג. שו\"ע יו\"ד סקע\"ט ס\"ב. רמ\"א אהע\"ז סס\"ד ס\"ג."],["200","55","אסתר ט, כב."],["201","56","שם, א."],["202","57","ראה תענית כט, א: משנכנס אדר כו' ולמצי נפשי' באדר – הובא במג\"א סתרפ\"ו סק\"ה (יעויין שו\"ת חתם סופר או\"ח סי' ק\"ס, ונימוקי או\"ח לסי' תרפ\"ו, שהקשה עליו). שדי חמד אס\"ד מערכת חתן וכלה סקכ\"א ד\"ה ולפני איזה (וכן ראיתי נוהגין)."],["203","58","ראה שו\"ע אדה\"ז או\"ח סקי\"ט ס\"ג."],["204","59","ראה זח\"א פד, א. שבת סו, ב. פנים יפות סוף פ' בהעלותך. דברי תורה מהד\"ת ס\"ה."],["205","60","ספרי עקב יא, כד."],["206","61","\"מבוא\" לקונטרס \"ומעין\" ע' 22. ולאח\"ז באגרות-קודש שלו ח\"א ע' רסו."],["207","62","ראה גם שיחת פורים דאשתקד סל\"ד (תורת מנחם – התוועדויות ח\"ה ע' 55)."],["208","63","אסתר ח, ח."],["209","64","שם ט, ג."],["210","65","מגילה יג, א."],["211","66","אסתר ב, ה."],["212","67","ואתחנן ד, לה. שם, לט."],["213","68","דב\"ר פ\"ב, כח."],["214","69","<a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא</a> שעהיוה\"א פ\"ו (פ, סע\"ב)."],["215","70","פרדס שי\"ב פ\"ב. ר\"ח שער התשובה פ\"ו. של\"ה פט, א. ועוד."],["216","71","ראה לעיל בהמאמר פ\"ב (ע' 7 ואילך)."],["217","72","ראה שעהיוה\"א שם."],["218","73","לשון אדה\"ז – <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["219","74","תקו\"ז תנ\"ז (צא, סע\"ב)."],["220","75","רמב\"ם ריש הל' יסוה\"ת."],["221","76","ראה גם שיחת יו\"ד שבט סט\"ו ואילך (לעיל ח\"ז ע' 319 ואילך)."],["222","77","סה\"מ תרנ\"ז ע' מח. ועוד."],["223","78","ירושלמי ערלה פ\"א ה\"ג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380107\" data-slug=\"likkutei-torah\" data-id=\"4001380107\">לקו\"ת צו ז, רע\"ד</a>. ובכ\"מ."],["224","79","ברכות ס, סע\"ב."],["225","80","תענית כא, א. וש\"נ."],["226","81","ראה תורת מנחם – התוועדויות ח\"ו ע' 126 ואילך. וש\"נ."],["227","82","מגילה ד, א ובפרש\"י."],["228","83","פרשב\"ם – הובא בתוד\"ה שאף שם."],["229","84","שבת כג, א ובפרש\"י."],["230","85","הל' חנוכה רפ\"ג."],["231","86","ר\"ן שבת שם."],["232","87","פסחים קח, סע\"א ואילך ובפרש\"י ורשב\"ם."],["233","88","סוטה יא, ב."],["234","89","קידושין כט, א (במשנה)."],["235","90","מגילה טו, ב."],["236","91","אסתר ד, יד."],["237","92","ראה שמו\"ר פ\"ב, ו. זח\"א רנג, א. שעה\"פ פ' ויחי."],["238","93","אסת\"ר ספ\"ח. ספ\"ט."],["239","94","ראה של\"ה מד, א. – הובא בקונטרס \"חנוך לנער\" ס\"ע 34 ואילך."],["240","95","לבוש – הובא בט\"ז או\"ח סעת\"ר סק\"ג."],["241","96","הל' דעות רפ\"ד (וראה מכתב נר החמישי שנה זו – אגרות-קודש ח\"ז ע' צט – בהערה)."],["242","97","ראה גם \"רשימות\" חוברת יד ס\"ע 15. תורת מנחם – התוועדויות ח\"א ע' 136 הערה 55. ח\"ג ע' 190. ח\"ז ע' 119. סה\"ש תשמ\"ז ח\"א ע' 332. מכתב כ\"ו תמוז שנה זו (אגרות-קודש ח\"ז ע' שכב), ובהנסמן שם."],["243","98","ראה סהמ\"צ להצ\"צ מצות אחדות ה' (דרמ\"צ ס, ב ואילך)."],["244","99","ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370415\" data-slug=\"torah-or\" data-id=\"3901370415\">תו\"א מג\"א צב, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370346\" data-slug=\"torah-or\" data-id=\"3901370346\">שערי אורה עח, א</a> ואילך. אוה\"ת מג\"א ע' פז ואילך."],["245","100","ראה סה\"ש תורת שלום ע' 120 ואילך."],["246","101","שבת קיט, סע\"ב."],["247","102","תרומה כה, ח."],["248","103","ראה אלשיך עה\"פ. של\"ה סט, א. ועוד."],["249","104","משלי יב, ד. וראה תו\"א ס\"פ ויגש. ובכ\"מ."],["250","105","ראה סה\"מ מלוקט ח\"ב ע' קו ואילך. וש\"נ."],["251","106","אסת\"ר פ\"י, ד."],["252","107","פרק ה."],["253","108","ראה גם שיחת יו\"ד שבט סל\"ג (לעיל ח\"ז ע' 335 ואילך). וש\"נ."],["254","109","מגילה ז, ב (ובפרש\"י)."],["255","110","סוכה כה, סע\"א. וש\"נ."],["256","111","ראה סה\"מ תרנ\"ה ע' לז. המשך תרס\"ו ס\"ע סח ואילך. ועוד."],["257","112","ח\"ג קפו, א."],["258","113","ראה רמ\"א או\"ח סתרצ\"ה ס\"ב."],["259","114","לשון חז\"ל – ב\"מ פג, סע\"ב."],["260","115","או\"ח שם."],["261","116","תהלים ל, יג."],["262","117","תוס' ורא\"ש מגילה שם (ד, א)."],["263","118","ראה שו\"ת נודע ביהודה מהדו\"ק סמ\"א. טורי אבן למגילה שם."],["264","119","טורי אבן שם ה, ב."],["265","120","ראה מדות ספ\"א."],["266","121","ברכות נח, א."],["267","122","ראה זח\"א צב, א. הנסמן בסה\"מ תשי\"א ע' 9."],["268","123","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181319\" data-slug=\"likkutei-sichot\" data-id=\"1300181319\">לקו\"ש חי\"ח ע' 310</a>, ובהנסמן שם."],["269","124","סוטה יו\"ד, א."],["270","125","תהלים פד, יב."],["271","126","ברכות כו, ב. טור או\"ח ר\"ס רלה."],["272","127","טור שם."],["273","128","עירובין סה, א."],["274","129","ראה גם לקו\"ש חל\"ד ע' 44 ואילך."],["275","130","\"התמים\" חוברת ז ע' לד."],["276","131","מו\"ק ה, סע\"א. וש\"נ."],["277","132","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380662\" data-slug=\"likkutei-torah\" data-id=\"4001380662\">לקו\"ת מטות פה, א</a>."],["278","133","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370237\" data-slug=\"torah-or\" data-id=\"3901370237\">תו\"א שמות נג, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381157\" data-slug=\"likkutei-torah\" data-id=\"4001381157\">לקו\"ת שה\"ש ז, א</a>. ובכ\"מ."],["279","134","ראה התוועדויות תשמ\"ה ח\"ה ס\"ע 3102 ואילך, ובהנסמן שם."],["280","135","ב\"סדר קריאת המגילה\"."],["281","136","שו\"ת צ\"צ (הוצאת תשנ\"ד) או\"ח סקי\"ד."],["282","137","כת\"י 855 (בספריית \"אגודת חסידי חב\"ד\") – נעתק בהערות לשו\"ת הנ\"ל."],["283","138","פ\"ב (ה, ד)."],["284","139","כתובות סח, סע\"א. נדרים מא, רע\"א."],["285","140","אבות פ\"ב מ\"ד."],["286","141","ברכות א, ב (ד\"ה והא דאמרינן). הובא בשו\"ע אדה\"ז או\"ח סתר\"ג."],["287","142","אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ד ע' שפד (נעתק ב\"היום יום\" כה תמוז). שם ע' תקמז (נעתק ב\"היום יום\" כא סיון). ועוד."],["288","143","בלק כד, כ."],["289","144","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370426\" data-slug=\"torah-or\" data-id=\"3901370426\">תו\"א מג\"א צה, א</a>. ובכ\"מ."],["290","145","ס\"פ תצא."],["291","146","ראה עטרת צבי לזח\"ב סה, א. וראה גם שיחת פורים דאשתקד סי\"ז (תורת מנחם – התוועדויות ח\"ה ס\"ע 35)."],["292","147","ירושלמי סנהדרין פ\"א ה\"א."],["293","148","פרש\"י ס\"פ בשלח."],["294","149","בראשית ב, ז."],["295","150","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. וראה בהנסמן ב\"מ\"מ, הגהות והערות קצרות\" ב\"לקוטי פירושים\" לשם (ע' לו)."],["296","151","ראה ד\"ה למען דעת תר\"צ פ\"ה (סה\"מ קונטרסים ח\"א פד, א). ד\"ה הוי' לי בעוזרי תרצ\"א (תרפ\"ז) פ\"ג (סה\"מ שם קפ, א. תרפ\"ז ע' רג). סה\"מ אידיש ע' 46. ועוד."],["297","152","\"התמים\" ח\"ב ע' נח. סה\"מ תש\"ח\nע' 292. וראה תורת מנחם – התוועדויות ח\"א ע' 190. וש\"נ."],["298","153","פ\"ה."],["299","154","ראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ע' סז (נעתק ב\"היום יום\" כג סיון). ח\"י ע' שצד. סה\"ש תרפ\"ה ס\"ע 83."],["300","155","לקו\"ד ח\"ג תקטז, א. וראה אגרות-קודש ח\"ד שם. לקו\"ד ח\"ב שיח, א ואילך."],["301","156","זח\"ג קסח, א."],["302","157","פכ\"ט."],["303","158","ראה סה\"ש תרצ\"ז ס\"ע 198. וש\"נ."],["304","159","סכ\"ד."],["305","160","ח\"ג קכד, ב (ברע\"מ)."],["306","161","ראה \"היום יום\" כ\"ף מ\"ח. ובכ\"מ."],["307","162","ע\"ז ה, א ובפרש\"י."],["308","163","פרש\"י עקב ח, ב. ועוד."],["309","164","שבת עג, סע\"א."],["310","165","ראה גם שיחת פורים תשי\"א סכ\"ח (תורת מנחם – התוועדויות ח\"ב ס\"ע 325). שיחת יו\"ד שבט סל\"ד (לעיל ח\"ז ע' 336)."],["311","166","המאמר הוגה ע\"י כ\"ק אדמו\"ר שליט\"א, ויצא לאור ב\"קונטרס פורים תנש\"א\" (נדפס לעיל ע' 15 ואילך. סה\"מ מלוקט ח\"ה ע' קפח ואילך)."],["312","167","ראה ב\"פתח דבר\" למאמר הנדפס בקונטרס הנ\"ל, ש\"אמירתו היתה קשורה, כנראה, עם המאורעות שאירעו בתקופה ההיא עד למפלתו של המושל דמדינה ההיא שהי' צורר ישראל כו'\"*.\n*) <i>ע\"ד פרטי המאורעות – ראה בארוכה ב</i>\"<i>כפר חב\"ד</i>\"<i> פרשת תצוה תשנ\"ג (גליון 563). </i>המו\"ל."],["313","168","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370521\" data-slug=\"torah-or\" data-id=\"3901370521\">תו\"א מג\"א קטז, ג</a>. סה\"מ קונטרסים ח\"א רנז, א."],["314","169","שה\"ש ב, א."],["315","170","שם, ב."],["316","171","משלי ה, ה. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600564\" data-slug=\"or-hatorah-hb\" data-id=\"8316600564\">אוה\"ת נ\"ך עה\"פ (ע' תקסד</a> ואילך)."],["317","172","אסתר ט, טז."],["318","173","שם, יח."],["319","174","זהר ח\"א קנ, רע\"א. ח\"ב פה, רע\"א. ועוד. וראה שמו\"ר פט\"ו, כו."],["320","175","זכרי' ב, ט."]]],[1400140008,"(הנחה בלתי מוגה)\n<b>החודש</b> הזה לכם ראש חדשים ראשון הוא לכם לחדשי השנה<sup data-n=\"321\">1</sup>, וידועה הקושיא<sup data-n=\"322\">2</sup> הרי ראש השנה הוא בתשרי, שנקרא ראש ע\"ש שכולל החיות דכללות השנה וממנו נחלק החיות לחדשים ואח\"כ לימים (כמו שהראש כולל חיות כל הגוף וממנו נמשך החיות בכל האברים)<sup data-n=\"323\">3</sup>, וא\"כ הרי תשרי הוא הראש, ואינו מובן מהו אומרו על ניסן החודש הזה לכם ראש חדשים (ויתרה מזה) ראשון גו' לחדשי השנה. וביותר אינו מובן ע\"פ מ\"ש במכילתא<sup data-n=\"324\">4</sup> החודש הזה לכם אבל לא מנה בו אדה\"ר, והיינו שקודם שנאמרה פרשת החודש הזה לכם הי' תשרי הראש, וא\"כ יוקשה ביותר למה נשתנה להיות החודש הזה לכם ראש חדשים, שאצל ישראל (לכם) ניסן הוא הראש.\nב) <b>וידוע</b> הביאור בזה<sup data-n=\"325\">5</sup>, ע\"פ מ\"ש בעקידה<sup data-n=\"326\">6</sup> שבשני אופני הנהגות אפשר להכיר אלקות. אופן א' הוא הכרת אלקות מהנהגה טבעית, כמ\"ש<sup data-n=\"327\">7</sup> שאו מרום עיניכם וראו מי ברא אלה. ובפרטיות יותר, שהרי הנבראים הם מוגבלים, ובדבר המוגבל אי אפשר להיות חיות בלתי מוגבל, דהנה, אפילו כלים דאצילות שאיהו וגרמוהי חד<sup data-n=\"328\">8</sup>, מ\"מ, להיותם בבחינת גבול, הנה גם האור והחיות שבהם הוא בבחינת גבול<sup data-n=\"329\">9</sup>, ומכ\"ש בבי\"ע, כדאיתא באגה\"ק<sup data-n=\"330\">10</sup> שבכלים דבי\"ע גם האורות דבחינת נפש ורוח הם בבחינת נברא, ועאכו\"כ בנוגע לשמים וארץ הגשמיים שהחיות שבהם הוא בבחינת גבול, ואי אפשר שיהי' בהם חיות בלתי מוגבל<sup data-n=\"331\">11</sup>. ומ\"מ אנורואים שיש בהם ענין של בלי גבול, שזהו שאין בהם שינוי כו', כדאיתא בירושלמי<sup data-n=\"332\">12</sup> ע\"פ<sup data-n=\"333\">13</sup> אלה תולדות השמים והארץ ביום הבראם שהם חזקים כיום הבראם, והיינו דלבד זאת אשר צבא הארץ קיימים במין וצבא השמים קיימים באיש, וכמ\"ש&lt;7&gt; איש לא נעדר, הרי הם גם חזקים כיום הבראם, והיינו, דעם היותם קיימים יותר מה' אלפים שנה, הרי הם חזקים כיום הבראם, וזה מורה על ענין הבלי גבול, שהרי בדבר שהוא מוגבל, והיינו שיש זמן או מקום שנפסק, ניכרת ההגבלה גם באמצעיתו ואפילו בראשיתו, וא\"כ, העדר השינוי מורה על בלי גבול. וענין זה שבדבר המוגבל (שגם החיות שלו הוא מוגבל) יש ענין של בלי גבול, מורה על גדלות הבורא. ואופן הב' הוא הכרת אלקות מהנהגה ניסית שלמעלה מהטבע שהוא שידוד הטבע, שבזה נראה גדלות הבורא. וההפרש בין הכרת האלקות שבב' הנהגות אלו, שבהנהגה הא' יש צורך בהתבוננות כדי להכיר אלקות, והיינו שע\"י התבוננות הוא בא לידי החלטה גמורה כו', אבל אעפ\"כ הרי זה בא דוקא ע\"י התבוננות, וללא התבוננות אין זה ניכר, וטעם הדבר, לפי שהחיות אלקי הוא בהעלם. משא\"כ בהנהגה הב', הרי מיד כשרואה את הנס, הרי גם ללא התבוננות רואה הוא שזה אלקות, והיינו לפי שהחיות האלקי הוא בגילוי. וטעם הדבר הוא, דבהנהגה הא' החיות הוא מחיצוניות האור שבא בהתלבשות ובגבול, ולכן אפשר להיות בהעלם, משא\"כ הנהגה הב' היא מפנימיות האור, היינו, שהחיות הוא כמו שהוא ואינו בא בהתלבשות, ולכן הוא בגילוי. וזוהי המעלה באופן הנהגה הב' על אופן הא', דאף שבשניהם ניכר אלקות, מ\"מ, באופן הא' החיות הוא מתלבש בגבול והוא בהעלם, משא\"כ באופן הב' אין החיות בא בהתלבשות והוא בגילוי. וזהו מ\"ש החודש הזה לכם ראש חדשים גו', דאף שר\"ה הוא בתשרי, מ\"מ אומר על ניסן שהוא ראשון לחדשי השנה, כי, זה שר\"ה הוא בתשרי הוא בענין הנהגה טבעית, שבזה תשרי הוא הראש, אבל בההנהגה הניסית ניסן הוא הראש. וכפי שהאריך הריטב\"א<sup data-n=\"334\">14</sup> שגם לדעת ר\"א שבכ\"ה באלול נברא העולם<sup data-n=\"335\">15</sup>, שלכן ר\"ה הוא בתשרי, הנה אחרי מ\"ת נעשה ניסן הראש למנין התורה ומנין ישראל. וזהו שאמרו חז\"ל<sup data-n=\"336\">16</sup> משבחר הקב\"ה בעולמו קבע להם ראשי חדשים, ומשבחר ביעקב ובניו קבע להם חודש של גאולה, היינו,שבהנהגה הטבעית (בעולמו) תשרי הוא הראש, ובהנהגה ניסית שלמעלה מהטבע, שזהו\"ע חודש של גאולה, ניסן הוא הראשון, וזהו אומרו ראשון הוא לכם לחדשי השנה.\nג) <b>אמנם</b> כל זה הוא ביאור ותירוץ על זה שענינו של ראש השנה בתשרי אינו בסתירה לכך שניסן הוא הראשון, דכיון שישנם ב' אופני הנהגות, הנהגה טבעית והנהגה ניסית, הנה בהנהגה הטבעית תשרי הוא הראשון ובהנהגה הניסית ניסן הוא הראשון. אבל עדיין צריך להבין<sup data-n=\"337\">17</sup> מהו הטעם שבהנהגה ניסית ניסן הוא הראשון, דלכאורה, גם בהנהגה ניסית הי' אפשר להיות תשרי הראשון, שהרי גם ההנהגה שלמעלה מהטבע היא בעולם, ומאחר שהעולם נברא בתשרי, א\"כ הרי גם בהנהגה זו הי' צ\"ל תשרי הראשון. אך הענין הוא, דהנה ידוע<sup data-n=\"338\">18</sup> שיש הפרש בין חדשי הקיץ לחדשי החורף, ובכללות בין חודש ניסן לחודש תשרי, שחדשי הקיץ (שתחילתם מניסן) הם חדשים דדכורא, בחינת ז\"א שרובו חסדים (שהרי חסד אזיל עם כולהו יומין<sup data-n=\"339\">19</sup>), וחדשי החורף (שתחילתם מתשרי) הם חדשים דנוקבא, בחינת מלכות שבנינה מהגבורות. וזהו שחודש ניסן נקרא חודש האביב<sup data-n=\"340\">20</sup>, שאביב סדר הא\"ב מלמעלה למטה, שהוא בחינת חסד<sup data-n=\"341\">21</sup>, ותשרי הוא הסדר דתשר\"ק מלמטה למעלה<sup data-n=\"341\">21</sup>. וכמו כן בהי\"ב צירופי הוי' שבי\"ב החדשים<sup data-n=\"342\">22</sup>, הנה בחודש ניסן צירוף שם הוי' הוא כסדרו<sup data-n=\"343\">23</sup>, שזה מורה על הגילוי דשם הוי', כי, חילוף האותיות הוא לפי שהאור הוא בהעלם, וכיון שבניסן הצירוף הוא כסדרו, הרי זה מורה על הגילוי דשם הוי', שזהו בחינת חסד. משא\"כ חודש תשרי הוא בחינת מלכות שבנינה מהגבורות, והרי ע\"י המלכות נעשה העלם בנבראים, וגם המלכות עצמה היא בחינת העלם, שהרי אוא\"ס שורה בחכמה דוקא, כמ\"ש רבנו הזקן<sup data-n=\"344\">24</sup> בשם הרב המגיד, לפי שבחכמה נרגש הביטול שהוא לבדו הוא ואין זולתו, וא\"כ, בחינתהמלכות שהו\"ע הרוממות וההתנשאות, היפך הביטול דספירת החכמה, הוא העלם. והנה, כיון שהמלכות היא בחינת העלם, לכן צריך להמשיך בה גילוי, שזהו\"ע הצדקה, שהיא במלכות, צדק ה', שצדקה היא בעני שצריך למלאות החסרון שלו, כמ\"ש<sup data-n=\"345\">25</sup> די מחסורו אשר יחסר לו, משא\"כ ניסן שהוא בחינת חסד, הרי זה למעלה מענין הצדקה, כי צדקה היא לעניים בלבד, משא\"כ גמילות חסדים היא בין לעניים בין לעשירים<sup data-n=\"346\">26</sup>, והיינו לפי שצדקה הוא מילוי החסרון, משא\"כ חסד אינו מילוי החסרון, אלא תוספות אור. וזהו ההפרש בין ניסן לתשרי, דתשרי הוא בחינת מלכות שנקראת צדקה, שהוא מילוי החסרון, שזהו האור ששייך אל העולמות, ולכן הוא הראשון בהנהגה טבעית, משא\"כ ניסן הוא בחינת חסד, שהוא האור שלמעלה מהעולמות, ולכן הוא הראשון בהנהגה ניסית שלמעלה מהטבע. ובלשון הקבלה<sup data-n=\"347\">27</sup>, שהנהגה טבעית היא מזיווג חיצוני דחו\"ב שזיווגייהו תדיר לצורך קיום העולמות, וע\"י קיום התומ\"צ הוא זיווג פנימי דחו\"ב שלמעלה מהעולמות. וזהו משבחר ביעקב ובניו, שהו\"ע מ\"ת, קבע להם חודש של גאולה, שענין הגאולה הוא למעלה מהטבע, ובהנהגה זו ניסן הוא הראשון, כיון שניסן הוא בחינת חסד, שהוא האור שלמעלה מהעולמות.\nד) <b>וביאור</b> הענין, דהנה ידוע שהמלכות נקראת תפלה, וכמ\"ש בפע\"ח בתחילתו שהמלכות מתפללת ומתחננת לז\"א בעלה ליתן לה חסרונה, כמ\"ש<sup data-n=\"348\">28</sup> ואני תפלה, וכמו שהאדם למטה מתפלל ומבקש י\"ב ברכות אמצעיות שבהם שואל צרכיו למלאות חסרונו<sup data-n=\"349\">29</sup>, והרי ידוע<sup data-n=\"350\">30</sup> שהבקשה בתפלה צ\"ל על מילוי החסרון שלמעלה, שעי\"ז יתתקן ויתמלא במילא החסרון שלמטה, והיינו שגם למעלה יש ענין של חסרון, וזהו שספירת המלכות מתפללת ומתחננת לז\"א בעלה שימלא חסרונה, כי ספירת המלכות לית לה מגרמה כלום<sup data-n=\"351\">31</sup>, וזהו שדוד הוא בר נפלי<sup data-n=\"352\">32</sup>, ולא הוו לי' שנין, ונמשכו לו שנים מאדה\"ר והאבות<sup data-n=\"353\">33</sup>, ולזה מתחננת המלכות לז\"א שימלא חסרונה. והנה, אף שמילוי החסרון הוא מאור הסובב דוקא,שלהיותו למעלה מחסרון נמשך ממנו מילוי החסרון, מ\"מ, מתחננת המלכות לז\"א, שהוא אור הממלא, לפי שההמשכה מאור הסובב היא ע\"י אור הממלא דוקא. דהנה, המלכות נקראת דיבור, ואנו רואים בדיבור למטה שאין התינוק מדבר עד שמתגדל ויש לו שכל, ודיבורו הוא במה שלבו חפץ, היינו, בחינת המדות, ומ\"מ אינו מדבר אלא כאשר הוא רוצה דוקא, והיינו שההמשכה היא מהרצון ע\"י השכל והמדות. וכמו כן הוא בספירת המלכות, שההמשכה היא מאור הסובב ע\"י אור הממלא דוקא, ולכן היא מתפללת לז\"א בעלה שימלא חסרונה.\n<b>והענין</b> בזה, דהנה, מספירת המלכות נעשה התהוות העולמות, והרי התהוות העולמות היא מחסרון האור, חסרון אחר חסרון, כידוע<sup data-n=\"354\">34</sup> שעד שלא נברא העולם הי' הוא ושמו בלבד, ומבואר בכ\"מ<sup data-n=\"355\">35</sup> דשם ואור הו\"ע אחד, ששניהם הארה בלבד, והיינו, שהתהוות העולמות היא מהארה בלבד. וכמבואר<sup data-n=\"356\">36</sup> ההפרש בין אור ושפע, דבשפע הנה השפע גורם שינוי בהמשפיע, שאינו דומה קודם השפעה בעת ההשפעה ואחרי ההשפעה, דקודם ההשפעה הוא מכין עצמו להשפיע, ובעת ההשפעה הוא טרוד ומוגבל בהשפעה, ואחרי ההשפעה הוא משתנה מכמו שהי' בעת ההשפעה, וטעם הדבר הוא לפי שההשפעה היא מהות ומציאות דבר מה שהמשפיע נותן מעצמו (ער גיט דאָס פון זיך), ולכן הרי זה גורם שינוי בהמשפיע. ובזה נכלל גם שההשפעה גורמת שינוי בהמשפיע למעליותא, כמאמר<sup data-n=\"357\">37</sup> ומתלמידי יותר מכולם, שזהו לפי שההשפעה היא מהות דבר. וכל זה הוא בשפע, משא\"כ באור שאינו גורם שינוי, לפי שהאור הוא הארה בלבד. אמנם, יש גם מעלה באור על שפע, שהאור הוא כמו העצם, שהרי השפע משתנה לפי אופן המקבל, משא\"כ האור הוא כמו העצם. וזהו הטעם שההתהוות הוא מהאור, דאף שאפשרות ההתהוות היא בכח העצמות דוקא, שהוא לבדו בכחו ויכלתו להוות יש מאין לפי שמציאותו מעצמותו ואין לו עילה וסיבה קודמת ח\"ו<sup data-n=\"358\">38</sup>, מ\"מ ההתהוות היא ע\"י האור, לפי שהאור הוא כמו העצם. אך כיון שהאור הוא כמו העצם, לכן אי אפשר להיות ההתהוות מהאור, כי אם ע\"י הצמצום דוקא. ונמצא, שכללות ענין ההתהוות הוא מחסרון האור, חסרון אחר חסרון, שהרי כלההתהוות היא מהשם שהוא הארה בלבד, ולכן נקראת בריאה יש מאין, דאף שממך הכל<sup data-n=\"359\">39</sup>, מ\"מ נקרא בשם אין, להיותו הארה בלבד שלגבי מעלה נקרא בשם אין<sup data-n=\"360\">40</sup>. ובאור גופא הנה ההתהוות היא מבחינה אחרונה שבאור, והיינו בחינת מלכות דא\"ס, וגם בזה הי' העלם וצמצום ונשאר רק בחינת מלכות דמלכות, כמ\"ש בע\"ח<sup data-n=\"361\">41</sup> כאילו נאמר מלכות דמלכות דא\"ס. וז\"ש<sup data-n=\"362\">42</sup> אתה הוא הוי' לבדך אתה עשית את השמים וגו', אתה הוא הוי' לבדך קאי על בחינת אוא\"ס שלפני הצמצום, ולאח\"ז נאמר אתה עשית גו' את חסר ה', לפי שחסרו ה' פרצופים מן הכתר עד המלכות, ונשאר רק בחינת מלכות שבמלכות, שיכולה להיות בבחינת מקור לעולמות. וכמו כן לאחר הצמצום, כל מה שנמשך ומשתלשל מציאות העולמות הוא בחינת חסרון האור, וכמ\"ש בעץ חיים<sup data-n=\"363\">43</sup> שבעקודים (שהוא התחלת ההשתלשלות) אינו מאיר רק ב' בחינת מקיפים וה' פנימיים, ובאצילות הרי כללות הגילוי הוא רק הארת הקו בלבד, וגם באורות פנימיים דאצילות המאירים בבי\"ע הרי בבריאה חסר בחינת כתר וחכמה, ואינו מאיר רק בחינת בינה, דאימא עילאה מקננא בכורסיא<sup data-n=\"364\">44</sup>, וביצירה רק בחינת ז\"א, ובעשי' רק בחינת מלכות. ומכל זה מובן שההתהוות היא מחסרון האור, חסרון אחרי חסרון, ולהיות שההתהוות שמחסרון האור היא מספירת המלכות, לכן הנה המלכות מתפללת לז\"א בעלה שימלא חסרונה.\n<b>והנה</b> מילוי החסרון הוא ע\"י ענין הצדקה, שגם כאשר היא בריבוי גדול, אפילו סוס לרכוב כו'<sup data-n=\"365\">45</sup>, הרי זה רק מילוי החסרון בלבד, ובכללות הוא הגילוי ששייך לעולמות. אמנם, ענין החסד הוא בין לעניים בין לעשירים, והענין בזה, דהנה, אין עני אלא בדעת ואין עשיר אלא בדעת<sup data-n=\"366\">46</sup>, וידוע שבעמידת הדעת יש ב' אופנים, דכאשר הספירות הן זה תחת זה (שהוא הסדר דתהו)<sup data-n=\"367\">47</sup>, אזי הדעת עומדת תחת המוחין חו\"ב וממשכת אל המדות, וזהו בחינת עניות, היינו שהדעת היא בבחינתהגבלה, שהרי ההמשכה היא כפי אופן קבלתה מחו\"ב שהוא בהגבלה, משא\"כ כאשר הספירות הן בג' קוין&lt;47&gt;, אזי הדעת עומדת תחת הכתר, שהוא למעלה מחסרון וצמצום, והו\"ע העשירות בדעת. וזהו ההפרש בין חסד לצדקה, דצדקה הוא לעניים, שהוא האור שבבחינת הגבלה ששייך לעולמות, משא\"כ חסד הוא גם לעשירים, שהוא האור שבבחינת בלי גבול שלמעלה מהעולמות.\nה) <b>וזהו</b> ג\"כ ההפרש בין תורה ותפלה, דהנה, תפלה ענינה מילוי החסרון, שזהו הבקשה בי\"ב ברכות אמצעיות להיות רופא חולים ומברך השנים כו', דענין החולי הוא שיש בו אש זרה שלא מצד הבריאות, וענינו בעבודה, שכאשר חסר באש דקדושה אזי נעשה אצלו אש זרה כו', ועי\"ז פועל גם למעלה, כמ\"ש<sup data-n=\"368\">48</sup> צור ילדך תשי, שמתישים כביכול כח של מעלה<sup data-n=\"369\">49</sup>. ויש אופן נעלה יותר בחולה, כמ\"ש<sup data-n=\"370\">50</sup> חולת אהבה אני, והיינו שיש לו אהבה לאלקות ואין לו במה להשביע את האהבה (ער האָט ניט מיט וואָס צו משביע זיין דאָס), וכדאיתא בכתבי האריז\"ל<sup data-n=\"371\">51</sup> שחולה בגימטריא מ\"ט, היינו שיש לו המ\"ט שערים וכל הענינים השייכים אליהם, ומ\"מ יש בו ענין הצמאון, כיון שחסר לו שער הנו\"ן, והיינו שאין לו במה לרוות את צמאונו. וכן הוא גם למעלה בספירת המלכות, דנהורא תתאה קארי תדיר לנהורא עילאה ולא שכיך<sup data-n=\"372\">52</sup>, שאין לה במה לרוות את צמאונה, שהו\"ע החולי. ועל זה הוא הבקשה רופא חולים. ומברך השנים הוא הבקשה ותן טל ומטר לברכה, דהנה, כאשר חטא ופגם ועבר את הדרך, אזי לא נמשך המטר<sup data-n=\"373\">53</sup>, וגם בנוגע לטל שלא מיעצר<sup data-n=\"374\">54</sup>, נעשה שינוי שאינו מקבל את הטל<sup data-n=\"373\">53</sup>. ועל זה היא הבקשה שיתמלא החסרון, היינו, מילוי החסרון שלמעלה, ובמילא יתמלא גם החסרון למטה, תחילה ברוחניות, ויומשך גם בגשמיות. וכל זה הוא בתפלה שענינה מילוי החסרון. משא\"כ תורה היא בחינת חסד, כמ\"ש<sup data-n=\"375\">55</sup> ותורת חסד, והיינו שענין התורה אינו מילוי החסרון, אלא התורה היא אור שלמעלה מהעולמות. וזהו שאמרו חז\"ל על הפסוק החודש הזה לכם, משבחר ביעקב ובניו קבע להם חודש של גאולה, דהנה, פרשת החודשהזה לכם היא התחלת התורה, כמ\"ש רש\"י בתחילת פירושו על התורה אמר ר' יצחק לא הי' צריך להתחיל התורה אלא מהחודש הזה לכם. וגם הבחירה ביעקב ובניו קשורה עם מ\"ת, וכידוע שהתחלת שני אלפים תורה הוא מאברהם אבינו<sup data-n=\"376\">56</sup>. וכיון שהתורה היא בחינת חסד, לכן מצד התורה הסדר הוא באופן דהחודש הזה לכם, שהו\"ע ההנהגה ניסית שלמעלה מהטבע. ומדייק החודש הזה לכם דוקא, ולא מנה בו אדם הראשון, לפי שהזיווג חיצוני דחו\"ב זיווגייהו תדיר לצורך קיום העולמות, והיינו שענין זה הי' עוד קודם מ\"ת, וגם אחרי מ\"ת אין צריך על זה עבודה דוקא, ונמשך גם ע\"י המלאכים שהם שלוחי השפע, שזהו\"ע המזל המכה בו ואומר לו גדל<sup data-n=\"377\">57</sup>, דשרש המלאכים הוא מהזיווג חיצוני<sup data-n=\"378\">58</sup>. אבל הזיווג פנימי דחו\"ב שהוא שרש ההנהגה ניסית נמשך ע\"י עבודה דוקא, ולכן מדייק החודש הזה לכם.\nו) <b>ובזה</b> יובן ג\"כ מה שאמרו רז\"ל<sup data-n=\"379\">59</sup> בתשרי בטלה העבודה מאבותינו, דהנה, כאשר ישנו חסרון, צריך להיות תחילה מילוי החסרון, ואח\"כ יכול להיות המשכת העשירות שלמעלה ממילוי החסרון. וכמו כן הי' גם ביצי\"מ, שבתחילה הי' צ\"ל מילוי החסרון, וענין זה הי' בתשרי שענינו צדקה כנ\"ל, ולכן בתשרי בטלה העבודה מאבותינו. אבל עדיין אין זה ענין הגאולה שלמעלה מהטבע, שענין זה הי' בניסן דוקא, בחינת חסד. והענין בזה, דהנה, ביצי\"מ נאמרו ד' לשונות של גאולה<sup data-n=\"380\">60</sup>, והוצאתי והצלתי וגאלתי ולקחתי<sup data-n=\"381\">61</sup>, והוצאתי אתכם מתחת סבלות מצרים הו\"ע היציאה מן הרע ע\"י מילוי החסרון, והוא ע\"י גילוי אור הממלא, שבו שייך ענין החסרון (סבלות מצרים), ונמשך מילוי החסרון כו'. והצלתי הוא מלשון צל, בחינת מקיף, שהוא אור הסובב, וכנ\"ל (ס\"ג) דמילוי החסרון הוא מאור הסובב דוקא. וגאלתי הו\"ע סמיכת גאולה לתפלה<sup data-n=\"382\">62</sup>, דתפלה היא מילוי החסרון כנ\"ל. וכל זה הי' בתשרי. אמנם, ולקחתי אתכם לי לעם הו\"ע המשכת העצמות, וע\"ד מ\"ש<sup data-n=\"383\">63</sup> ועברתי בארץ מצרים גו' אני ה', אני ולא מלאך ולא שליח ולא אחר<sup data-n=\"384\">64</sup>, כי אם עצמותו ומהותו,והו\"ע זיווג פנימי דחו\"ב שההמשכה היא מלמעלה מעלה עד בחינת העצמות, וע\"ד מארז\"ל<sup data-n=\"385\">65</sup> קשה לזווגם כקריעת ים סוף, לפי שבענין הנישואין יש המשכת הא\"ס כידוע<sup data-n=\"386\">66</sup>. וענין זה הי' בניסן דוקא, לפי שניסן הוא בחינת חסד כנ\"ל. וזהו גם מה שאמרו חז\"ל<sup data-n=\"387\">67</sup> בניסן נגאלו ובניסן עתידין להגאל, במהרה בימינו ע\"י משיח צדקנו.\n**********",[["321","1","בא יב, ב."],["322","2","ראה אוה\"ת בראשית יח, סע\"ב ואילך. ד\"ה החודש הזה לכם תרט\"ו (מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' ע). תרנ\"ד (סה\"מ תרנ\"ד ע' קלא). תרס\"ו (המשך תרס\"ו ע' קנו). עת\"ר (סה\"מ עת\"ר ע' רצה). תרע\"ח (סה\"מ תרע\"ח ע' רכד)."],["323","3","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבוא מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">נצבים מז, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">דרושי ר\"ה נח, א</a> ואילך. עט\"ר שער ר\"ה בתחילתו."],["324","4","עה\"פ."],["325","5","בכל הבא לקמן – ראה ד\"ה הנ\"ל תרע\"ח (סה\"מ תרע\"ח ע' רכד ואילך)."],["326","6","פ' בא עה\"פ החודש גו' (שער לח)."],["327","7","ישעי' מ, כו."],["328","8","תקו\"ז בהקדמה (ג, ב)."],["329","9","ראה המשך תרס\"ו ע' קצא."],["330","10","ס\"כ (קל, א)."],["331","11","ראה מו\"נ בההקדמות לח\"ב – הקדמה יב. הובא בהמשך תרס\"ו שם."],["332","12","ריש ברכות."],["333","13","בראשית ב, ד."],["334","14","בחידושיו לר\"ה ז, א."],["335","15","ויק\"ר רפכ\"ט. פסיקתא דר\"כ פיסקא כג (בחודש השביעי). ובכ\"מ."],["336","16","שמו\"ר פט\"ו, יא."],["337","17","בהבא לקמן – ראה ד\"ה הנ\"ל תרע\"ח (סה\"מ תרע\"ח ע' רכו)."],["338","18","ראה לקוטי תורה להאריז\"ל פ' ויצא ד\"ה ענין הז' כוכבי לכת. קהלת יעקב מערכת יב חדשים (הערת כ\"ק אדמו\"ר שליט\"א בסה\"מ ה'ש\"ת ע' 28)."],["339","19","ראה זח\"ג קג, א-ב. קצא, ב. סה\"מ תש\"ח ע' 144."],["340","20","בא יג, ד. וראה רמב\"ם הל' קידוש החודש פ\"ד ה\"א."],["341","21","ראה זח\"ב קפו, א. שם נא, ב (הערת כ\"ק אדמו\"ר שליט\"א שם)."],["342","22","ראה פרדס שער יג (שער השערים) פ\"ג. משנת חסידים סדר מסכת ניסן ואילך (בכוונת כל חודש). ובכ\"מ. וראה אוה\"ת בראשית טו, א ואילך. בא ע' רנד. ר\"ה ע' א'שנב ואילך. ובכ\"מ."],["343","23","פרדס שער כא (שער פרטי השמות) פט\"ז. משנת חסידים שם מסכת ניסן."],["344","24","<a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה</a> (בהגהה)."],["345","25","פ' ראה טו, ח."],["346","26","סוכה מט, ב."],["347","27","הובא ונתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">לקו\"ת נצבים מז, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381211\" data-slug=\"likkutei-torah\" data-id=\"4001381211\">שה\"ש כ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381219\" data-slug=\"likkutei-torah\" data-id=\"4001381219\">כב, ג</a>."],["348","28","תהלים קט, ד."],["349","29","ברכות לד, א."],["350","30","ראה גם ד\"ה כי תשא (לעיל ח\"ז ע' 345 ואילך)."],["351","31","זח\"א קפא, א. רמט, ב. ח\"ב ריח, ב. עץ חיים שער ו (שער העקודים) פ\"ה."],["352","32","מגלה עמוקות ויצא (לט, ב). וראה יל\"ש בראשית רמז מא. זח\"א נה, א. צא, ב. קסח, א. ועוד."],["353","33","יל\"ש וזוהר שבהערה הקודמת."],["354","34","פדר\"א פ\"ג."],["355","35","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380254\" data-slug=\"likkutei-torah\" data-id=\"4001380254\">לקו\"ת בהר מא, ג</a>. המשך תרס\"ו ס\"ע תסב. ועוד."],["356","36","ראה מאמרי אדמו\"ר הזקן תקס\"ב ח\"א ע' מב. רסא. ח\"ב ס\"ע תכב ואילך. המשך תרס\"ו ע' קעג ואילך. ובכ\"מ."],["357","37","תענית ז, א."],["358","38","אגה\"ק ס\"כ."],["359","39","דברי הימים-א כט, יד."],["360","40","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380794\" data-slug=\"likkutei-torah\" data-id=\"4001380794\">לקו\"ת פ' ראה יט, סע\"ג</a>. ובכ\"מ."],["361","41","שער מב (שער דרושי אבי\"ע) פ\"א."],["362","42","נחמי' ט, ו. וראה סה\"מ תר\"ס ע' מג ואילך. עזר\"ת ע' קיז ואילך. ובכ\"מ."],["363","43","שער ו (שער העקודים) פ\"ב."],["364","44","תקו\"ז ת\"ו (כג, א). ע\"ח שער מז (שער סדר אבי\"ע) פ\"ג. תניא פל\"ט. ועוד."],["365","45","כתובות סז, רע\"ב."],["366","46","ראה שם סח, א. נדרים מא, א. זח\"ג רעג, ב."],["367","47","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370089\" data-slug=\"torah-or\" data-id=\"3901370089\">תו\"א תולדות יט, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370116\" data-slug=\"torah-or\" data-id=\"3901370116\">וישלח כד, ד</a>. מאמרי אדמו\"ר הזקן תקס\"ח ח\"א ע' א. תקס\"ט ס\"ע יג ואילך. ובכ\"מ."],["368","48","האזינו לב, יח."],["369","49","ראה איכ\"ר פ\"א, לג."],["370","50","שה\"ש ב, ה."],["371","51","טעמי המצוות פ' וירא. מאו\"א ח, לה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת ברכה צז, ב</a>. ובכ\"מ."],["372","52","ראה זוהר ח\"ב קמ, א. ח\"א קעח, ב. עז, ב. פו, ב."],["373","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381016\" data-slug=\"likkutei-torah\" data-id=\"4001381016\">לקו\"ת האזינו עג, ב</a>. ובכ\"מ."],["374","54","תענית ג, א."],["375","55","משלי לא, כו."],["376","56","סנהדרין צז, סע\"א. ע\"ז ט, א."],["377","57","ראה ב\"ר פ\"י, ו. זוהר ח\"א רנא, א (בהשמטות). ח\"ב קעא, ב. מו\"נ ח\"ב פ\"י. תניא אגה\"ק סוס\"כ (קלב, א)."],["378","58","ראה עץ חיים שער לט (שער מ\"ן ומ\"ד) דרוש ד. מאמרי אדמו\"ר הזקן ענינים ע' רמ ואילך. סה\"מ תרצ\"ו ע' 43. וש\"נ."],["379","59","ראה ר\"ה יא, א-ב."],["380","60","ראה גם סה\"מ תרע\"ח ע' קמד ואילך."],["381","61","וארא ו, ו-ז."],["382","62","ראה ברכות יו\"ד, ב."],["383","63","בא יב, יב."],["384","64","ראה ספרי תבוא כו, ח. זח\"א קיז, א. סדר הגש\"פ."],["385","65","פסחים קיח, א. סוטה ב, א. וש\"נ."],["386","66","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381287\" data-slug=\"likkutei-torah\" data-id=\"4001381287\">לקו\"ת שה\"ש לט, ד</a> ואילך. מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תרעא ואילך. סה\"מ תרנ\"ב ס\"ע קל. תרנ\"ז ע' קעט. ובכ\"מ."],["387","67","ר\"ה יא, א. שמו\"ר פט\"ו, יא."]]],[1400140009,"בלתי מוגה\n<b>א</b>. כ\"ק אדמו\"ר שליט\"א צוה לנגן ואמר מאמר ד\"ה החודש הזה לכם ראש חדשים.\n***\n<b>ב</b>. איתא בגמרא<sup data-n=\"388\">1</sup> \"באחד בניסן ראש השנה לחדשים . . מנלן דכתיב<sup data-n=\"389\">2</sup> החודש הזה לכם ראש חדשים ראשון הוא לכם לחדשי השנה\". כלומר: אע\"פ שהתחלת השנה היא מחודש תשרי, מ\"מ, מנין החדשים מתחיל מחודש ניסן.\nאמנם, בהענין ד\"ראש השנה לחדשים\" אין נפק\"מ בנוגע למנין השנים<sup data-n=\"390\">3</sup>.\nאך ישנו עוד ענין באחד בניסן שנוגע למנין השנים – כדאיתא במשנה<sup data-n=\"391\">4</sup> \"באחד בניסן ראש השנה למלכים\", \"רגילים היו למנות זמן שטרותיהם לשנות המלך . . וקבעו חכמים אחד בניסן לתחלת שנתו, ואפילו עמד בשבט או באדר, כלתה שנתו משהגיע ניסן, ויתחילו למנות לו שנה שני'\"<sup data-n=\"392\">5</sup>.\nועוד זאת, ש\"באחד בניסן ראש השנה לרגלים\", \"נפקא מינה לנודר למיקם עלי' בבל תאחר\", שאינו עובר בבל תאחר עד שיעברו עליו ג' רגלים כסדרן, וחג המצות תחילה<sup data-n=\"393\">6</sup>.\nוצריך להבין: מהי השייכות של \"רגלים\" ו\"מלכים\" לחודש ניסן דוקא, שלכן נקבע אחד בניסן להיות ראש השנה למלכים ולרגלים, אע\"פ שהתחלת השנה היא מחודש תשרי?\n<b>ג</b>. ויש לבאר תחילה כללות הענין ד\"רגלים\":החילוק שבין יו\"ט (רגל) לשבת – ששבת \"מקדשא וקיימא\"<sup data-n=\"394\">7</sup>, משא\"כ יו\"ט שקביעותו תלוי' בב\"ד, שנאמר<sup data-n=\"395\">8</sup> \"אלה מועדי ה' אשר תקראו אותם\", אתם כתיב, \"אתם אפילו שוגגין אתם אפילו מזידין כו'\"<sup data-n=\"396\">9</sup>.\nוהענין בזה:\nהקדושה דשבת נקבעה מצד הבריאה עצמה, היינו, שנקבע בהבריאה שיש ענינים של חול ויש ענינים של קדושה. וכיון שכן, הרי גם הקדושה (שבת שמקודש מימי החול) היא במדידת והגבלת העולם, קדושה שבסדר השתלשלות.\nמשא\"כ הקדושה דיו\"ט שלא נקבעה מצד הבריאה עצמה, אלא זהו ענין שנמסר לב\"ד – נשמות ישראל שאינם נתונים תחת שליטת הטבע, ויש להם כח התורה, להיותם סמוכין איש מפי איש עד משה רבינו, שקיבל תורה מפי הגבורה – שבכחם לפעול קדושה גם ביום כזה שמצד הבריאה עצמה הוא יום חול, הרי קדושה זו היא למעלה ממדידת והגבלת העולם, המשכה שלמעלה מסדר השתלשלות.\nוזוהי השייכות ד\"רגלים\" לחודש ניסן:\nנתבאר בהמאמר<sup data-n=\"397\">10</sup> החילוק שבין תשרי לניסן, שתשרי הוא ראש השנה דסדר הנהגת העולם, הנהגה טבעית, וניסן הוא הראש להנהגה שלמעלה מהטבע, הנהגה נסית, כמרומז גם בשם \"ניסן\", מלשון נסים<sup data-n=\"398\">11</sup>.\nוכפי שנתבאר, שחדשי הקיץ (שהתחלתם מניסן) הם חדשים דדכורא, בחי' ז\"א, שעיקרו חסדים, ענין האור והגילוי, והוא למעלה מבחי' מלכות, שעיקר בנינה מהגבורות (העלם), שמשם הם החדשים דנוקבא, חדשי החורף (שהתחלתם מתשרי).\nוכיון שניסן הוא הראש להנהגה שלמעלה מהטבע, נקבע בו \"ראש השנה לרגלים\", שענינם המשכת הקדושה (לא רק ש\"מקדשא וקיימא\" בסדר השתלשלות, אלא) שלמעלה מסדר השתלשלות.\nוענין זה (שניסן הוא הראש והראשון) נתחדש במתן תורה (החל מיצי\"מ שהיא ההכנה למ\"ת) – שהרי בתחלת הבריאה הי' תשרי חודש הראשון, ובמ\"ת נעשה ניסן חודש הראשון, כמ\"ש התרגום על הפסוק<sup data-n=\"399\">12</sup> \"ויקהלו גו' בירח האיתנים בחג הוא החודש השביעי\", \"בירחא דעתיקייאקרן לי' ירחא קדמאה וכען (לאחר מ\"ת) הוא ירחא שביעאה\"<sup data-n=\"400\">13</sup> – כיון שבמ\"ת נתחדשה הבעלות של נש\"י על העולם, שע\"י התורה פועלים בעולם הנהגה שלמעלה מהטבע.\n<b>ד</b>. וזהו גם הטעם שאחד בניסן הוא \"ראש השנה למלכים\":\n\"ניסן\" – מלשון נסים – הוא גם מלשון \"כנשוא נס הרים\"<sup data-n=\"401\">14</sup>, שהו\"ע ההגבהה וההתנשאות למעלה מהטבע.\nוזוהי השייכות דניסן למלכים – שאחד בניסן הוא \"ראש השנה למלכים\" – כיון שמלכי בית דוד הכשרים נקראים בשם \"נשיא\"<sup data-n=\"402\">15</sup>, מלשון התנשאות, ובזה נכלל (לא רק ענין ההתנשאות על העם, אלא) גם הענין דהתנשאות עצמית שלמעלה לגמרי ממציאות העם, ובשרשו למעלה הו\"ע מלכות דא\"ס שלמעלה מסדר השתלשלות.\n<b>ה</b>. והנה, כיון ש\"כל ישראל בני מלכים הם\"<sup data-n=\"403\">16</sup>, הרי מובן, שענין ההתנשאות שבמלכים, שהו\"ע ההגבהה שלמעלה מהטבע (כנ\"ל), ישנו אצל כל בנ\"י.\nוהענין בזה – שלכאו\"א מישראל יש כח <i>להתעלות</i> מסדר ההנהגה שמצד טבע העולם שהגוף ונפש הבהמית וחלקו בעולם מעלימים ומסתירים על הנשמה, שלא זו בלבד שלא יעלימו ויסתירו, אלא אדרבה, הנשמה נעשית בעה\"ב עליהם, לפעול שעל ידם תתמלא ותושלם הכוונה דירידה צורך עלי', שתתעלה לדרגא נעלית יותר מכמו שהיתה קודם ירידתה למטה.\nוענינו בעבודה בפועל – שאין זה באופן שבמשך כל היום כולו מונח הוא בהוויות העולם, ובינתיים נזכר גם על הקב\"ה, ולכן לומד פרק אחד שחרית ופרק אחד ערבית, אלא אדרבה: במשך כל היום, מהרגע שניעור משנתו, חושב הוא אודות הקב\"ה, ולכן מתפלל כדבעי, ולומד שיעור בתורה, ובזה דוקא מונח הוא בכל מציאותו; אלא שבינתיים נזכר שיש גם מציאות העולם, ומצד הכוונה העליונה צריכה להיות עבודתו גם בבירור חלקו בעולם, ולכן כופה את עצמו להתנתק לרגע מתפלה ותורה כדי לעסוק בעבודת הבירורים.\n<b>ו</b>. ובפרטיות יותר:ידוע<sup data-n=\"404\">17</sup> החילוק שבין עולמות בי\"ע לעולם האצילות, שבעולמות בי\"ע, מציאות בפשיטות ואלקות בהתחדשות, משא\"כ בעולם האצילות, אלקות בפשיטות ומציאות בהתחדשות.\nודוגמתו בהנשמה – שקודם ירידתה למטה הרי היא באצילות (כמבואר<sup data-n=\"405\">18</sup> בפירוש \"נשמה שנתת בי טהורה היא\"<sup data-n=\"406\">19</sup> שקאי על עמידתה בעולם האצילות) ששם אלקות בפשיטות ומציאות בהתחדשות, משא\"כ לאחרי ירידתה בגוף כו'.\nוזאת תובעים מיהודי – שהירידה בגוף לא תפעל העלם והסתר בהנשמה, אלא גם בהיותה למטה תהי' כמו שהיתה למעלה (ואדרבה, שע\"י הירידה למטה תתעלה לדרגא נעלית יותר, כנ\"ל) – שאלקות בפשיטות ומציאות בהתחדשות.\n<b>ז</b>. אמנם, על זה שואל יהודי קושיא:\nכיון שמצד ירידת הנשמה למטה נמצא הוא בגוף ונפש הבהמית בעולם הזה הגשמי והחומרי, ונוסף לזה, ידע איניש בנפשי' מעמדו ומצבו מצד מעשיו דיבוריו ומחשבותיו שלא כדבעי, שחטא ופגם והעביר את הדרך – איך יתכן שיהי' אצלו אלקות בפשיטות ומציאות בהתחדשות?\nוהמענה לזה – בדיבור הראשון דמ\"ת, שענינו הוא השליטה על הטבע ע\"י הנהגה שלמעלה מהטבע – \"אנכי הוי' אלקיך אשר הוצאתיך מארץ מצרים\"<sup data-n=\"407\">20</sup>:\nהקב\"ה אומר לכאו\"א מישראל \"אנכי הוי' אלקיך\" – לשון יחיד<sup data-n=\"408\">21</sup> – ש\"הוי'\", שענינו הי' הוה ויהי' כאחד<sup data-n=\"409\">22</sup>, למעלה מהטבע, הוא \"אלקיך\", כחך וחיותך<sup data-n=\"410\">23</sup>,\nועי\"ז \"הוצאתיך מארץ מצרים\" – שניתן לו הכח לצאת מכל המיצרים וההגבלות של העולם, הן אלה שמצד העולם כשלעצמו, והן אלה שגרם ע\"י מעשיו כו'.\nויתירה מזה: לא זו בלבד שבכחו לעמוד במעמד ומצב שהגוף ונפש הבהמית לא ישלטו עליו, עי\"ז שיברח מהם כו', אלא אדרבה,שבכחו לברר ולזכך את הגוף ונפש הבהמית עצמם, כתורת הבעש\"ט<sup data-n=\"411\">24</sup> על הפסוק<sup data-n=\"412\">25</sup> \"כי תראה חמור שונאך וגו' עזוב תעזוב עמו\", שאין לשבור את הגוף ע\"י תעניות וסיגופים, אלא לבררו ולזככו כו'.\nוכיון שכן, יכולים לדרוש ממנו את היציאה מהמיצרים וגבולים באופן כזה שעכ\"פ בנוגע להנהגה בפועל יהי' מונח אצלו אלקות בפשיטות ומציאות בהתחדשות.\n<b>ח</b>. ועוד זאת, שהענין ד\"הוצאתיך מארץ מצרים\" הוא בנקל יותר בימינו אלה מכמו ביצי\"מ בפעם הראשונה, כי:\nבהיותם במצרים, \"ערות הארץ\"<sup data-n=\"413\">26</sup>, היו בנ\"י שקועים במ\"ט שערי טומאה<sup data-n=\"414\">27</sup>, וזו היתה הגלות הקשה ביותר. ואע\"פ שההשמדות וההריגות רח\"ל שהיו בגלויות שלאח\"ז לא היו בגלות מצרים (כנראה ממדרשי חז\"ל), מ\"מ, היתה זו הגלות הקשה ביותר, מכמה טעמים: (א) להיותה הגלות הראשונה, (ב) ולהיותה קודם הבירור והזיכוך שנעשה בעולם ע\"י מ\"ת (כמשנ\"ת במק\"א<sup data-n=\"415\">28</sup>).\nואם מגלות מצרים שהיתה הקשה ביותר, יצאו בנ\"י – משאר הגלויות, שהן קלות יותר, וישנו גם הכח דמ\"ת, הרי בודאי שיש בכחו של כאו\"א מישראל לצאת מהם.\nובפרט בעמדנו בעקבתא דעקבתא דמשיחא, לאחרי כל מה שכבר פעלו בדורות שלפנינו בבירור הניצוצות כו', ובמילא ישנו הסיוע של ניצוצות הקדושה שכבר נתבררו, ומה גם שלא נשאר לנו לפעול אלא דבר מועט בלבד (\"אַ קלייניקייט\"), והיינו, שהמעלה בעבודה עתה היא הן מצד המברר והן מצד המתברר – הרי בודאי שיש בכח לצאת מכל המיצרים והגבולים, כך, שבנוגע להנהגה בפועל עכ\"פ יהי' מונח אצלו אלקות בפשיטות ומציאות בהתחדשות.\nצריכים רק לעשות ולפעול, ומתוך שמחה, ועי\"ז מתבטלים כל הענינים של מצרים וגבולים, כיון ששמחה פורצת גדר<sup data-n=\"416\">29</sup>.\n***<b>ט</b>. האמור<sup data-n=\"417\">30</sup> לעיל שבימינו אלה נקל יותר העסק בעבודת הבירורים – מתבטא גם בכמה הנהגות.\nולדוגמא:\nבדורות שלפנינו לא היו עוסקים בענינים גשמיים קודם התפלה ושיעור לימוד בתורה – מלבד הענינים שמברכים עליהם בברכות השחר, כמו \"מלביש ערומים\", ו\"שעשה לי כל צרכי\", וכיו\"ב, שהם ענינים של לבושים שבדרך מקיף, משא\"כ בנוגע לענינים של מזון שבפנימיות, הנה רק לאחרי התפלה ושיעור לימוד בתורה היו אוכלים פת שחרית.\nאמנם, בדורות האחרונים התירו לשתות קודם התפלה<sup data-n=\"418\">31</sup>, ולאחרונה יותר התירו גם לאכול משהו – מיני מזונות – קודם התפלה<sup data-n=\"419\">32</sup>. וכהפתגם שסיפר כ\"ק מו\"ח אדמו\"ר<sup data-n=\"420\">33</sup> שמוטב לאכול כדי להתפלל מאשר להתפלל כדי לאכול<sup data-n=\"421\">34</sup>.\nוהנה, הטעם בפשטות הוא מצד חלישות בריאות הגוף בדורות האחרונים. אבל בפנימיות וברוחניות הענינים – הטעם הוא מפני שבירור הגשמיות נעשה קל יותר בדורות האחרונים, לפי שבנ\"י עוסקים כל הזמן בבירור הניצוצות, וכבר נתבררו ריבוי ניצוצות, ולכן, גם קודם התפלה יש בכח לברר את הדבר הגשמי, אלא שזהו רק כאשר הדבר נעשה בשביל התפלה.\nומכל זה מובן שבימינו אלה בודאי יש כח לצאת מכל המיצרים והגבולים, ו\"לא נפלאת היא\"<sup data-n=\"422\">35</sup>, צריכים רק לעסוק ולפעול בדבר.\n**********",[["388","1","ר\"ה ז, א."],["389","2","בא יב, ב."],["390","3","ברשימת ההנחה יש שקו\"ט בדברי הרשב\"א בענין זה*, אבל תוכן הדברים אינו ברור (המו\"ל)."],["391","4","ר\"ה בתחילתה."],["392","5","פרש\"י שם."],["393","6","שם ד, א ובפרש\"י.\n*) <i>כנראה הכוונה לחידושי הרשב\"א לר\"ה שם</i>: \"<i>לא ידענא למאי הלכתא</i>.<i> וי\"ל דנפקא מינה לידע החגים שכתוב בהן בראשון</i>,<i> בחדש השלישי</i>,<i> ובחדש השביעי כו'</i>\"."],["394","7","ביצה יז, א."],["395","8","אמור כג, לז."],["396","9","ר\"ה כה, א."],["397","10","לעיל ע' 51 ואילך. וש\"נ."],["398","11","ראה ברכות נז, רע\"א."],["399","12","מלכים-א ח, ב."],["400","13","ראה גם חידושי הריטב\"א לר\"ה ז, א."],["401","14","ישעי' יח, ג."],["402","15","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191165\" data-slug=\"likkutei-sichot\" data-id=\"1300191165\">לקו\"ש חי\"ט ע' 165</a> ואילך. וש\"נ."],["403","16","שבת סז, א. וש\"נ."],["404","17","ראה סה\"מ תש\"ו ע' 30. סה\"מ מלוקט ח\"א ע' רכד. ועוד."],["405","18","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380824\" data-slug=\"likkutei-torah\" data-id=\"4001380824\">לקו\"ת ראה כז, א</a>. ובכ\"מ."],["406","19","נוסח ברכת השחר."],["407","20","יתרו כ, ב."],["408","21","ראה יל\"ש יתרו רמז רפו. ועוד."],["409","22","זח\"ג רנז, סע\"ב. פרדס ש\"א פ\"ט. תניא שעהיוה\"א פ\"ז. ובכ\"מ."],["410","23","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380375\" data-slug=\"likkutei-torah\" data-id=\"4001380375\">לקו\"ת במדבר טז, סע\"ד</a>. ר\"פ ראה. סה\"מ מלוקט ח\"ד ע' מט. ע' רעג. ועוד."],["411","24","כתר שם טוב (הוצאת תשנ\"ט) הוספות סכ\"א. וש\"נ (נעתק ב\"היום יום\" כח שבט)."],["412","25","משפטים כג, ה."],["413","26","מקץ מב, ט. שם, יב. וראה קה\"ר פ\"א, ד."],["414","27","ראה זו\"ח ר\"פ יתרו. ועוד."],["415","28","ראה גם שיחת ש\"פ שמות, מבה\"ח שבט סט\"ו (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011096\" data-slug=\"likkutei-sichot\" data-id=\"1300011096\">לקו\"ש ח\"א ע' 96</a>. לעיל ח\"ז ע' 282 ואילך)."],["416","29","ראה בארוכה סה\"מ תרנ\"ז ס\"ע רכג ואילך."],["417","30","ברשימת ההנחה נזכר שדובר גם בענין \"כי גר היית בארצו\", \"בירא דשתית מיני' לא תשדי בי' קלא\" (ב\"ק צב, ב), שכאשר מקבלים טובה ממישהו צריכים להתחשב בכך, מבלי הבט על מעמדו ומצבו כו' (אבל לא ברור המשך הענין ופרטי הדברים בזה. – המו\"ל)."],["418","31","ראה טושו\"ע (ואדה\"ז) או\"ח ספ\"ט ס\"ג (ס\"ה), ובנ\"כ שם."],["419","32","ראה אגרות-קודש אדמו\"ר מוהריי\"צ ח\"י ע' ב."],["420","33","אגרות-קודש שלו ח\"ד ע' שח (נעתק ב\"היום יום\" יו\"ד שבט)."],["421","34","ראה גם מכתב כ\"ו תמוז שנה זו (אגרות-קודש ח\"ז ע' שכב)."],["422","35","לשון הכתוב – נצבים ל, יא."]]],[1400140010,"– בעת גזיזת השערות (\"אָפּשערעניש\")* –\nבלתי מוגה\nכיבדו את כ\"ק אדמו\"ר שליט\"א ב\"ראשית הגז\"<sup data-n=\"423\">1</sup>, ואח\"כ אמר:\nבעמדנו בסמיכות לחג הפסח, מודגשת ביותר מעלתם של \"עוללים ויונקים\" – \"מפי עוללים ויונקים יסדת עוז\"<sup data-n=\"424\">2</sup> – כמסופר במדרשי חז\"ל<sup data-n=\"425\">3</sup> שבעת קריעת ים סוף \"הם (ה\"עוללים ויונקים\") הכירוהו תחלה\".\n(וסיים כ\"ק אדמו\"ר שליט\"א:) ויה\"ר שכן תהי' לנו בגאולה האמיתית והשלימה ש\"בניסן עתידין להגאל\"<sup data-n=\"426\">4</sup> – ש\"הם\", ה\"עוללים ויונקים\", \"יכירוהו תחלה\".\n**********",[["","","*) אצל בנו של הרה\"ת ר' אברהם מאיר הכהן זרחי."],["423","1","ראה סידור מהרי\"ד ח\"א קסט, ב (הובא באגרות-קודש כ\"ק אדמו\"ר שליט\"א\nח\"ה ע' כב). וראה גם מכתב ו' אייר שנה זו (אגרות-קודש ח\"ז ס\"ע רלה)."],["424","2","תהלים ח, ג."],["425","3","סוטה יא, ב. שמו\"ר פ\"א, יב."],["426","4","ר\"ה יא, רע\"א. שמו\"ר פט\"ו, יא."]]],[1400140011,"ב\"ה, י\"א ניסן, ה'תשי\"ג\nברוקלין, נ.י.\nאל בני ובנות ישראל\nדי בכל אתר ואתר\nה' עליהם יחיו\nשלום רב וברכה!\nימי חג המצות, זכר צאתנו מארץ מצרים, זמן חירותנו, ממשמשים ובאים.\nידוע ענין הזכרון והמדמה והמצייר, אשר פועל הוא בנפש האדם הזוכר ומדמה רגש ומצב רוח דומה, פחות או יותר, למצב רוח בו נמצא, הוא או אדם כדוגמתו, בעת המאורע עצמו. וככל אשר יגדל תוקף כחות נפשו וממשלתם על הגוף, הקשור ואסור בזמן ומקום, כן יתקרב יותר ויותר מצב נפשו בעת הזכרון – להמצב בעת המאורע.\nורוח אייתי רוח ואמשיך רוח, באתערותא דלתתא אתערותא דלעילא, וכדרז\"ל \"והימים האלה נזכרים ונעשים, שבהזכר זכרם למטה נעשים בפועל למעלה\", ובמילא נשפעים גם למטה ומתעוררים כל הענינים הקשורים בימים ההם.\nוזהו אחד הטעמים שנצטווינו לזכור יציאת מצרים בכל דור ודור,בכל יום ויום – לרבות הלילות, לראות עצמו כאלו הוא בעצמו יצא היום ממצרים, יצא לחירות ונפדה,\nכי בכל יום ויום צריכה להיות \"יציאת מצרים\" – יציאת נפש האלקית ממאסר הגוף, יציאה לחירות אמתית.\nואיזוהי חירות אמתית,\nחירות בכל מיני חירות – חירות מן השעבוד, חירות מן היסורים – שעבוד ויסורים גשמיים, שעבוד ויסורים רוחניים.\nעבודה שעל האדם עצמו לעבדה בכל יום ויום היא – יציאת מצרים ברוחניות, יציאה מהמצרים ומההגבלות של הגוף ונפש הבהמית שלו, משעבוד יצרו הרע.\nוכאשר משחרר האדם את עצמו מיצרו הרע –\nבעזר הקב\"ה, הבוחר בישראל עמו והוציאם ממצרים מקום הזוהמא, ועל ידי עסק התורה –\nמשתחרר על ידי זה משעבוד ויסורים רוחניים – המלחמה העצומה של היצרים בנפשו – ומשעבוד ויסורים גשמיים.\nוכמו שנאמר: אם בחוקותי תלכו גו' ונתתי גשמיכם גו' ונתתי שלום בארץ גו' אני הוי' אלקיכם אשר הוצאתי אתכם מארץ מצרים.\nבברכה לחג הפסח כשר ושמח,\nולחירות אמתית במהרה בימינו על ידי גאולתנו האמיתית והשלימה על ידי משיח צדקנו\n<b>מנחם שניאורסאהן</b>",[["","","<i>פחות או יותר</i>: ומתאים להחוזק ועומק הנדרשים בהרגש ומצב רוח הבאים על ידי הזכרון – הוא אופן חיוב הזכרון, אם רק בלב (במחשבה) או גם בפה ובמעשה. – לכמה דעות בזה מחולק ג\"כ חיוב זכרון יציאת מצרים בכל השנה, אשר דיו במחשבה, משא\"כ בליל פסח (ראה שאגת ארי' סו\"ס יג. מנחת חנוך מ' כא. שד\"ח כללים ז, יג. ואכ\"מ).\n<i>ורוח </i>. .<i> רוח</i>: זהר ח\"ב קסב, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370176\" data-slug=\"torah-or\" data-id=\"3901370176\">תורה אור לח, ד</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670134\" data-slug=\"or-hatorah-hb\" data-id=\"8158670134\">אוה\"ת [חנוכה] רפו, א</a>.\n<i>וכדרז\"ל</i>: הרמ\"ז בס' תקון שובבים הובא בספר לב דוד פכ\"ט. – והזמן מצד עצמו מסוגל לזה, וכמו שהאריך בלב דוד שם. וידועה ג\"כ הראי' ממשנה ספ\"ג דגטין: בודקין את היין כו' ובהוצאת סמדר כו'.\nנדפסה באגרות-קודש כ\"ק אדמו\"ר שליט\"א ח\"ז אגרת ב'סז. הגש\"פ עם לקוטי טעמים מנהגים וביאורים (קה\"ת תשמ\"ז) ע' תקעג.<i>לראות עצמו </i>. .<i> ממאסר הגוף</i>: רמב\"ם הל' חמץ ומצה פ\"ז ה\"ו. <a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא</a> פמ\"ז.\n<i>חירות </i>. .<i> מן היסורים</i>: זהר ח\"ב קיד, א. עירובין נד, א. שמ\"ר פמ\"א, ז.\n<i>יציאת מצרים ברוחניות</i>: ראה ד\"ה בכל דור – לכ\"ק מו\"ח אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע – (ס' המאמרים – אידית).\n<i>בעזר הקב\"ה </i>. .<i> עסק התורה</i>: סוכה נב, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא</a> פמ\"ו. קדושין ל, ב."]]],[1400140012,"<h3>לשלוח לאנ\"ש שי' בכל מרחבי תבל</h3><h3>לקראת חג הפסח, ה'תשי\"ג</h3>\nחג כשר ושמח וחירות אמיתית בגו\"ר.\n<b>מנחם שניאורסאהן</b>"],[1400140013,"בלתי מוגה\n<b>א</b>. איתא בסידור האריז\"ל<sup data-n=\"427\">1</sup> אודות השמחה דליל פסח (בארץ ישראל – בלילה הראשון, ובחוץ לארץ – בשני הלילות), \"שאין זמן שמחה כ\"כ שמחת השכינה כמו בליל פסח\".\nולכן, תובעים מיהודי – שצריך להיות בדוגמא שלמעלה – שיהי' בשמחה בעת עריכת הסדר, שעי\"ז פועל השמחה למעלה, ושתומשך גם למטה.\n– בסידור האריז\"ל שם מבואר גם הטעם לגודל השמחה בליל פסח שאין דוגמתה בכל השנה כולה, אבל הטעם אינו נוגע. נוגע רק לידע שכן הוא הענין, שצריכים להיות בשמחה.\n(וסיים כ\"ק אדמו\"ר שליט\"א:) \"זאָגט אַ פריילעכן ניגון\". תבחרו איזה ניגון שתרצו, העיקר, שיהי' ניגון שמח.\n[ניגנו ניגון שמח, וכ\"ק אדמו\"ר שליט\"א רמז שירקדו, וגם עמד מלא קומתו ורקד על מקומו בשמחה גדולה].\n***\n<b>ב</b>. \"<i>הא לחמא עניא</i>\":\nצריך לומר \"הֵא (לחמא עניא)\", בצירי<sup data-n=\"428\">2</sup>, שזהו כנגד מה שאמר יוסף הצדיק במצרים: \"הא לכם זרע\"<sup data-n=\"429\">3</sup>.\nוהענין בזה<sup data-n=\"430\">4</sup> – כידוע שבחינתו של יוסף היא יסוד, שממנו נמשכת ההשפעה כו'. וכשאמר יוסף למצרים \"הא לכם זרע\", נעשה אחיזה למצרים ביסוד דלעו\"ז, שמזה נעשה הענין דח\"נ, שהוא חטא חמור ביותר, ועד שאיתא בספרים<sup data-n=\"431\">5</sup> (שהובאו בתורת החסידות) שחטא זה הוא הסיבה לאריכות הגלות. וכדי לתקן מה שאמר יוסף למצרים \"הא לכם זרע\" – אומרים בליל פסח \"הא לחמא עניא די אכלו אבהתנא בארעא דמצרים\".ומזה רואים גודל העילוי שבליל הפסח, אשר, מבלי הבט על המעמד ומצב בענין הנ\"ל – שכן, גם מי שהוא נקי מח\"נ החמורים<sup data-n=\"432\">6</sup>, אלא שלא קידש עצמו בשעת תשמיש כו', הרי ע\"פ מ\"ש בכתבי-יד של ספר התניא<sup data-n=\"433\">7</sup> נכלל גם ענין זה בחטא הנ\"ל, וכל-שכן מי שאינו נקי כו', ש\"חמור . . וגדול עוונו בבחי' הגדלות ורבוי הטומאה והקליפות . . שכחותי' וחילותי' מלבישים כו'\"<sup data-n=\"434\">8</sup>, שלכן, במשך כל השנה כולה קשה לתקן ענין הנ\"ל – הרי מצד גודל העילוי דליל הפסח<sup data-n=\"435\">9</sup>, הנה ע\"י אמירת \"הא לחמא עניא\", יכול יהודי לתקן לא רק את הענינים שעשה וגרם <i>הוא</i> <i>בעצמו</i>, אלא גם את הענינים שנעשו ונגרמו מצד אמירתו של יוסף \"הא לכם זרע\".\n<b>ג</b>. וזהו הטעם לאמירת \"הא לחמא עניא\" בליל הפסח בתחילת הסדר:\nענינו של חג הפסח הו\"ע הגאולה. ועל זה אמרו רז\"ל<sup data-n=\"436\">10</sup> \"בכל דור ודור (ובכל יום ויום<sup data-n=\"437\">11</sup>) חייב אדם לראות את עצמו כאילו הוא יצא (היום<sup data-n=\"437\">11</sup>) ממצרים\", היינו, שאצל כל אדם ישנו ענין של \"מצרים\" שצריך לצאת ממנו, שזהו\"ע הגאולה הפרטית ע\"י משיח הפרטי (כמבואר באגה\"ק<sup data-n=\"438\">12</sup>), אשר על ידה באים להגאולה הכללית.\nולכן, בליל הפסח, בתחילת עריכת הסדר, עוד לפני אמירת סדר הגדה ממשנה וגמרא – מקדימים לומר \"הא לחמא עניא\", כדי לתקן חטא הנ\"ל שהוא סיבת אריכות הגלות (כנ\"ל ס\"ב), ובמילא, ע\"י תיקונו באה הגאולה.\nוזהו שמסיימים בפיסקא זו \"השתא הכא כו' בני חורין\" – שעם היות ש\"השתא הכא\", שיודעים המעמד ומצב כו', ובמילא יודעים ש\"השתא עבדין\", מ\"מ, ע\"י אמירת \"הא לחמא עניא\" פועלים שנהי' \"לשנה הבאה בני חורין\" – כפירוש כ\"ק מו\"ח אדמו\"ר<sup data-n=\"439\">13</sup> שאין צורך להמתין עד לשנה הבאה, אלא שנעשים בני חורין <i>תיכף ומיד</i>, ובמילא נהי' \"לשנה הבאה בני חורין\".\n*<b>ד</b>. \"<i>וכל המרבה לספר ביציאת מצרים הרי זה משובח</i>\":\nידוע דיוק המפרשים<sup data-n=\"440\">14</sup> במ\"ש \"ו<i>כל</i> המרבה לספר כו'\", ולא \"והמרבה לספר כו'\" – הרי כבר אמר לפנ\"ז \"כולנו חכמים כולנו נבונים כולנו יודעים את התורה\", שבזה כולל את כל הסוגים שמצוה עליהם לספר ביציאת מצרים, ומה בא להרבות עוד באמרו \"ו<i>כל</i> המרבה לספר כו'\"?\nוהביאור בזה – שבאמרו \"ו<i>כל</i> המרבה לספר כו'\" בא לרבות עוד סוג – אלה שלא היו בשעבוד מצרים (כדלקמן), שגם הם צריכים לספר ביציאת מצרים, ויתירה מזה, להרבות בסיפור יציאת מצרים.\nכלומר: בתחילה מבאר שלא מספיקה הידיעה ד\"כולנו חכמים כו' כולנו יודעים כו'\", אלא \"מצוה עלינו <i>לספר</i> ביציאת מצרים\", <i>בדיבור</i> דוקא, ולכמה דעות<sup data-n=\"441\">15</sup> צריך להיות הסיפור לזולת (בן או אחר) דוקא. אמנם, כל זה הוא בנוגע לאלה שהיו בשעבוד מצרים, אבל אלה שמעולם לא היו בשעבוד מצרים, יש מקום לומר שאינם שייכים להמצוה דסיפור ביציאת מצרים. ועל זה מוסיף תיבת \"ו<i>כל</i>\", לרבות את אלה שלא היו בשעבוד מצרים, שגם הם בכלל החיוב לספר ביציאת מצרים, ובאופן ד\"המרבה לספר ביציאת מצרים\".\nמי הם אלה שלא היו בשעבוד מצרים? – הרי הם כהנים ולוים, כמסופר במדרשי חז\"ל<sup data-n=\"442\">16</sup> שמשה ואהרן וכל שבט לוי לא היו במלאכת שעבוד מצרים [לפי שמלכתחילה לא נתפתו לדברי פרעה שמשך את בני ישראל בדברים לעשות מלאכתו, ועד שנטל בעצמו סל ומגרפה לעשות לבנים כו'<sup data-n=\"443\">17</sup>], ואותם בא לרבות באמרו \"ו<i>כל</i> המרבה לספר ביציאת מצרים\".\n<b>ה</b>. וזהו המשך הפיסקא שלאח\"ז – \"מעשה ברבי אליעזר ורבי יהושע ורבי אלעזר בן עזרי' ורבי עקיבא וכו'\" – שמכאן ראי' שגם כהנים ולוים שלא היו בשעבוד מצרים חייבים להרבות בסיפור יצי\"מ:\nבנוגע לרבי אליעזר – סתם ר\"א שהוא רבי אליעזר בן הורקנוס<sup data-n=\"444\">18</sup>, הנקרא ר\"א הגדול – אף שמצינו במדרז\"ל<sup data-n=\"445\">19</sup> ש\"בשעה שעלה משהלמרום שמע קולו של הקב\"ה שיושב ועוסק בפרשת פרה אדומה ואומר הלכה בשם אומרה, ר' אליעזר אומר עגלה בת שנתה ופרה בת שתים<sup data-n=\"446\">20</sup>, אמר לפניו, רבון העולמים, יהי רצון שיהא מחלצי, אמר לו חייך <i>שהוא מחלציך</i>\", ומהראוי לומר כפשטי' שהי' לוי, מ\"מ, יש גם דעה<sup data-n=\"447\">21</sup> שהי' מחלציו של משה – מבני בנותיו.\nאמנם, רבי יהושע – הי' לוי, כפי שמצינו להדיא שהי' מן המשוררים<sup data-n=\"448\">22</sup>, ונתנו לו מעשר<sup data-n=\"449\">23</sup>.\nורבי אלעזר בן עזרי' – הי' כהן מיוחס, \"עשירי לעזרא\", שלכן מינוהו לנשיא<sup data-n=\"450\">24</sup>.\nורבי עקיבא – הי' בן גרים<sup data-n=\"451\">25</sup>.\nוזהו המשך הפיסקא \"מעשה ברבי אליעזר וכו'\" ל\"<i>כל</i> המרבה לספר ביציאת מצרים כו'\" – שגם כהנים ולוים שלא נשתעבדו (וכן גרים) היו מרבים בסיפור יציאת מצרים.\n<b>ו</b>. וההוראה מזה בנוגע אלינו:\nכיון שכל בני ישראל הם \"בנים למקום\", יש אצל כאו\"א מישראל מעלה מיוחדת, שמצד מעלה זו הרי הוא למעלה מכללות הענין דגלות ושעבוד מצרים. ובמילא, יכול הוא לחשוב שאינו צריך לספר ביציאת מצרים, כיון שאין אצלו כלל הענין דמצרים.\nועל זה אומרים \"<i>כל</i> המרבה לספר ביציאת מצרים כו'\" – שגם מי שלא הי' בשעבוד מצרים, צריך לספר ביציאת מצרים להזולת, ולהרבות בסיפור יצי\"מ עד כדי כך שיפעל אצל הזולת ענין של יציאת מצרים.\nוהענין בזה – ש\"כל ישראל ערבים זה בזה\"<sup data-n=\"452\">26</sup>, וכהפירוש<sup data-n=\"453\">27</sup> (שהזכיר כ\"ק מו\"ח אדמו\"ר כמ\"פ<sup data-n=\"454\">28</sup>) ש\"ערבים\" הוא גם מלשון עירוב, שמעורבים זב\"ז, ולכן, כל זמן שלא פעל ענין של יציאת מצרים אצלהזולת, נמצא גם הוא בגלות מצרים (וכפי שמצינו בגמרא<sup data-n=\"455\">29</sup> בנוגע לגדולי ישראל, שהי' <i>נוגע להם</i> שבשכנותם דרו אנשי דלא מעלי כו').\n<b>ז</b>. והמשך וסיום הפיסקא – ש\"היו מספרים ביציאת מצרים כל אותו הלילה עד שבאו תלמידיהם<sup data-n=\"456\">30</sup> ואמרו להם רבותינו הגיע זמן קריאת שמע של שחרית\" – שר\"א ור\"י כו' הרבו כל כך לספר ביציאת מצרים עד שפעלו על תלמידיהם שהגיע אצלם זמן ק\"ש של שחרית, היינו, שנעשה אצלם מעמד ומצב של אור.\nכלומר: לא מספיק ש\"רבותינו\" בעצמם יאמרו \"הגיע זמן ק\"ש של שחרית\", שהרי אצלם לא הי' כלל מעמד ומצב של חושך. אלא הכוונה היא שיפעלו גם על \"תלמידיהם\" – שקודם שנעשו תלמידיהם, או גם בתחילת לימודם, הי' אצלם מעמד ומצב של חושך [דאף שנאמר \"<i>אותו</i> הלילה\" לשון זכר, שזוהי מדריגה נעלית יותר<sup data-n=\"457\">31</sup>, הרי זה בכל זאת \"לילה\", חושך], ואעפ\"כ יאמרו – התלמידים בעצמם – \"הגיע זמן ק\"ש של שחרית\".\nוזהו ש\"באו תלמידיהם ואמרו להם רבותינו הגיע זמן קריאת שמע של שחרית\": בהענין דמס\"נ (ק\"ש) הנכם \"רבותינו\", כיון שכל ההשפעה באה על ידכם, אבל אעפ\"כ, ישנו גם הענין ד\"מתלמידי יותר מכולם\"<sup data-n=\"458\">32</sup>, וכבנדו\"ד, שהענין ד\"לספר ביציאת מצרים\" נשלם דוקא ע\"י פעולת הסיפור להתלמידים. ובכן, מודיעים אנו לכם, \"רבותינו, הגיע זמן ק\"ש של שחרית\", כלומר, גם אנו יצאנו כבר מאפילה לאור גדול.\n*\n<b>ח</b>. \"<i>כל ימי חייך להביא לימות המשיח</i>\":\nכיון שלימות המשיח יקויים היעוד<sup data-n=\"459\">33</sup> \"את רוח הטומאה אעביר מן הארץ\", יש מקום לחשוב שאז לא יהי' כללות הענין דפסח ויציאת מצרים.\nוע\"ד ההפרש שבין פסח לשבועות, שבפסח אסור לגמרי המין שהוא ההיפך דמצה, ואלו בשבועות מקריבים שתי הלחם ממין זה דוקא, ומבואר בזהר<sup data-n=\"460\">34</sup> ע\"פ משל מבן מלך שנחלש והוצרך לאכול לרפואתו מאכל מסויים ולהזהר משאר המאכלים, ולאחרי שהבריא הותר לו לאכולכל המאכלים. ודוגמתו בנמשל, שבחג הפסח, שזה עתה יצאו בני ישראל ממצרים, הוצרכו להזהר מדבר שהוא ההיפך דמצה, משא\"כ בשבועות, שקיבלו התורה, שוב אין צורך בזהירות זו.\nולכן יש צורך בלימוד מיוחד – \"כל ימי חייך להביא לימות המשיח\" – שגם לימות המשיח יזכירו הענין דיציאת מצרים.\n[ולהעיר מדברי הרשב\"א<sup data-n=\"461\">35</sup> ש\"גם לדברי חכמים שאומרים שאין מזכירין יציאת מצרים לימות המשיח, לא יתבטלו מצות הפסח והמצות ומניעת החמץ\"].\nוטעם הדבר<sup data-n=\"462\">36</sup> – לפי שהגאולה ממצרים היתה הגאולה הראשונה, והיא מביאה גם את הגאולה העתידה, שהרי לולי הגאולה ממצרים לא היתה יכולה לבוא הגאולה העתידה, וגם כל עניני העליות שיהיו לעתיד לבוא בכל שעה ושעה, יהיו ע\"י יציאת מצרים.\nוכדאיתא בגמרא<sup data-n=\"463\">37</sup> שאע\"פ ש\"כבר נאמר<sup data-n=\"464\">38</sup> הנה ימים באים נאום ה' ולא יאמרו עוד חי ה' אשר העלה את בני ישראל מארץ מצרים כי אם חי ה' אשר העלה גו' מכל הארצות וגו'\" – הרי הפירוש בזה הוא – \"לא שתעקר יציאת מצרים ממקומה, אלא שתהא שעבוד גליות עיקר ויציאת מצרים טפל לו\", והיינו, שגם לעתיד לבוא יהי' נוגע הענין דיציאת מצרים.\nומקרא מלא דיבר הכתוב<sup data-n=\"465\">39</sup> \"כימי צאתך מארץ מצרים אראנו נפלאות\", היינו, שדוקא ע\"י יציאת מצרים יהיו כל ה\"נפלאות\" בגאולה העתידה<sup data-n=\"462\">36</sup>.\n[כ\"ק אדמו\"ר שליט\"א צוה לנגן \"אני מאמין\"].\n***\n<b>ט</b>. \"<i>כנגד ארבעה בנים דברה תורה</i>. אחד חכם, ואחד רשע, ואחד תם, ואחד שאינו יודע לשאול\"<sup data-n=\"466\">40</sup>:\nהפירוש הפשוט הוא שד' הפסוקים שמצינו בתורה בנוגע לאופן ההגדה לבנים, הם ביחס לארבעה סוגי בנים, היינו, שלכל סוג צריכה להיות ההגדה בלשון המתאים לו.אמנם, כיון שכל התורה היא לכל בני ישראל, \"תורה אחת לכולנו\"<sup data-n=\"467\">41</sup> – צריך לומר, שכל ד' הלשונות שבד' הפסוקים שכנגד הארבעה בנים שייכים לכאו\"א מישראל, כיון שגם אצלו ישנם כל פרטי המדריגות דהארבעה בנים.\nוע\"ד שמצינו<sup data-n=\"468\">42</sup> שכאו\"א מישראל צריך לקיים את כל המצוות שבתורה, חוץ ממצוות המלך, שלהיותו נשמה כללית מוציאם ידי חובתם. ועד\"ז יש לומר, שכאו\"א מישראל מחוייב בכל ד' הלשונות שבהם דברה תורה, וגם אם אין לו בנים מחוייב הוא בכל ד' לשונות אלה, כיון שאצלו גופא ישנם כל פרטי המדריגות דחכם רשע תם ושאינו יודע לשאול.\n<b>י</b>. והביאור בזה:\nמדריגת \"חכם\" שבכאו\"א מישראל ענינה שיהודי אינו רוצה ואינו יכול להיות נפרד מאלקות<sup data-n=\"469\">43</sup>, שזהו מפני היותו \"חכם\" – \"איזהו חכם הרואה את הנולד\"<sup data-n=\"470\">44</sup>, \"שרואה כל דבר איך נולד ונתהוה מאין ליש כו'\"<sup data-n=\"471\">45</sup>, ע\"י כח הפועל שבנפעל. ובפרט ע\"פ מ\"ש אדה\"ז בתניא<sup data-n=\"472\">46</sup> \"שמעתי ממורי כו'\" שמדרגת החכמה ענינה ההרגש \"שהוא לבדו הוא ואין זולתו\".\nוכמו כן ישנם בכאו\"א מישראל גם פרטי המדריגות ד\"תם\" ו\"שאינו יודע לשאול\", ואפילו המדריגה ד\"רשע\" – כמובן ממ\"ש אדמו\"ר האמצעי בתורת חיים<sup data-n=\"473\">47</sup> שאפילו בצדיק גמור ישנה (לא רק המדריגה ד\"אמה העברי'\" ו\"עבד עברי\", אלא) גם המדריגה ד\"עבד כנעני\", ש\"בהפקירא ניחא לי'\"<sup data-n=\"474\">48</sup>, ועבודתו אינה אלא מצד אימת האדון שלא יכהו בשבט כו', ודוגמתו בעבודה הרוחנית הוא הארת המקיף דחי' ויחידה, שהוא כמו הכאת השבט של האדון.\nוממשיך לבאר, שזהו מ\"ש הרמב\"ם<sup data-n=\"475\">49</sup> שאפילו צדיק גמור שמואס ברע, הנה באותו רע שאין הטבעיות מחמדתו, \"לא יאמר אדם אי אפשי כו', אלא אפשי ומה אעשה ואבי שבשמים גזר עלי\"<sup data-n=\"476\">50</sup> – דלכאורה אינו מובן: כיון שהצדיק מואס ברע, איך יכול לומר \"אפשי\"? – כי, זה גופאשמואס ברע הוא מפני ש\"אבי שבשמים גזר עלי\", אבל מצד הגוף הרי הוא במעמד ומצב ש\"אפשי\". וזהו גם ענין \"עבדא בהפקירא ניחא לי'\" – שעבודתו היא מצד אימת האדון, הארת המקיף דהנשמה כו', אבל מצד הגוף, \"בהפקירא ניחא לי'\".\nולהעיר גם מהסיפור<sup data-n=\"477\">51</sup> שכאשר תלמידי הבעש\"ט הרהרו כו', הראו להם מלמעלה שמשה רבינו מסביר מ\"ש<sup data-n=\"478\">52</sup> \"ויפול אברהם על פניו ויצחק ויאמר בלבו וגו'\" (דלכאורה \"איך אפשר הדבר אשר אברהם אבינו יהי' מסתפק במאמר השם\"), ש\"זהו מצד הגוף, ואשר גם גוף קדוש בשר הוא\".\n<b>יא</b>. עפ\"ז יש לבאר גם את הסמיכות ד\"חכם\" ל\"רשע\" – \"אחד חכם ואחד רשע\":\nלכאורה, מצד סדר השתלשלות המדריגות צ\"ל מקומו של ה\"רשע\" בסוף, ובפרט ע\"פ הידוע<sup data-n=\"479\">53</sup> שד' הבנים הם כנגד ד' עולמות אבי\"ע, חכם כנגד אצילות ורשע כנגד עשי', ומדוע מסמיכים את ה\"רשע\" אצל ה\"חכם\"?\nוהביאור בזה – שכשם שאצל ה\"חכם\" יש גם מדריגת \"רשע\" (כנ\"ל), כך גם אצל ה\"רשע\" יש מדריגת \"חכם\" שפועלת בו, כאמור לעיל שמדריגת \"חכם\" ענינה שכאו\"א מישראל אינו רוצה ואינו יכול להיות נפרד מאלקות, ולכן סומכים ה\"רשע\" לה\"חכם\", להורות שגם אצל ה\"רשע\" ישנה ופועלת מדריגת ה\"חכם\".\n<b>יב</b>. ועפ\"ז יובן גם סיום הפיסקא ד\"רשע\" – \"ואמור לו בעבור זה עשה ה' לי בצאתי ממצרים, לי ולא לו, אילו הי' שם לא הי' נגאל\":\nלכאורה אינו מובן: כיון ש\"אילו הי' שם לא הי' נגאל\", היינו, שאין לו שייכות לכללות הענין דיציאת מצרים – לשם מה מדברים אודותיו בעת ה\"סדר\"?\nולא עוד אלא שמדגישים \"<i>ואמור לו</i> . . אילו הי' שם לא הי' נגאל\" – לשם מה צריכים להכנס עמו בדברים; צריכים לעשות מה שכתוב לפני ה\"אמור לו\" (\"הקהה את שיניו\")... ולא לדבר עמו כלל, כיון שאין לו שייכות לכללות הענין דיציאת מצרים?!אך הפירוש הוא: \"אילו הי' שם – במצרים, היינו, לפני מתן-תורה – לא הי' נגאל\", משא\"כ עתה, לאחר מ\"ת, מוכרח כאו\"א מישראל להגאל, דכיון שבמ\"ת אמר הקב\"ה לכאו\"א מישראל – בלשון יחיד<sup data-n=\"480\">54</sup> – \"אנכי הוי' אלקיך\"<sup data-n=\"481\">55</sup>, ועי\"ז נעשה אצל כאו\"א מישראל \"הוי' אלקיך\". וכידוע<sup data-n=\"482\">56</sup> ש\"ישראל\" ר\"ת \"<i>י</i>ש <i>ש</i>שים <i>ר</i>יבוא <i>א</i>ותיות <i>ל</i>תורה\", וכשם שכשרות הספר-תורה תלוי' בשלימות כל האותיות שבה, ואם חסרה אות אחת בלבד, איזה שתהי', אזי כל הס\"ת אינה כשרה<sup data-n=\"483\">57</sup>, כך גם כאו\"א מישראל, יהי' מי שיהי', נוגע לכללות הכוונה העליונה, ובמילא, מוכרח גם הוא להגאל.\nוזהו שגם ה\"רשע\" שייך לעריכת הסדר, כיון שעכשיו צריך גם הוא להגאל;\nוהפירוש ד\"אמור לו . . אילו הי' שם לא הי' נגאל\", הוא, שאופן קירוב הרשע הוא עי\"ז שמראים לו את <i>הנועם של התורה</i>, אשר, אע\"פ שמצד מעמדו ומצבו, לולי מ\"ת, \"אילו הי' שם לא הי' נגאל\", מ\"מ, מצד <i>מתן-תורה</i> יכול וצריך גם הוא להגאל.\n*\n<b>יג</b>. \"<i>מתחלה עובדי עבודה זרה היו אבותינו ועכשיו קרבנו המקום לעבודתו</i>, שנאמר<sup data-n=\"484\">58</sup> ויאמר יהושע גו' תרח אבי אברהם וגו'\":\nצריך להבין מ\"ש גבי תרח \"אבי אברהם\" (בה\"א), ולא \"אבי אברם\" – הרי מצד <i>התולדה</i>, כפי שנולד מתרח אביו, נקרא \"אברם\", ואילו הוספת האות ה\"א (אבר<i>ה</i>ם) באה על ידי <i>שלימות עבודתו</i> של אברהם על ידי המילה, שאז \"המליכו (השליטו) הקב\"ה על מאתיים וארבעים ושמונה אברים\" (גם על ה' האברים שע\"פ טבע אינם ברשותו של אדם לשלוט עליהם)<sup data-n=\"485\">59</sup>, ומה שייך ענין זה לתרח שיקרא \"אבי אבר<i>ה</i>ם\"?\nליתר ביאור:\nלא זו בלבד שהה\"א דאבר<i>ה</i>ם אינה מצד תולדתו מתרח אביו, כי אם ע\"י עבודתו, אלא עוד זאת, שענינו של תרח הוא <i>ההיפך</i> מעבודתו של אברהם – שהרי באברהם כתיב<sup data-n=\"486\">60</sup> \"ויקרא שם אברם בשם ה' א-לעולם\", \"א\"ת ויקרא אלא ויקרא, מלמד שהקריא אברהם אבינו לשמו של הקב\"ה בפה כל עובר ושב\"<sup data-n=\"487\">61</sup>, ואילו תרח הי' עובד ע\"ז, ופעל גם על אחרים לעבוד ע\"ז.\nולא זו בלבד שענינו של תרח מצד עצמו הוא ההיפך מעבודתו של אברהם, אלא עוד זאת, שתרח הי' <i>מנגד</i> לאברהם, <i>והפריע</i> לעבודתו של אברהם שעל ידה ניתוספה לו האות ה\"א.\nועפ\"ז יפלא ביותר מ\"ש \"תרח אבי אברהם\"?!\nאך הענין הוא – שכאשר ישנו ענין ההתקשרות של שני אנשים, כמו ההתקשרות של אב ובן וכיו\"ב, אזי ההתקשרות היא <i>בכל הענינים</i>, כך, שההתקשרות של תרח היא לא רק עם \"אברם\", אלא גם עם \"אברהם\", כמו שהוא במדריגתו הנעלית בתוספת ה\"א.\n<b>יד</b>. ומזה למדים הוראה בעבודתנו:\nכאשר חסיד עושה חשבון – אליבא דנפשי' – במה מתבטאת השייכות וההתקשרות שלו אל הרבי, יודע הוא שאין לו שום ציור בגודל ההפלאה של הרבי, ולאידך יודע הוא היטב פחיתותו כו'.\nונוסף על עצם ריחוק הערך בין החסיד לרבי, הרי גם ההתקשרות של החסיד אל הרבי – שנותן \"מעמד\", לפעמים מציית אל הרבי ומקיים רצונו, שומע מאמר ולומדו ומבינו – אינה אלא בענינים החיצוניים של הרבי, ועוד והוא העיקר, שההתקשרות מצדו היא התקשרות חיצונית בלבד, שלכן, \"התעיף<sup data-n=\"488\">62</sup> עיניך בו ואיננו\"...\nואעפ\"כ, צריך לידע שבכל מעמד ומצב איזה שיהי' מקושר הוא אל הרבי. \"עס איז פאַרפאַלן\"... כיון שהתקשר אל הרבי פעם אחת, נשאר הוא מקושר אל הרבי בכל המצבים שיהי' בהם, וע\"ד האמור בענין \"תרח אבי אברהם\", שזוהי התקשרות של אב ובן, ועאכו\"כ בנוגע להתקשרות של רבי וחסיד, שהיא באופן נעלה יותר מאור ומאור, אב ובן, עצם והתפשטות וכו', וכוללת את כולם<sup data-n=\"489\">63</sup>.\n*\n<b>טו</b>. \"<i>והיא שעמדה</i>\":\nבתיבת \"והיא\" – ישנם ב' פירושים:א) הפירוש הפשוט<sup data-n=\"490\">64</sup> – \"והיא\" קאי על <i>ההבטחה</i> שהבטיח הקב\"ה לאברהם ולנביאים, שעז\"נ בפיסקא שלפנ\"ז \"ברוך שומר הבטחתו לישראל\", שהבטחה זו \"היא שעמדה לאבותינו ולנו\", שאע\"פ ש\"בכל דור ודור עומדים עלינו לכלותינו\", מ\"מ, \"הקב\"ה מצילנו מידם\".\nב) והפירוש הפנימי – \"והיא\" קאי על <i>השכינה</i>, כמארז\"ל<sup data-n=\"491\">65</sup> \"גלו למצרים שכינה עמהם . . גלו לבבל שכינה עמהם . . ואף כשהן עתידין ליגאל שכינה עמהם\", והשכינה, \"היא שעמדה לאבותינו ולנו\", שאע\"פ ש\"בכל דור ודור עומדים עלינו לכלותינו\", מ\"מ, \"הקב\"ה מצילנו מידם\".\nויש לבאר הקשר והשייכות של ב' הפירושים – כבכל עניני התורה שיש בהם ב' פירושים, ע\"פ נגלה דתורה וע\"פ פנימיות התורה, שמתאימים ושייכים זל\"ז<sup data-n=\"492\">66</sup>.\nובהקדם מ\"ש<sup data-n=\"493\">67</sup> \"דבר מלך שלטון\", ו\"דיבורו של הקב\"ה חשיב מעשה\"<sup data-n=\"494\">68</sup> – שזהו הטעם ש\"בעשרה מאמרות נברא העולם\"<sup data-n=\"495\">69</sup>, כי, עם היותם \"מאמרות\" (דיבור) בלבד, הרי זה חשיב מעשה.\nועפ\"ז מובן גם בנוגע להבטחתו של הקב\"ה \"אנכי ארד עמך מצרימה ואנכי אעלך גם עלה\"<sup data-n=\"496\">70</sup> – שע\"י דיבורו של הקב\"ה, \"אנכי ארד עמך\", ש\"חשיב מעשה\", נעשה כן בפועל, ש\"בכל מקום שגלו שכינה עמהם\".\nונמצא, שההבטחה לישראל (כפירוש הפשוט), ו\"שכינה עמהם\" (כהפירוש הפנימי), ענינם אחד שנחלק לחיצוניות ופנימיות: ההבטחה – הדיבור – היא החיצוניות, והפעולה ד\"שכינה עמהם\" שנעשית ע\"י ההבטחה – כיון שדיבורו חשיב מעשה – היא הפנימיות.\n*\n<b>טז</b>. \"<i>ואת עמלנו אלו הבנים</i>, שנאמר<sup data-n=\"497\">71</sup> כל הבן הילוד היאורה תשליכוהו וכל הבת תחיון\":\nהראי' מהפסוק \"כל הבן הילוד גו'\" היא (לא על הפירוש ש\"עמלנואלו הבנים\", שהרי בפסוק לא נזכר תיבת \"עמל\", אלא) על הענין, שגזרו על הבנים<sup data-n=\"498\">72</sup>.\nאבל על הפירוש ש\"עמלנו אלו הבנים\" אינו מביא ראי' – כיון שזהו דבר הפשוט שבנוגע ל\"בנים\" צריך להיות \"עמל\" דוקא.\nומזה מובן גם בנוגע לתלמידים, כדרשת חז\"ל<sup data-n=\"499\">73</sup> \"ושננתם לבניך אלו התלמידים\", שצריך להתעסק עמהם באופן של עמל ויגיעה (\"עמלנו\"), היינו, שלא מספיק ללמוד עמהם במשך מספר השעות שצריך ללמדם, ואח\"כ יכול לנוח ולילך לישון, אלא עליו להמשיך לעמול ולהתייגע ולהיות מונח בהתלמידים בכל מציאותו.\nאם רצונו להיות \"משפיע\" – צריך להיות אצלו עמל ויגיעה. ואם טוען: נוּ, אזי לא אהי' \"משפיע\" – עליו לדעת שכיון שזהו ציווי של הרבי, הרי זה ענינו, שעליו להיות רב ומשפיע, ובמילא, צריך לעמול ולהתייגע עם התלמידים, ואז יהי' אצלו הענין ד\"בניך אלו התלמידים\", וגם \"בניך\" כפשוטו, זרעא חיא וקיימא.\n*\n<b>יז</b>. (בנוגע להפיסקא \"דיינו\" – אמר כ\"ק אדמו\"ר שליט\"א:)\nהתוועדות זו – בליל ב' דפסח – היא על יסוד הנהגתו של כ\"ק מו\"ח אדמו\"ר שהי' מבאר עניני ההגדה<sup data-n=\"500\">74</sup>.\n– כ\"ק אדמו\"ר הצ\"צ אמר פעם<sup data-n=\"501\">75</sup> במענה לשאלת אחד הרבנים (\"אַ עולם'שער\") ע\"ד פעולותיו בעסקנות ציבורית עד כדי מס\"נ (כידוע<sup data-n=\"502\">76</sup> שישב במאסר כ\"ב פעמים כו'), איך הי' מותר לו להעמיד את עצמו בסכנה, הרי הי' צריך לחשוב מה יהי' עם החסידים? – שכיון ששאל ע\"ד הנגלה (\"אַ נגלה'דיקע שאלה\"), ישיב לו ע\"ד הנגלה (\"אַ נגלה'דיקן תירוץ\"), תירוץ עם \"ואי בעית אימא\": התירוץ – שישנם הבנים, וה\"אי בעית אימא\" – שהאחדות של חסידים תנהיג אותם עד ביאת המשיח. ובכן, על יסוד התירוץ והאב\"א הנ\"ל, ממשיכים בהסדר שהי' כ\"ק מו\"ח אדמו\"ר נוהג לבאר עניני ההגדה, וזהו הטעם לעריכת התוועדות בליל ב' דפסח.וכיון שבאמירת ה\"דיינו\" [בכתבי האריז\"ל איתא שישנם <i>ט\"ו</i> דיינו, אבל לפי הנוסחא שלנו אינם אלא <i>י\"ד</i><sup data-n=\"503\">77</sup>] לא היו מפסיקים<sup data-n=\"504\">78</sup>, אלא היו אומרים את כולם בחדא מחתא – לכן, לא ידובר אודות ה\"דיינו\".\n*\n<b>יח</b>. \"<i>על אחת כמה וכמה טובה כפולה ומכופלת למקום עלינו כו' ובנה לנו את בית הבחירה כו'</i>\":\nבפיסקא זו צריך להבין: (א) מהו הדיוק שהקב\"ה נקרא כאן בשם \"מקום\"? (ב) הרי גם לאחרי בנין בית הבחירה היו עוד כמה מעלות טובות, ולמה מסיים בהענין ד\"בנה לנו את בית הבחירה\"?\nוהענין בזה:\nהטעם שהקב\"ה נקרא בשם \"מקום\" – לפי ש\"הוא מקומו של עולם\"<sup data-n=\"505\">79</sup>, דקאי בכללות על אור הממלא ששייך להתהוות. אמנם, ידוע שההתהוות היא בכח העצמות דוקא<sup data-n=\"506\">80</sup>, וכוונת ההתהוות היא להיות גילוי העצמות למטה. וכוונה זו נשלמת ע\"י נשמות ישראל שמושרשים בהעצמות, ובהם היא בחירת העצמות, ולכן יש בהם ענין הבחירה, לפי שנלקחים ממקום כזה שיש בו ענין הבחירה, כידוע שענין הבחירה הוא בהעצמות דוקא<sup data-n=\"507\">81</sup>.\nועפ\"ז י\"ל, שבפיסקא זו מדובר אודות כללות ההתהוות ותכליתה: ענין ההתהוות – נרמז בהתחלה בתואר \"מקום\". וכדי שתתמלא כוונת ותכלית ההתהוות צ\"ל כללות סדר העבודה \"שהוציאנו ממצרים וכו'\", עד להתכלית של כללות העבודה – \"ובנה לנו את בית הבחירה\", שרומז גם על ביהמ\"ק שבכאו\"א מישראל, כמ\"ש<sup data-n=\"508\">82</sup> \"ושכנתי בתוכם\", בתוך כל אחד ואחד<sup data-n=\"509\">83</sup>.\n*\n<b>יט</b>. גם מהפיסקא \"לפיכך\" והלאה לא היו מפסיקים. ויש לומרהטעם, שלא רצו להפסיק בהפרקים דהלל. וקרוב לודאי שזהו גם הטעם שלא היו מפסיקים בחצי' השני של ההגדה (לאחרי ברכת המזון).\n*\n<b>כ</b>. \"<i>לשנה הבאה בירושלים</i>\":\nבנוגע להסדר דמחשבה דיבור ומעשה – הרי הפירוש בזה הוא שכאשר ישנה המחשבה, דהיינו כוונה [וגם אם ישנם כאלה שאינם יודעים לכוין, הרי מסתמא ישנו מי שיכול להוציאם ידי חובתם], וישנו גם הדיבור – אזי בא גם המעשה, \"לשנה הבאה בירושלים\", בפועל ממש.\nומובן, שאין הכוונה שצריכים להמתין שנה שלימה, אלא ענין זה יכול להתחיל תיכף ומיד, ובמילא נהי' \"לשנה הבאה בירושלים\" (כנ\"ל ס\"ג).\n[כ\"ק אדמו\"ר שליט\"א צוה לנגן \"אני מאמין\". ואחרי שניגנו, אמר, שנוסף על ענין האמונה, צריך להיות גם ענין של מעשה, ולכן ינגנו \"ממצרים גאלתנו\", שזהו ענין שכבר הי' במעשה בפועל, וענין זה ימשיך גם את הגאולה העתידה – בפועל ממש].\n<b>כא</b>. בסידור של\"ה<sup data-n=\"510\">84</sup> איתא שצריכים לומר \"לשנה הבאה בירושלים\" ג' פעמים, דבתלתא זימני הוי חזקה<sup data-n=\"511\">85</sup>. אבל אדמו\"ר הזקן אינו מביא זה בסידורו, דס\"ל שאין צורך בענין של חזקה, וגם לולי החזקה יש בכחו ובבעלותו של יהודי לומר ולפעול שיהי' \"לשנה הבאה בירושלים\".\n[כ\"ק אדמו\"ר שליט\"א צוה שכולם יכריזו \"לשנה הבאה בירושלים\"].\n<b>כב</b>. \"לשנה הבאה בירושלים\" מכריזים שתי פעמים בשנה: בסיום וחותם יוהכ\"פ, ובליל פסח.\nוהנה, ליל הפסח הוא נעלה יותר ממוצאי יוהכ\"פ, כיון שפסח נקרא \"ליל שימורים\"<sup data-n=\"512\">86</sup>, שאז אין שליטה להשטן כו'<sup data-n=\"513\">87</sup>. ואע\"פ שגם ביוהכ\"פ אין שליטה להשטן, כדאיתא בגמרא<sup data-n=\"514\">88</sup> \"השטן בגימטריא תלת מאה ושתיןוארבעה הוי, תלת מאה ושתין וארבעה יומי אית לי' רשותא לאסטוני, ביומא דכיפורי לית לי' רשותא לאסטוני\", אבל אעפ\"כ, אין זה באופן ד\"שימורים\", ורק בפסח נאמר \"ליל שימורים\".\nוהענין בזה, שגם כאשר ישנים, ולא רק שינה דשמחת בית השואבה שהיא באופן ד\"מנמנמי אכתפא דהדדי\"<sup data-n=\"515\">89</sup>, \"נים ולא נים\"<sup data-n=\"516\">90</sup>, אלא שינה של ממש, ראש ורגל בהשוואה, הנה גם אז אין להתיירא מפני מזיקים כו', כיון שזהו \"ליל שימורים\".\nומובן שבשעה שאין מציאות של שטן ומזיקים כו' – אזי יהודי הוא בעה\"ב לומר ולפעול שיהי' \"לשנה הבאה בירושלים\"!\n[בסיום ההתוועדות אמר כ\"ק אדמו\"ר שליט\"א, שכל אלה הזקוקים לרפואה יכנסו אליו לחדרו, ונתן להם חתיכת מצה: \"מיכלא דאסוותא\"<sup data-n=\"517\">91</sup>].\n**********",[["427","1","לר\"ש מרשקוב – קודם קידוש."],["428","2","משנת חסידים מסכת סדר ליל פסח פ\"ה מ\"ב. סידור האריז\"ל בהגדה."],["429","3","ויגש מז, כג. וראה מ\"ח שם מ\"ג. סידור האריז\"ל שם. פע\"ח שער חהמ\"צ פ\"ז."],["430","4","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011098\" data-slug=\"likkutei-sichot\" data-id=\"1300011098\">לקו\"ש ח\"א ס\"ע 98</a> ואילך. וש\"נ."],["431","5","ל\"ת להאריז\"ל ישעי' נט, כ. ועוד."],["432","6","לשון אדמו\"ר הזקן ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא פכ\"ט (לו, ב</a>)."],["433","7","ראה \"לוח התיקון\" לתניא פ\"ז, ובטעמי המצוות להרח\"ו ס\"פ בראשית."],["434","8","תניא שם."],["435","9","חסר כמה תיבות (המו\"ל)."],["436","10","נוסח הגדה של פסח, מפסחים קטז, ב (במשנה)."],["437","11","הוספת אדה\"ז בתניא רפמ\"ז."],["438","12","סימן ד."],["439","13","שיחת ליל א' דחה\"פ תש\"ה בתחלתה (סה\"ש תש\"ה ריש ע' 83)."],["440","14","הגדה של פסח שמחת הרגל (לחיד\"א) – הובא בהגש\"פ עם לקוטי טעמים כו' ע' טו."],["441","15","נסמנו בהגש\"פ הנ\"ל שם."],["442","16","שמו\"ר פ\"ה, טז. הובא בפרש\"י עה\"ת שמות ה, ד."],["443","17","ראה הנסמן בתו\"ש שמות א, יג (אות קלד-קלו)."],["444","18","הליכות עולם – הובא בסה\"ד בערכו (אות ב)."],["445","19","פס\"ר ופסיקתא דר\"כ פ' פרה. במדב\"ר פי\"ט, ז. תנחומא חוקת ח."],["446","20","ריש מס' פרה."],["447","21","יוחסין ועש\"מ (להרמ\"ע מפאנו) מאמר חקו\"ד פט\"ו – הובאו בקונטרס בית צדיק בהקדמת הרד\"ל לפרדר\"א (אות א)."],["448","22","ערכין יא, ב."],["449","23","מע\"ש פ\"ה מ\"ט."],["450","24","ברכות כז, סע\"ב."],["451","25","ראה סדה\"ד בערכו."],["452","26","שבועות לט, סע\"א. סנהדרין כז, סע\"ב."],["453","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380444\" data-slug=\"likkutei-torah\" data-id=\"4001380444\">לקו\"ת בהעלותך לג, ג</a>. וראה גם שם שה\"ש לה, ד."],["454","28","ראה גם סה\"ש תש\"א ע' 144."],["455","29","ראה (לדוגמא) ברכות ז, א. יו\"ד, רע\"א. ועוד. הנסמן בתורת מנחם – התוועדויות ח\"ז ס\"ע 75."],["456","30","יש גורסים: \"התלמידים\", אבל גירסת אדה\"ז בהגדה היא: \"תלמידיהם\"."],["457","31","ראה גם שיחת ליל ב' דחה\"פ תרצ\"ז ס\"ז (סה\"ש תרצ\"ז ע' 225)."],["458","32","תענית ז, א. וש\"נ."],["459","33","זכרי' יג, ב."],["460","34","ח\"ב קפג, ב."],["461","35","בע\"י ברכות יב, ב."],["462","36","ראה סה\"מ תש\"ח ע' 164 ואילך."],["463","37","ברכות שם."],["464","38","ירמי' כג, ז-ח."],["465","39","מיכה ז, טו."],["466","40","קטעים משיחה זו – נכללו ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011261\" data-slug=\"likkutei-sichot\" data-id=\"1300011261\">לקו\"ש</a> לקו\"ש ח\"א ע' 247 ואילך."],["467","41","לשון אדמו\"ר הזקן ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא ספמ\"ו</a>. ועוד."],["468","42","ראה תניא אגה\"ק רסכ\"ט – בשם האריז\"ל, הנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181201\" data-slug=\"likkutei-sichot\" data-id=\"1300181201\">לקו\"ש חי\"ח ע' 192</a> הערה 55 ובשוה\"ג."],["469","43","ראה אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ד ע' תקמז (נעתק ב\"היום יום\" כא סיון). וראה שם ע' שפד (נעתק ב\"היום יום\" כה תמוז). ועוד."],["470","44","תמיד לב, א."],["471","45","<a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא פמ\"ג (סא, ב</a>)."],["472","46","פל\"ה בהגהה."],["473","47","שמות עא, ב ואילך."],["474","48","גיטין יג, א. וש\"נ."],["475","49","בשמונה פרקים שלו פ\"ו."],["476","50","תו\"כ ופרש\"י קדושים כ, כו."],["477","51","אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ג ע' תנד."],["478","52","לך לך יז, יז."],["479","53","פע\"ח שבהערה 3. ועוד."],["480","54","ראה יל\"ש יתרו רמז רפו. ועוד."],["481","55","יתרו כ, ב."],["482","56","מגלה עמוקות אופן קפו."],["483","57","ראה זח\"ג עא, א. תקו\"ז תכ\"ה. שו\"ת\nנודע ביהודה מהד\"ת או\"ח סק\"ט. אבנ\"ז יו\"ד ח\"ב סשע\"א."],["484","58","יהושע כד, ב."],["485","59","נדרים לב, רע\"ב."],["486","60","וירא כא, לג."],["487","61","סוטה יו\"ד, סע\"א ואילך."],["488","62","משלי כג, ה."],["489","63","ראה לקו\"ד ח\"א נ, א."],["490","64","ראה גם הגש\"פ עם לקוטי טעמים כו' ע' כא."],["491","65","מגילה כט, א."],["492","66","ראה לקו\"ש ח\"ג ע' 782. ועוד."],["493","67","קהלת ח, ד."],["494","68","ראה ב\"ר פמ\"ד, כב."],["495","69","אבות רפ\"ה."],["496","70","ויגש מו, ד."],["497","71","שמות א, כב."],["498","72","ראה גם הגש\"פ עם לקוטי טעמים כו' ע' כד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011113\" data-slug=\"likkutei-sichot\" data-id=\"1300011113\">לקו\"ש ח\"א ע' 113</a> ואילך. שיחת ליל ב' דחה\"פ תשי\"א סכ\"א (תורת מנחם – התוועדויות ח\"ג ע' 23 ואילך)."],["499","73","ספרי ופרש\"י עה\"פ ואתחנן ו, ז."],["500","74","ראה \"רשימות\" חוברת ה ע' 19 (וש\"נ): \"ליל ב' מבאר בהגדה\"."],["501","75","שיחת אחש\"פ תרצ\"ה סט\"ו (סה\"מ תשי\"א ע' 245)."],["502","76","\"היום יום\" כג חשון."],["503","77","ראה הגש\"פ עם לקוטי טעמים כו' ע' כח. וש\"נ."],["504","78","ראה \"רשימות\" חוברת לח ריש ע' 10. הגש\"פ שם. נת' בשיחת ליל א' דחה\"פ דאשתקד ס\"ה ואילך (תורת מנחם – התוועדויות ח\"ה ס\"ע 114 ואילך)."],["505","79","ב\"ר פס\"ח, ט."],["506","80","ראה תניא אגה\"ק ס\"כ (קל, סע\"א ואילך)."],["507","81","ראה סה\"מ מלוקט ח\"ה ע' ד. וש\"נ."],["508","82","תרומה כה, ח."],["509","83","ראה אלשיך עה\"פ. של\"ה סט, א. ועוד."],["510","84","הובא בהגש\"פ עם לקוטי טעמים כו' ע' נ."],["511","85","ב\"מ קו, רע\"ב. וש\"נ."],["512","86","בא יב, מב."],["513","87","ראה פסחים קט, סע\"ב. שו\"ע אדה\"ז או\"ח סו\"ס תפא."],["514","88","יומא כ, א. ועוד."],["515","89","סוכה נג, א."],["516","90","פסחים קכ, רע\"ב."],["517","91","ראה זהר שבהערה 34. שיחת ליל ב' דחה\"פ תש\"ב ס\"ו (סה\"ש תש\"ב ע' 94 ואילך) – נעתק (בקיצור) ב\"היום יום\" טו ניסן."]]],[1400140014,"(הנחה בלתי מוגה)\n<b>והחרים</b><sup data-n=\"518\">1</sup> הוי' את לשון ים מצרים והניף ידו על הנהר גו' והכהו לשבעה נחלים גו'<sup data-n=\"519\">2</sup>. הנה כתוב זה קאי על הגאולה העתידה להיות במהרה בימינו ע\"י משיח צדקנו, כמ\"ש בתחילת הענין<sup data-n=\"520\">3</sup> ויצא חוטר מגזע ישי וגו'. ותוכן הענין הוא, דכשם שכללות הגאולה דלעתיד תהי' כמו הגאולה דיציאת מצרים, כמ\"ש<sup data-n=\"521\">4</sup> כימי צאתך מארץ מצרים אראנו נפלאות, כמו כן גם הפרטים שהיו ביציאת מצרים יהיו ג\"כ בהגאולה דלעתיד, וזהו\"ע הבקיעה דלעתיד שהוא כמו קריעת ים סוף ביציאת מצרים, וכמו שמסיים בכתוב<sup data-n=\"522\">5</sup> כאשר היתה לישראל ביום עלותו מארץ מצרים. וצריך להבין, דמאחר שהבקיעה שתהי' בהגאולה דלעתיד היא דוגמת קריעת ים סוף שהיתה ביציאת מצרים, מהו טעם השינויים שביניהם, החל משינוי הא', שביציאת מצרים היתה הבקיעה רק בים, ולעתיד תהי' הבקיעה בים (והחרים הוי' את לשון ים מצרים) וגם בנהר (והניף ידו על הנהר). והנה, בפשטות אפ\"ל הטעם, שביציאת מצרים עברו רק דרך ים סוף, ולכן הוצרכה להיות הבקיעה רק בים סוף, ולעתיד שיצאו מאשור וממצרים ומפתרוס גו' ומאיי הים<sup data-n=\"523\">6</sup>, יצטרכו לעבור גם דרך הנהר, ולכן תצטרך להיות הבקיעה בים ובנהר<sup data-n=\"524\">7</sup>. אמנם, לבד זאת שטעם זה אינו ביאור על שינוי הלשון בכתוב והחרים גו' והניף גו', שבים נאמר הלשון והחרים, שיש בזה ב' פירושים<sup data-n=\"525\">8</sup>, פירוש הא', והחרים מלשון יובש<sup data-n=\"526\">9</sup>, ופירוש הב', והחרים מלשון חרם<sup data-n=\"527\">10</sup> גו' להוי'<sup data-n=\"528\">11</sup>, ובנהר נאמר הלשון והניף, הנה עוד זאת, הרי ידוע שקריעת ים סוף לא היתה בשביל הצלתבנ\"י מהמצריים, שהרי הרבה דרכים למקום, ובפרט ע\"פ מ\"ש בתוספות<sup data-n=\"529\">12</sup> שבאותו צד שירדו באותו צד עלו, דמזה מוכרח שקריעת ים סוף לא היתה בשביל ההצלה, אלא קריעת ים סוף הוא אחד מהענינים הרוחניים שהוצרכו להיות ביציאת מצרים [ובזה יובן מ\"ש (בהגדה) אילו קרע לנו את הים ולא העבירנו כו' דיינו, לפי שהענין דקריעת ים סוף לא הי' בשביל ההצלה, אלא הוא ענין רוחני שהוצרך להיות ביציאת מצרים]. ועפ\"ז אינו מובן טעם השינוי שביציאת מצרים היתה הבקיעה רק בים, ולעתיד תהי' הבקיעה בים ובנהר. ועוד שינוי בין הבקיעה דיציאת מצרים להבקיעה דלעתיד, שבקריעת ים סוף נאמר<sup data-n=\"530\">13</sup> הרם את מטך ונטה את ידך על הים ובקעהו, שהבקיעה היתה (ע\"י היד, אבל) גם ע\"י מטה, משא\"כ בהבקיעה לעתיד נאמר והניף ידו על הנהר, שלא תהי' ע\"י מטה, כי אם ע\"י היד בלבד<sup data-n=\"531\">14</sup>.\nב) <b>ולהבין</b> זה צריך להקדים תחילה הענין דקריעת ים סוף, היינו לשם מה הוצרך להיות קריעת ים סוף ביציאת מצרים<sup data-n=\"532\">15</sup>. והענין בזה, דהנה יציאת מצרים קשורה עם מתן תורה, כמ\"ש<sup data-n=\"533\">16</sup> בהוציאך את העם ממצרים תעבדון את האלקים על ההר הזה, וקריעת ים סוף לא הי' בשביל הענין דיציאת מצרים עצמו (שהרי קריעת ים סוף הי' אחרי יציאת מצרים), אלא בשביל הענין דמ\"ת<sup data-n=\"534\">17</sup>. ולכן, כדי להבין הענין דקריעת ים סוף שהי' בשביל מ\"ת, יש להקדים תחילה הבנת הענין דמ\"ת.\n<b>והענין</b> בזה, דהנה ידוע שההתחדשות (דער אויפטו) דמ\"ת הוא שנעשה ההתחברות דגשמיות וחומריות עם רוחניות, שהרי קודם מ\"ת לא הי' קשור וחבור דרוחניות עם גשמיות, כדאיתא במדרש<sup data-n=\"535\">18</sup> משל למלך שגזר ואמר בני רומי לא ירדו לסוריא ובני סוריא לא יעלו לרומי כך כשברא הקב\"ה את העולם גזר ואמר השמים שמים להוי' והארץ נתן לבני אדם<sup data-n=\"536\">19</sup>, כשבקש ליתן התורה בטל גזירה ראשונה ואמר התחתונים יעלו לעליונים והעליונים ירדו לתחתונים, ואני המתחיל, שנאמר<sup data-n=\"537\">20</sup> וירד הוי' על הר סיני, וכתיב<sup data-n=\"538\">21</sup> ואל משה אמר עלה אל האלקים. ואף שגם קודםמ\"ת, היינו בתחילת הבריאה, היתה ההתקשרות דרוחניות עם גשמיות, כמודגש בפרט בהאדם (שהוא עולם קטן<sup data-n=\"539\">22</sup>) בהתקשרות הנשמה בגוף בכח המפליא לעשות<sup data-n=\"540\">23</sup>, מ\"מ, קודם מ\"ת, גם כאשר הרוחני הי' בהגשמי ופעל בו, לא היתה הפעולה בגוף הגשמי, היינו שהגשמי נשאר בגשמיותו כמו שהי' קודם, ובמ\"ת נתחדש שפעולת הרוחני בהגשמי היא בהגשמי עצמו. וזהו שאמרו חז\"ל<sup data-n=\"541\">24</sup> כל המצוות שעשו לפניך האבות ריחות היו אבל אנו שמן תורק שמך, והיינו, דמעשה האבות לא הי' בגוף הגשמי, וכמו ריח שנרגש רק בשעת מעשה, אבל אח\"כ כאשר לוקחים את הדבר לא נשאר ממנו מאומה, והוא לפי שגם בשעת מעשה הי' רק ריח בלבד, שאינו מציאות דבר ממשי, אבל אנו, לאחר מ\"ת, שמן תורק שמך, היינו שהפעולה היא בגוף הגשמי, דמעשה המצוות לאחר מ\"ת פועל בירור זיכוך וקדושה בגוף הדברים הגשמיים שבהם נעשית המצוה, ולכן נשאר ענין זה גם אח\"כ, שזהו דין עפ\"י נגלה שבמעשה המצוות נשאר קדושה בהדבר גם אחר מעשה המצוה<sup data-n=\"542\">25</sup>. וכ\"ז הוא לאחר מ\"ת דוקא, שהרוחני נשאר בהגשמי גם אחר מעשה המצוה, ומכ\"ש בעת מעשה המצוה, משא\"כ בהמצוות שעשו לפניך האבות, אף שהיו אותם הענינים שניתנו אח\"כ במ\"ת, מ\"מ, ריחות היו, שאחר עשיית המצוה לא נשאר שום דבר, וגם בעת עשיית המצוה לא היתה הפעולה בגוף הדבר הגשמי.\n<b>ופנימיות</b> הדברים בזה, דקודם מ\"ת היו אצילות ובי\"ע ב' דברים נבדלים, והיינו שעולמות בי\"ע היו כביכול כמו דבר נפרד, להיות אשר בבי\"ע אין זה באופן דאיהו<sup data-n=\"543\">26</sup> וחיוהי וגרמוהי חד<sup data-n=\"544\">27</sup>, ועוד זאת שאפילו עולם הבריאה הוא התחלה למציאות של רע, משא\"כ באצילות נאמר<sup data-n=\"545\">28</sup> לא יגורך רע, ולכן לא הי' אפשר להיות חיבור אצילות ובי\"ע. וההתחדשות דמ\"ת הוא שיהי' חיבור אצילות ובי\"ע, והיינו, דעם היות שגם לאחר מ\"ת נשארים עולמות בי\"ע כמו שהם, שאפילו עולם הבריאה הוא התחלה למציאות הרע, מ\"מ, ההתחדשות דמ\"ת היא אשר לאט לאט יומשך אצילות בבי\"ע ובי\"ע יתעלה באצילות, עד שעולמות בי\"ע ישתוו להיות כמו עולם האצילות.ג) <b>והנה</b> כדי לפעול ההתחדשות דחיבור אצילות ובי\"ע במ\"ת, הוצרך להיות גם קודם מ\"ת החיבור דאצילות ובי\"ע לפי שעה. ובהקדים דתורה היא מלשון הוראה<sup data-n=\"546\">29</sup>, היינו שהתורה היא הוראה בחיים משעה שנולד עד ביאת המשיח, והסדר בהוראה הוא שבתחילה נעשה הדבר לפי שעה, ואח\"כ נעשה בתמידות, וכמו בחינוך דקטן כו', וכמו\"כ גם בחנוכת המזבח, שהקריבו קרבנות מיוחדים שלא היו אח\"כ, היינו, שהיו גילוים ואורות נעלים לפי שעה, שעי\"ז יוכל להיות אח\"כ הקרבת הקרבנות (גשמיים) תמידין כסדרן<sup data-n=\"547\">30</sup>. וכמו\"כ בנוגע למ\"ת שנתחדש חיבור אצילות ובי\"ע, שקודם מ\"ת הוצרך להיות ענין זה לפי שעה. וזהו ענין קריעת ים סוף, שהו\"ע חיבור אצילות ובי\"ע לפי שעה, כהכנה לחיבור אצילות ובי\"ע שנתחדש במ\"ת.\n<b>והענין</b> בזה, דהנה ים סוף הוא בחינת מלכות דאצילות, שהוא סוף כל דרגין דאצילות, וההפסק בין אצילות ובי\"ע הוא בבחינת מלכות דאצילות, ששם נפסק עולם האצילות ומתחילים עולמות בי\"ע, ולכן נקראת בחינת המלכות ים וארץ<sup data-n=\"548\">31</sup>. והנה, מלכות היא דיבור<sup data-n=\"549\">32</sup>, וענין הדיבור הוא גילוי לזולתו, דכאשר האדם רוצה לגלות לזולתו השכל וההרגש שלו, היינו בחינת מוחין ומדות, אזי המוחין ומדות מתלבשים באותיות הדיבור. אמנם, כללות הגילוי לזולתו, היינו מה שהזולת מקבל, הוא חיצוניות בלבד, וזהו שאמרו חז\"ל<sup data-n=\"550\">33</sup> עד ארבעין שנין לא קאים אינש אדעתא דרבי', היינו, דעם היות שהרב מצדו רוצה לגלות לו, ולכן מסדר את הענין שכלי באותיות הדיבור שמכילים כל מה שרוצה לגלות לו, וכן התלמיד מצדו הוא בתנועה של ביטול אל הרב, ששומע את דברי הרב כמו שתלמיד צריך לשמוע, באופן ששפתותיו נוטפות מור<sup data-n=\"551\">34</sup>, מ\"מ, מה שמקבל הוא רק חיצוניות בלבד, שצריך להיות משך זמן עד דקאים אדעתא דרבי', ועד הזמן ההוא לא קאים אלא על החיצוניות בלבד. וכן הוא גם בבחינת מלכות דאצילות, דמלכות לית לה מגרמה כלום, ונקראת כנסת ישראל ע\"ש שכונסת ואוספת כל הגילוים בתוכה, וממנה נמשך לבי\"ע, אמנם, מה שנמשך בבי\"ע הוא רק חיצוניות בלבד, דאף שבהעלםיש (בה) כל הפנימיות, מ\"מ, מה שבא בגילוי מאצילות בבי\"ע הוא רק החיצוניות בלבד, ואילו הפנימיות נשארת בהעלם. וכמו\"כ הוא מצד עולם הבריאה כו'. וכיון שההתחדשות דמ\"ת הוא שיהי' בבי\"ע גם הפנימיות דאצילות, הנה קודם מ\"ת הוצרך להיות קריעת ים סוף, שהו\"ע החיבור דאצילות ובי\"ע, כי קריעת הים, היינו קריעת ההעלם, שעי\"ז נעשה החיבור דאצילות ובי\"ע. וחיבור זה נעשה בב' האופנים, אופן הא', שאצילות נמשך בבי\"ע, ואופן הב', שבי\"ע נתעלה באצילות, כמרומז בב' הלשונות שמצינו בקריעת ים סוף, דהנה כתיב<sup data-n=\"552\">35</sup> הפך ים ליבשה, היינו, שעיקר הנס הי' שנהפך הים ליבשה, שבחינת ההעלם בא בגילוי, וכתיב<sup data-n=\"553\">36</sup> ויבואו בני ישראל בתוך הים ביבשה, היינו, שעיקר הרבותא היא מה שבתוך הים הלכו ביבשה, שבתוך ההעלם עצמו הי' בחינת גילוי (כמבואר בזהר<sup data-n=\"554\">37</sup> וכתבי האריז\"ל<sup data-n=\"555\">38</sup>), ומבואר בחסידות<sup data-n=\"556\">39</sup> דמר אמר חדא ומר אמר חדא ולא פליגי, כיון שהחיבור דאצילות ובי\"ע הי' בשני אופנים, שאצילות נמשך בבי\"ע (הפך ים ליבשה, שבחינת ההעלם בא בגילוי), ובי\"ע נתעלה באצילות (שבתוך הים הלכו ביבשה, שבתוך ההעלם עצמו הי' בחינת גילוי). אמנם, ההתחברות דאצילות ובי\"ע בקריעת ים סוף היתה רק לפי שעה, ולכן אף שראתה שפחה על הים מה שלא ראה רבן של נביאים<sup data-n=\"557\">40</sup>, ראתה דייקא בראי' חושיית, מ\"מ נשארה אח\"כ שפחה, לפי שהגילוי בקריעת ים סוף הי' רק לפי שעה. אך ע\"י ההתחברות דאצילות ובי\"ע לפי שעה בקריעת ים סוף, נעשה במ\"ת החיבור דאצילות ובי\"ע בתמידות ובתדירות.\nד) <b>והנה</b> כיון שההתחדשות דמ\"ת הוא החיבור דאצילות ובי\"ע עד אשר לאט לאט יהי' בי\"ע כמו אצילות כנ\"ל, לכן הנה עיקר העבודה היא עבודת הבירורים לברר ולזכך את עולמות בי\"ע עד שיהיו כמו אצילות. ולכן, הנה עיקר לימוד התורה בזמן הזה הוא נגלה דתורה, בחינת עץ הדעת טוב ורע<sup data-n=\"558\">41</sup>, לפי שעל ידה הוא הבירור דטו\"ר, ולכן נתלבשה התורה גם בטענות של שקר כדי לברר אותם, וזהו שעיקר הלימוד עכשיו הוא נגלה דתורה, בשביל הבירורים, שיבררו ויזככו אתהעולמות בי\"ע עד שיהיו כמו עולם האצילות. אבל פנימיות התורה, אילנא דחיי&lt;41&gt;, תתגלה בביאת המשיח דוקא<sup data-n=\"559\">42</sup>, שזהו שטעמי תורה וטעמי מצוות לא נתגלו<sup data-n=\"560\">43</sup>, והתגלותן תהי' לעתיד דוקא.\n<b>אך</b> צריך להבין<sup data-n=\"561\">44</sup> מ\"ש שטעמי המצוות לא נתגלו עכשיו, דלכאורה, הרי ידוע שבמתן תורה ניתנה גם פנימיות התורה, וכדאיתא בחסידות<sup data-n=\"562\">45</sup> שמתן תורה לא יהי' עוד הפעם, והוא לפי שגם פנימיות התורה ניתנה בשעת מ\"ת, וכמו\"כ הרי רע\"ק רשב\"י והאריז\"ל והבעש\"ט והרביים אחריו למדו וגילו פנימיות התורה, ומהו הפירוש שטעמי המצוות לא נתגלו עכשיו. ועם היות שמזה גופא שעכשיו עיקר הלימוד הוא בגליא דתורה בשביל הבירורים כנ\"ל, מובן, שפנימיות התורה לא נתגלה עכשיו, שהרי איתא באגה\"ק<sup data-n=\"563\">46</sup> שכשיושלם בירור הניצוצות ויופרד הרע מן הטוב ולא שלטא אילנא דטוב ורע אזי לא יהי' עסק התורה והמצוות לברר בירורים כי אם לייחד יחודים עליונים כו' ע\"י פנימיות התורה דוקא, וא\"כ, כיון שעכשיו צריך ללימוד הנגלה בשביל הבירורים, עכצ\"ל שלא נתגלה עדיין פנימיות התורה, מ\"מ, עדיין אינו מובן, שהרי גם עכשיו יש ההתגלות דפנימיות התורה כנ\"ל, ואף שלא יש השגת המהות, הרי מ\"מ יש ידיעת המציאות עכ\"פ, וא\"כ מהו הענין שטעמי מצוות לא נתגלו עכשיו, ויתגלו בביאת המשיח דוקא.\nה) <b>ויובן</b><sup data-n=\"564\">47</sup> ע\"פ המבואר בחסידות<sup data-n=\"565\">48</sup> בענין שמשיח ילמד תורה עם כל ישראל, שאין זה הלימוד דנגלה דתורה, שהרי אז בתחה\"מ יקומו תנאים ואמוראים, האבות ומשה רבנו, שיודעים את כל התורה כולה, וא\"כ אי אפשר לומר דזה שמשיח ילמד תורה עם כל ישראל הוא נגלה דתורה, מאחר שהיו וישנם כאלו שיודעים את כל התורה כולה. ועוד זאת, דאיך אפשר להיות שאיש אחד ילמד עם ריבוי אלפים ורבבות. ובהכרח לומר, דזה שמשיח ילמד תורה עם כל ישראל הוא הלימודדפנימיות התורה. ועדיין צריך להבין איך אפשר להיות שאיש אחד ילמד עם ריבוי עצום של אנשים. אך הענין הוא, דהנה יש ב' אופני לימוד, מלמעלה למטה ומלמטה למעלה. הלימוד מלמטה למעלה הוא ענין הבנה והשגה, שמבין ומשיג את כל הענינים שיכול לתופסם, עד אשר בא להענינים שבהם צ\"ל ענין של הפשטה כו'. ולימוד זה, מלמטה למעלה, הוא בחינת שמיעה, שעז\"נ<sup data-n=\"566\">49</sup> אינו דומה שמיעה לראי'. והענין בזה, דכאשר שומע את הדבר, הנה אף שסיפרו לו את הדבר עם כל הפרטים, מ\"מ, התפיסא שלו בהדבר אינה אלא מציאות הדבר, ולא מהות הדבר, וכמו\"כ מה שהדבר תופס בו, אין זה בעצמותו, שההתפעלות שיש בשמיעה אינו דומה לההתפעלות דראי', היינו שההתפעלות דשמיעה אינה התפעלות עצמית, לפי שהענין אינו תופס את העצם שלו, ועד אשר במשך הזמן יכולים לסתור ולהפריך מה ששמע, דאף ששמע זה מאיש אמת שסיפר לו מה שהוא בעצמו ראה ונתקבל אצלו הדבר, מ\"מ, במשך הזמן אפשר לסתור אצלו את הדבר, שיהיו לו ספיקות בהדבר, לפי שלא נתקבל בהעצם שלו. משא\"כ כאשר רואה את הדבר, אזי רואה את מהות הדבר, ובאופן שתופס את העצם שלו, דכיון שהוא רואה את עצם ומהות הדבר, לכן בא הדבר גם בהעצם שלו. והנה, יש עוד הפרש בין ראי' לשמיעה, דע\"י שמיעה תופס גם בריחוק, וע\"י ראי' תופס בקירוב דוקא, שזהו גם שע\"י שמיעה תופס בדבר רוחני (דאף שהתפיסה היא ע\"י חושים גשמיים, מ\"מ, עי\"ז תופס בדבר רוחני), משא\"כ ע\"י ראי' תופס בדבר גשמי דוקא. ושני החילוקים הם תלויים זה בזה, דלהיות שבשמיעה תופס רק במציאות הדבר, לכן אפשר להיות גם בריחוק, משא\"כ בראי' שתופס את מהות הדבר, צריך להיות בקירוב ובגשמיות דוקא. וכמו כן הוא גם בהשגה שהו\"ע של שמיעה בלבד, שהרי גם ראיית עין השכל היא באופן של שמיעה בלבד, שמשיג רק את מציאות הדבר (אבל במהות הדבר יש לו רק השערה בלבד), וההשגה בהדבר אינה אלא כפי מדידת והגבלת השכל, וכן בהאדם המשיג הרי זה באופן שאינו נתפס בעצמותו, והיינו שבהענינים שבו שהם למעלה ממדידה והגבלה, ומכ\"ש מהמדידה והגבלה דשכל, הנה באותם הענינים לא נתפס הדבר, ולכן ההתפעלות דהשגה אינה כמו ההתפעלות דראי', שההתפעלות דהשגה אינה התפעלות עצמית, ולגבי ענינים של פועל ממש מספיק גם השגה, לפי שגם ענין הפועל אינו עצמי. משא\"כ בראי' חושית, שהוא בחינת ראי' דחכמה,רואה את מהות הדבר, ונתפס בהעצם של האדם, וכמו שמצינו אצל האריז\"ל<sup data-n=\"567\">50</sup> שהי' מתנמנם וראה במשך שעה או שתים בריבוי גדול כ\"כ עד שבשביל לדבר בזה בהבנה והשגה הי' צריך ס' או פ' שנה (כב' הגירסאות שבזה<sup data-n=\"568\">51</sup>). ובזה יובן מה שבכתבי האריז\"ל ובחסידות מדובר גם בספירות ומדרגות נעלות שלא יכלו הנביאים להשיג במראה נבואתם, לפי שהשגת הנביאים היא ראי' חושית, וענין זה שייך עד לדרגא מסויימת כו', משא\"כ בהשגה, וכמו\"כ בראיית עין השכל שהוא רק השגת המציאות, אפשר להשיג במדריגות נעלות יותר, שזהו מה שחכם עדיף מנביא<sup data-n=\"569\">52</sup>. וזהו מה שמשיח ילמוד פנימיות התורה עם כל ישראל, דאף שגם עכשיו יש השגה כו', מ\"מ, בביאת המשיח תהי' הראי' באלקות, ראי' חושית, דמעין זה הי' גם קודם, אבל רק אצל יחידי סגולה, ואצלם גופא רק לפרקים רחוקים, אבל בביאת המשיח יתחדש ענין הראי' בתמידות אצל כל בנ\"י, שזהו מה שמשיח ילמוד תורה עם כל ישראל. וכיון שעצם הלימוד שמשיח ילמד עם כל ישראל יהי' נעלה יותר, יהי' גם אופן הלימוד באופן אחר לגמרי, ומשום זה יוכל ללמוד עם ריבוי עצום, ריבוי בכמות וריבוי באיכות.\nו) <b>ועפ\"ז</b> יובן שכשם שקודם מ\"ת הוצרך להיות קריעת ים סוף, כך צ\"ל דוגמתו קודם התגלות פנימיות התורה ע\"י משיח, אלא שיש שינוי בין הבקיעה שהי' ביציאת מצרים להבקיעה שתהי' בביאת המשיח, עלי' נאמר והחרים הוי' את לשון ים מצרים והניף את ידו על הנהר גו'. והענין בזה, כמשנת\"ל שקריעת ים סוף הי' הכנה למ\"ת שהוא חיבור אצילות ובי\"ע, וכיון שההעלם על האורות דאצילות הוא ים סוף, בחינת מלכות, לזאת הוצרך להיות קריעת ים סוף, קריעת ההעלם, להסיר את הצמצומים וההעלמות הפרסאות והמסכים. אבל בביאת המשיח שיהי' אז ענין הראי', שהוא גילוי העצם, הנה על זה יש גם ההעלם דנהר, ולכן צריך להיות גם בקיעת הנהר. דהנה, ים הוא דיבור, ונהר הוא מחשבה<sup data-n=\"570\">53</sup>, דים מקוי וקיימא<sup data-n=\"571\">54</sup>, ונהר הוא מלשון ונהרו אליו<sup data-n=\"572\">55</sup>, דזהו מה שהדיבורנקרא ים, לפי שדיבור הוא לזולתו ויש לו הפסק, ומחשבה נקראת נהר, לפי שמחשבה היא לעצמו ומשוטטת תמיד. והנה, אותיות המחשבה מעלימים על העצם, והיינו דלא רק אותיות הדיבור, אלא גם אותיות המחשבה, אותיות השכל כמו שהם בעילויים, הרי הם מעלימים על העצם. ולכן הנה קודם ביאת המשיח שיהי' אז גילוי העצם, יצטרך להיות מקודם ענין הבקיעה לא רק בהים, אלא גם בהנהר.\nז) <b>וזהו</b> והחרים הוי' את לשון ים מצרים, והחרים דייקא, שיש בזה ב' פירושים, מלשון יובש, ומלשון כל חרם להוי' (כנ\"ל). והענין בזה, דמצרים קאי על עולמות בי\"ע, שהם בחינת מיצרים וגבולים<sup data-n=\"573\">56</sup>. וכיון שקריעת הים הו\"ע חיבור אצילות ובי\"ע, הנה הסדר בזה שתחילה צריך להיות והחרים הוי' את לשון ים מצרים, והחרים מלשון יובש, עס זאָל ווערן אויס מציאות דבי\"ע, ואח\"כ יכול להיות הענין דוהחרים מלשון כל חרם להוי', שהו\"ע החיבור עם אצילות. וממשיך בכתוב והניף ידו על הנהר, ידו דייקא, דבקריעת ים סוף הי' ג\"כ ע\"י מטה, משא\"כ לעתיד תהי' הבקיעה רק ע\"י יד. והענין בזה, דאמרו רז\"ל<sup data-n=\"574\">57</sup> כשם שדרכו של כלב לרדות במקל כך הם (הרשעים) לוקים, וזהו שאמרו חז\"ל<sup data-n=\"575\">58</sup> לעולם ירגיז אדם יצ\"ט על יצה\"ר, ירגיז דוקא. וכיון שהצורך במקל הוא בשביל לרדות היצה\"ר כו', לכן הי' ענין זה ביציאת מצרים, משא\"כ לעתיד, שיעביר ה' את רוח הטומאה מן הארץ<sup data-n=\"576\">59</sup>, לא יהי' צורך במטה, אלא והניף ידו דוקא. וכללות הענין דוהניף ידו על הנהר, בקיעת הנהר, הוא כדי שיוכל להתחדש ענין הראי' שהוא גילוי העצם (כנ\"ל). וגם ענין זה יהי' בב' האופנים דמלמעלה למטה ומלמטה למעלה (ע\"ד האמור לעיל בקריעת ים סוף), דזהו מ\"ש והניף ידו על הנהר והכהו לשבעה נחלים, דנהר הוא המשכה מלמעלה למטה שהמים נגרים למטה, והכהו לשבעה נחלים הוא מלמטה למעלה (חסר קצת). וכל זה יתגלה ע\"י משיח דוקא. והענין בזה, דהנה כתיב<sup data-n=\"577\">60</sup> הנה ישכיל עבדי ירום ונשא וגבה מאד, שהוא למעלה מהאבות ומשה רבינו, ולמעלה גם מאדם הראשון<sup data-n=\"578\">61</sup>, שזהו\"ע גבה מאד, מאד אותיות אדם, אבל בצירוף אחר שמורה על בלי גבול. ובזה גופא יש ב' דעות<sup data-n=\"579\">62</sup>, דעה א', שהוא למעלה מאדה\"ר כמו שהי' אחרהחטא, ודעה הב' שהוא למעלה מאדה\"ר גם כמו שהי' קודם החטא. וכללות הענין בזה, שבביאת המשיח יהי' גילוי העצם, וזהו שנקרא מלך המשיח, דמשה נקרא משה רבינו, דאף שנאמר<sup data-n=\"580\">63</sup> ויהי בישורון מלך, ולפי דעה אחת<sup data-n=\"581\">64</sup> קאי על משה, מ\"מ, שם התואר שלו הוא רבינו, היינו, שעיקר ענינו שהוא רבינו, שענינו הוא לימוד, ענין ההשגה, משא\"כ משיח לא נקרא משיח רבינו, אלא מלך המשיח, דמלך הו\"ע רוממות ומקיף, כמ\"ש<sup data-n=\"582\">65</sup> שום תשים עליך מלך, שתהא אימתו עליך<sup data-n=\"583\">66</sup>, שהו\"ע מקיף, ולכן נקרא מלך המשיח, לפי שגם הלימוד דמשיח יהי' בבחינת ראי' שהו\"ע מקיף, אלא שמקיף זה יומשך גם בפנימיות, דזהו מ\"ש ישכיל, ישכיל הוא מלשון מפעיל, היינו שענין הראי' יפעול בכל ישראל. וזהו גם מ\"ש&lt;2&gt; והדריך בנעלים, דלהיות שכל ישראל יהי' אצלם בחינת הראי' שהוא גילוי העצם, לכן הנה כל ההשתלשלות ומלאכים כו', כל הענינים שמלבד בני ישראל, לא יוכלו לקבל מישראל כי אם ע\"י לבוש, שזהו\"ע הנעלים. וכל זה יהי' בגאולה העתידה להיות במהרה בימינו ע\"י משיח צדקנו, שיהי' אז ראי' חושית, כמ\"ש<sup data-n=\"584\">67</sup> וראו כל בשר (בשר דייקא) גו' כי פי הוי' דבר, שהוא כח הפועל בנפעל<sup data-n=\"585\">68</sup>, ויהי' התגלות העצמות למטה.\n**********",[["518","1","על העתק ההנחה שבספריית אגודת חסידי חב\"ד – ציין כ\"ק אדמו\"ר שליט\"א בכתי\"ק: \"<i>תרלא</i>\" (המשך והחרים תרל\"א)."],["519","2","ישעי' יא, טו."],["520","3","שם, א."],["521","4","מיכה ז, טו."],["522","5","ישעי' שם, טז."],["523","6","שם, יא."],["524","7","ראה גם פרש\"י שם, טו: \"והחרים – ליבשו כדי שיעברו בו גליות ישראל ממצרים, על הנהר – נהר פרת לעבור בו גליות אשור\"."],["525","8","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600191\" data-slug=\"or-hatorah-hb\" data-id=\"8316600191\">אוה\"ת נ\"ך</a> עה\"פ (ח\"א ע' קצא). המשך והחרים ע' א."],["526","9","תרגום יונתן ופרש\"י עה\"פ. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380149\" data-slug=\"likkutei-torah\" data-id=\"4001380149\">לקו\"ת צו יח, ב</a>."],["527","10","בהר כז, כח."],["528","11","מכלול ערך חרם. הובא באוה\"ת והמשך הנ\"ל שם."],["529","12","ערכין טו, א. וראה תו\"א בשלח סב, ב. סה\"מ תרל\"ה ח\"א ע' רנו. ד\"ה והניף תרח\"ץ (סה\"מ תרח\"ץ ע' קצט). ועוד."],["530","13","בשלח יד, כו."],["531","14","ראה המשך והחרים הנ\"ל ע' כה."],["532","15","ראה שער האמונה לאדמו\"ר האמצעי פנ\"ב (פג, ב ואילך). המשך הנ\"ל ס\"ע א ואילך."],["533","16","שמות ג, יב."],["534","17","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380144\" data-slug=\"likkutei-torah\" data-id=\"4001380144\">לקו\"ת צו יז, א</a>. שער האמונה שם."],["535","18","תנחומא וארא טו. שמו\"ר פי\"ב, ג."],["536","19","תהלים קטו, טז."],["537","20","יתרו יט, כ."],["538","21","משפטים כד, א."],["539","22","תנחומא פקודי ג. תקו\"ז תס\"ט (ק, ב. קא, א). וראה אדר\"נ ספל\"א."],["540","23","ראה רמ\"א או\"ח סוס\"ו."],["541","24","שהש\"ר פ\"א, ג (א). וראה סה\"מ תרס\"ב ע' רסה ואילך. תרע\"ח ע' קסד ואילך."],["542","25","ראה מגילה כו, ב. ועוד."],["543","26","תקו\"ז בהקדמה (ג, ב)."],["544","27","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370061\" data-slug=\"torah-or\" data-id=\"3901370061\">תו\"א וירא יג, ג</a>. ובכ\"מ."],["545","28","תהלים ה, ה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380322\" data-slug=\"likkutei-torah\" data-id=\"4001380322\">לקו\"ת במדבר ג, סע\"ג</a> ואילך."],["546","29","ראה רד\"ק לתהלים יט, ח. ס' השרשים להרד\"ק ערך ירה. וראה זח\"ג נג, ב."],["547","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380424\" data-slug=\"likkutei-torah\" data-id=\"4001380424\">לקו\"ת נשא כט, א</a>-ב."],["548","31","ראה סה\"מ תרל\"ה שם ע' רנט. תרח\"ץ שם ע' רא."],["549","32","בהבא לקמן – ראה שער האמונה פנ\"ג (פד, ב)."],["550","33","ראה ע\"ז ה, ב."],["551","34","שה\"ש ה, יג. וראה שבת ל, ב. וש\"נ."],["552","35","תהלים סו, ו."],["553","36","בשלח יד, כב."],["554","37","זח\"ב מח, ב."],["555","38","פע\"ח שער חג המצות פ\"ח."],["556","39","שער האמונה פנ\"ד (פו, ב ואילך). וראה סידור (עם דא\"ח) רפט, ד ואילך. מאמרי אדמו\"ר הזקן על פרשיות התורה ח\"א ע' רנח ואילך. מאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' ריב ואילך. ע' רנ ואילך."],["557","40","מכילתא בשלח טו, ב."],["558","41","ראה זח\"ג קכד, ב (ברע\"מ). תניא אגה\"ק סכ\"ו."],["559","42","רש\"י שה\"ש א, ב. אותיות דרע\"ק אות ז'."],["560","43","ראה תקו\"ז ת\"ע (קל, ב). תניא אגה\"ק סי\"ט (קכח, א)."],["561","44","בהבא לקמן – ראה שער האמונה פנ\"ח (צב, א ואילך)."],["562","45","ראה המשך תרס\"ו ע' כג. ע' תקמו. המשך תער\"ב ח\"א ע' שסו. סה\"מ תש\"ט ע' 57. ועוד."],["563","46","סכ\"ו (קמה, א)."],["564","47","בהבא לקמן – ראה שער האמונה פנ\"ט (צב, ב ואילך)."],["565","48","שער האמונה פנ\"ו ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380145\" data-slug=\"likkutei-torah\" data-id=\"4001380145\">לקו\"ת צו יז, ב</a>. מאמרי אדמו\"ר הזקן על פרשיות התורה ח\"א ע' רסד. ע' ער. סהמ\"צ להצ\"צ קיא, רע\"א. סה\"מ תרל\"ה שם ע' רסז ואילך. תרח\"ץ שם ע' ר ואילך. תרצ\"ט ע' 207. ובכ\"מ."],["566","49","ראה מכילתא יתרו יט, ט."],["567","50","ראה פע\"ח שער ק\"ש שעהמ\"ט פ\"א."],["568","51","ראה הערת כ\"ק אדמו\"ר שליט\"א בסה\"מ תש\"א ע' 133. מקומות שצויינו בהערה 48."],["569","52","ב\"ב יב, א. וראה תניא אגה\"ק סי\"ט (קכז, ב). לקו\"ת ויקרא ה, סע\"ד. מאמרי אדמו\"ר הזקן הקצרים ע' שנה. פירוש המילות לאדמו\"ר האמצעי פמ\"ב. ובכ\"מ."],["570","53","ראה סה\"מ תרל\"ה שם ע' רסח ואילך. תרח\"ץ שם ע' רא. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370038\" data-slug=\"torah-or\" data-id=\"3901370038\">תו\"א ט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת שה\"ש יז, ג</a>."],["571","54","ראה מקוואות פ\"ה מ\"ד. פרה פ\"ח מ\"ח."],["572","55","ישעי' ב, ב."],["573","56","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370224\" data-slug=\"torah-or\" data-id=\"3901370224\">תו\"א שמות מט, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370256\" data-slug=\"torah-or\" data-id=\"3901370256\">וארא נז, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">יתרו עא, ג</a>-ד."],["574","57","ראה שמו\"ר פ\"ט, ב."],["575","58","ברכות ה, א."],["576","59","ע\"פ זכרי' יג, ב."],["577","60","ישעי' נב, יג."],["578","61","ראה רמ\"ז לזח\"ג רס, ב. סה\"מ שצויינו בהערה הבאה."],["579","62","ראה סה\"מ תרל\"ה שם ע' רסו. תרח\"ץ שם ע' ר. ועוד."],["580","63","ברכה לג, ה."],["581","64","ראה רמב\"ן עה\"פ."],["582","65","שופטים יז, טו."],["583","66","סנהדרין כב, א. קידושין לב, ב."],["584","67","ישעי' מ, ה."],["585","68","ראה תו\"ח תצוה תפב, א ואילך."]]]]});
